window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0098", [{"word":"fracture","ipa_uk":"/ˈfræktʃə/","ipa_us":"/ˈfræktʃər/","definition_zh":"（使）断裂；裂缝；骨折；岩体破裂；分裂","definition_en":"to break or crack a hard solid, or the break itself, especially in bone or rock","core_image":"一块完好的石板被凿子沿着一条细线敲开，断面新鲜而锋利","scene":"地质实验室里，学生把岩芯夹在台钳上，准备沿薄弱面敲开。 A geologist uses a chisel to fracture the core sample and expose a fresh surface.","sceneCN":"这里 fracture 是动词「使断裂、敲裂」（第 1 个义项：把坚硬固体沿薄弱面破开）；句意为地质学家用凿子敲裂岩芯样品，露出新鲜断面。","pos":[{"tag":"v.","zh":"使断裂；敲裂；使骨折；使分裂"},{"tag":"n.","zh":"裂缝；断裂；骨折；岩体破裂"}],"collocations":[{"phrase":"fracture a bone","zh":"使骨头骨折"},{"phrase":"hairline fracture","zh":"发丝般细的裂缝；细微骨折"},{"phrase":"stress fracture","zh":"应力性骨折"},{"phrase":"fracture zone","zh":"断裂带"},{"phrase":"fracture the surface","zh":"使表面破裂"},{"phrase":"fracture along lines","zh":"沿分界线分裂"}],"forms":[{"label":"三单（he/she/it）","form":"fractures"},{"label":"过去式","form":"fractured"},{"label":"过去分词","form":"fractured"},{"label":"现在分词","form":"fracturing"},{"label":"名词复数","form":"fractures"},{"label":"形容词（断裂的）","form":"fractured"}],"derivatives":[{"word":"fractured","pos":"adj.","zh":"断裂的；分裂的；支离破碎的"},{"word":"fracturing","pos":"n.","zh":"破裂；压裂作业"},{"word":"fraction","pos":"n.","zh":"分数；小部分（同出 frangere，但语义已分流）"},{"word":"fragment","pos":"n.","zh":"碎片；片段（同出 frangere 的另一支）"},{"word":"fragile","pos":"adj.","zh":"易碎的；脆弱的（同出 frangere）"},{"word":"refract","pos":"v.","zh":"使折射（re- 加 frangere，指光线折断）"}],"senses":[{"no":"01","title":"Break a hard solid on purpose","titleCN":"使坚硬固体断裂","definition":"to break or crack a hard material such as rock, metal or glass","definitionCN":"使岩石、金属、玻璃等坚硬材料破裂或出现裂缝","example":"A geologist uses a chisel to fracture the core sample.","exampleCN":"地质学家用凿子敲裂岩芯样品。","why":"fracture comes from Latin fractura, a breaking, from frangere, to break; the verb is the act that produces a fractura.","whyCN":"fracture 来自拉丁 fractura「断裂」，源自动词 frangere「打破」；动词义就是产生一道断裂的动作。"},{"no":"02","title":"The crack that results","titleCN":"断裂后留下的裂缝","definition":"a crack or line of breakage in a solid object","definitionCN":"固体物件上出现的裂缝或断线","example":"A hairline fracture ran across the marble slab.","exampleCN":"一条发丝般的细裂缝横过大理石板。","why":"Latin fractura named both the act and its result, and English kept the same double life in one noun.","whyCN":"拉丁 fractura 同时指动作与结果，英语把这个双重身份原样保留在同一个名词里。"},{"no":"03","title":"Break a bone","titleCN":"使骨头骨折","definition":"to crack or break a bone in the body","definitionCN":"使身体中的骨头裂开或折断","example":"He fractured his wrist when he fell off the ladder.","exampleCN":"他从梯子上摔下来，手腕骨折了。","why":"a bone is the hardest solid in the body, so the general sense of breaking a hard thing settled naturally on bone.","whyCN":"骨头是身体里最硬的固体，因此「敲断硬物」的一般义自然落在骨折上。"},{"no":"04","title":"A break in the rock mass","titleCN":"岩体中的破裂面","definition":"a planar break through rock along which the two sides have moved or can move","definitionCN":"贯穿岩层、两侧已发生或可能发生位移的破裂面","example":"The fault is a fracture that has slipped many times.","exampleCN":"这条断层是一条多次滑动的破裂面。","why":"geology took the everyday noun and made it precise: a fracture is any break, a fault is one that has actually slipped.","whyCN":"地质学把日常名词精确化：fracture 泛指破裂，fault 专指真正发生过滑动的那一条。"},{"no":"05","title":"Split a group into camps","titleCN":"使团体分裂成对立阵营","definition":"to divide a group, party or alliance into opposing parts","definitionCN":"使团体、政党或联盟分裂为对立的几部分","example":"The dispute fractured the alliance into three camps.","exampleCN":"这场争端把联盟分裂成三个阵营。","why":"the image of a solid breaking into pieces was transferred from stone to social bodies, which also lose their wholeness.","whyCN":"固体碎成数块的意象被移用到社会群体上，因为群体同样会失去完整。"},{"no":"06","title":"A split in unity or agreement","titleCN":"统一或共识上的裂口","definition":"a division or breach in something previously united, such as trust or consensus","definitionCN":"原本统一之物（如信任或共识）出现的分裂或缺口","example":"The report exposed a fracture in the coalition's common position.","exampleCN":"这份报告暴露出联盟共同立场上的一道裂口。","why":"the noun sense extends the physical crack to anything that can no longer be described as one piece.","whyCN":"名词义把物理裂缝扩展到一切不再能被称作「一整块」的事物。"},{"no":"07","title":"The way a mineral breaks","titleCN":"矿物断口的形态","definition":"the characteristic surface shape a mineral shows when it breaks other than along cleavage planes","definitionCN":"矿物不沿解理面断开时所呈现的特征断面形态","example":"Quartz shows a conchoidal fracture rather than flat cleavage.","exampleCN":"石英呈现贝壳状断口，而不是平整的解理面。","why":"mineralogy needed a word for the surface left by breaking, and fracture already meant exactly that result.","whyCN":"矿物学需要一个词指断裂留下的表面，而 fracture 本来就表示这个结果。"},{"no":"08","title":"Break the continuity of something abstract","titleCN":"抽象义：打断某种连续性","definition":"to break the continuity or smooth working of a system, narrative or relationship","definitionCN":"打断系统、叙事或关系的连续性或顺畅运转","example":"One missing shipment can fracture a delicate supply chain.","exampleCN":"一次缺货就可能打断一条脆弱的供应链。","why":"the abstract sense keeps the core gesture: something that was continuous is now interrupted by a break.","whyCN":"抽象义保留核心动作：原本连续的东西，如今被一道断口打断。"}],"etymology":{"intro":{"en":"Fracture comes from Latin fractura, a breaking, from the verb frangere, to break, whose past participle is fractus. The word entered English in the fifteenth century, first as the medical name for a broken bone.","cn":"fracture 来自拉丁 fractura「断裂」，出自动词 frangere「打破」，其过去分词为 fractus。该词于 15 世纪进入英语，最初是骨折的医学名称。"},"items":[{"era":"LATIN FRANGERE","en":"Frangere meant to break, shatter or smash. Its past participle fractus supplied the stem frac- seen in fracture, fraction and fragment.","cn":"frangere 意为「打破、击碎、砸碎」。其过去分词 fractus 提供了 fracture、fraction、fragment 中所见的 frac- 词干。"},{"era":"LATIN FRACTURA","en":"Fractura was the noun of result, a breaking or the breach produced by it, used for broken bones as well as broken objects.","cn":"fractura 是结果名词，指「断裂」或断裂造成的破口，既用于断骨，也用于破碎的物件。"},{"era":"MEDICAL ENGLISH","en":"English took fracture in the fifteenth century as a term for a broken bone, alongside the older verb break.","cn":"英语在 15 世纪借入 fracture，作为骨折的术语，与更古老的动词 break 并存。"},{"era":"GEOLOGY AND ENGINEERING","en":"From the eighteenth century the word was applied to rock masses and to manufactured materials, where a fracture is a plane of breakage.","cn":"从 18 世纪起，该词被用于岩体与人工材料，其中 fracture 指一个破裂面。"},{"era":"FIGURATIVE SPLIT","en":"In modern usage a society, party or narrative can be fractured, extending the stone image to anything that loses its wholeness.","cn":"在现代用法中，社会、政党或叙事都可以被 fracture，把石头的意象扩展到一切失去完整性的东西。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin only): the link of frangere to a reconstructed Indo-European root for breaking is a standard reconstruction, not a recorded form; the first date of the geological sense is approximate.","cn":"来源不确定（仅更深词源）：frangere 与重构的印欧语「打破」词根之间的联系属于标准重构，并非有记录的形式；地质义的首见年代为约数。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin breaking stock; group two holds near neighbours that also describe damage or division.","cn":"第一组是同出拉丁「打破」词干的词；第二组是同样表示损坏或分裂的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fractured","ipa":"/ˈfræktʃəd/","tag":"same word, adjective","definition":"The past participle used as an adjective: cracked, split or disjointed, as in a fractured skull or a fractured story.","definitionCN":"本词的过去分词作形容词：裂开的、分裂的、支离破碎的，如骨折的头骨或破碎的叙事。"},{"word":"fragment","ipa":"/ˈfræɡmənt/","tag":"same root, a piece","definition":"From the same frangere stock: a piece broken off something larger, so it names the result rather than the break.","definitionCN":"同出 frangere：从更大物体上掉下的一块，指结果而非断裂本身。"},{"word":"fraction","ipa":"/ˈfrækʃn/","tag":"same root, a part","definition":"Also from fractus, but it shifted to a numerical part of a whole and no longer means a physical break.","definitionCN":"同样来自 fractus，但语义转向「整体的数值部分」，不再指物理断裂。"},{"word":"fragile","ipa":"/ˈfrædʒaɪl/","tag":"same root, easily broken","definition":"From frangere through French: easily broken, describing a quality rather than an event.","definitionCN":"经法语来自 frangere：容易破碎的，描述性质而非事件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"crack","ipa":"/kræk/","tag":"narrow opening","definition":"A narrow line of breakage or a sharp splitting sound; it can be smaller than a fracture and need not separate the parts.","definitionCN":"狭窄的裂线或清脆的爆裂声；可以比 fracture 更轻，且两半不必分离。"},{"word":"break","ipa":"/breɪk/","tag":"plain everyday word","definition":"The general English verb for separating into pieces; fracture is its technical and medical counterpart.","definitionCN":"表示分成数块的一般英语动词；fracture 是它技术化、医学化的对应词。"},{"word":"split","ipa":"/splɪt/","tag":"divide lengthwise","definition":"To divide along a line, often cleanly, as wood splits; it stresses separation rather than shattering.","definitionCN":"沿一条线分开，常指干脆地劈开，如木头裂开；强调分离而非碎成多块。"},{"word":"rupture","ipa":"/ˈrʌptʃə/","tag":"burst apart","definition":"A sudden tearing or bursting of something under pressure, such as a pipe or a tendon; it adds force to the idea of breaking.","definitionCN":"受压之物突然撕裂或爆开，如管道或肌腱；在「断裂」之上加了「受力爆裂」。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"frac- is the broken stem: frangere broke things, and fractus is the broken result.","cn":"frac- 就是「断」的词干：frangere 打破东西，fractus 是打破的结果。"},{"en":"The family runs fracture, fractured, fracturing, fraction, fragment, fragile and refract.","cn":"同族词包括 fracture、fractured、fracturing、fraction、fragment、fragile、refract。"},{"en":"Medical phrases fix the bone sense: hairline fracture, stress fracture, compound fracture.","cn":"医学搭配固定了骨折义：细微骨折、应力性骨折、开放性骨折。"},{"en":"Geology pairs it with fault and fracture zone, where the break is a plane in rock.","cn":"地质学把它与断层、断裂带配对，此时断口是岩体中的一个面。"},{"en":"The verb takes a direct object: fracture a bone, fracture a rock, fracture an alliance.","cn":"动词直接带宾语：使骨折、敲裂岩石、使联盟分裂。"}],"abstract":[{"en":"Picture a plate that looks whole until a hairline runs across it.","cn":"想象一只看似完好的盘子，直到一条细线横穿而过。"},{"en":"Picture a team photo with one person cut out of the frame.","cn":"想象一张团队合影，其中一个人被从画面里裁掉。"},{"en":"Picture a sentence that stops in the middle because the thought itself broke.","cn":"想象一句话说到一半就停住，因为那个念头本身断了。"}]},"examples":[{"en":"The impact fractured the limestone into angular blocks.","cn":"撞击把石灰岩碎成有棱角的岩块。"},{"en":"She fractured her ankle while stepping off the curb.","cn":"她在下路缘时扭断了脚踝。"},{"en":"The vote fractured the party along regional lines.","cn":"这次投票使该党沿地域界线分裂。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fract（断）+ ure」——像石头被敲出一道缝 → 断裂、骨折、分裂","word":"fracture"},"root":"拉丁 frangere「打破」的过去分词 fractus + 名词后缀 -ura → fractura「断裂」；英语 fracture。同族含 fraction、fragment、fragile、refract。","sensesIntro":{"en":"Eight senses follow one event: a hard thing loses its wholeness. The event is then named as a noun, located in bone, made a plane in rock, and finally applied to groups, agreements, mineral surfaces and systems.","cn":"八个义项沿同一个事件展开：坚硬之物失去完整。这个事件先被名词化，再落到骨头、岩体中的平面，最后用于群体、共识、矿物断面与系统。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sound slab that acquires a sharp new line and is no longer one piece.","cn":"核心意象：一块完好的石板出现一道锋利的新线，从此不再是一整块。"},"chain":["BREAK HARD SOLID","THE BREAK ITSELF","BONE BREAK","ROCK BREAK","SOCIAL SPLIT","CONTINUITY BREAK"],"branches":[{"senses":"S1 · S2","en":"ACT AND RESULT: the verb names the blow, the noun names the line it leaves.","cn":"动作与结果：动词指那一下敲击，名词指它留下的那条线。"},{"senses":"S3","en":"BONE: the body's hardest solid is the most personal place a fracture can happen.","cn":"骨头：身体里最硬的固体，是断裂最能切身发生的地方。"},{"senses":"S4 · S7","en":"ROCK AND MINERAL: geology turns the break into a measurable plane or surface.","cn":"岩石与矿物：地质学把断裂变成可测量的平面或断面。"},{"senses":"S5 · S6","en":"SOCIAL SPLIT: a group, like a slab, can lose its wholeness along a line.","cn":"社会分裂：群体和石板一样，会沿一条线失去完整。"},{"senses":"S8","en":"SYSTEM BREAK: continuity itself is what snaps in the abstract use.","cn":"系统中断：抽象用法里断掉的是连续性本身。"}]},"affixes":{"intro":{"en":"Fracture is a Latin noun of result built from a verbal stem plus a suffix, and the same stem recurs across English.","cn":"fracture 是由动词词干加后缀构成的拉丁结果名词，同一词干在英语中反复出现。"},"latinIntro":{"en":"Latin frangere, fractus and fractura give fracture, fraction, fragment, fragile, refract and frangible.","cn":"拉丁 frangere、fractus 与 fractura 衍生 fracture、fraction、fragment、fragile、refract 与 frangible。"},"items":[{"word":"frac-","structure":"fractus (Latin participle stem, 'broken')","meaning":"broken; broken off","meaningCN":"破碎的；断下的","example":"The stem frac- carries the result of breaking.","exampleCN":"词干 frac- 承载「打破之后的结果」。"},{"word":"-ure","structure":"-ura (Latin noun suffix, action or result)","meaning":"the act or result of doing","meaningCN":"动作或结果","example":"Fractura is the result noun built on the participle.","exampleCN":"fractura 是在分词之上构成的结果名词。"},{"word":"fracture","structure":"fractus + -ura","meaning":"a breaking; to break","meaningCN":"断裂；使断裂","example":"The chisel fracture left a clean edge.","exampleCN":"凿出的断裂留下干净的边。"},{"word":"fractured","structure":"fracture + -ed (past participle)","meaning":"broken, split, disjointed","meaningCN":"断裂的；分裂的；支离破碎的","example":"The fractured rock face showed several sets of joints.","exampleCN":"断裂的岩面显出好几组节理。"},{"word":"fracturing","structure":"fracture + -ing (verbal noun)","meaning":"the process of breaking","meaningCN":"破裂过程；压裂","example":"Hydraulic fracturing opened the shale.","exampleCN":"水力压裂打开了页岩。"},{"word":"fraction","structure":"fractus + -io (Latin noun of action)","meaning":"a breaking into parts, hence a numerical part","meaningCN":"分成部分，后指数值上的分数","example":"Only a fraction of the sample survived.","exampleCN":"样品中只有一小部分留存。"},{"word":"fragment","structure":"fragmentum (Latin, a piece broken off)","meaning":"a broken piece","meaningCN":"碎片","example":"Fragments of the core lay on the bench.","exampleCN":"岩芯的碎片散在实验台上。"},{"word":"fragile","structure":"fragilis (Latin, easily broken)","meaning":"easily broken","meaningCN":"易碎的","example":"The fragile shell cracked at a touch.","exampleCN":"脆薄的壳一碰就裂。"},{"word":"refract","structure":"re- (back) + frangere (break)","meaning":"to bend a ray back as it passes","meaningCN":"使（光线）折射","example":"Water refracts the light entering it.","exampleCN":"水使进入其中的光发生折射。"},{"word":"frangible","structure":"frangere + -ibilis (able to be)","meaning":"able to be broken","meaningCN":"可破碎的","example":"The frangible target shattered on impact.","exampleCN":"易碎靶一受撞击就碎。"}],"latinEntries":[{"word":"frangere","structure":"frangere, fregi, fractum (verb, third conjugation)","meaning":"to break, shatter","meaningCN":"打破；击碎"},{"word":"fractus","structure":"fractus, -a, -um (perfect passive participle)","meaning":"broken","meaningCN":"被打破的"},{"word":"fractura","structure":"fractura, fracturae (f., first declension)","meaning":"a breaking; a fracture","meaningCN":"断裂；骨折"},{"word":"fractio","structure":"fractio, fractionis (f., third declension)","meaning":"a breaking; a portion","meaningCN":"破碎；部分"},{"word":"fragilis","structure":"fragilis, fragile (adjective, third declension)","meaning":"easily broken","meaningCN":"易碎的"}]}},{"word":"fractured","ipa_uk":"/ˈfræktʃəd/","ipa_us":"/ˈfræktʃərd/","definition_zh":"断裂的；骨折的；分裂的；支离破碎的；受损的","definition_en":"broken or cracked, or divided into parts that no longer hold together","core_image":"一张完整的合影被撕成几片，边缘参差，人物再也对不上","scene":"急诊室里，医生把片子举到灯下，指着腕骨上的一道细线。 The X-ray shows a fractured wrist that needs a cast.","sceneCN":"这里 fractured 是形容词「骨折的、断裂的」（第 1 个义项：骨头或硬物出现裂口）；句意为 X 光片显示腕部骨折，需要打石膏。","pos":[{"tag":"adj.","zh":"断裂的；骨折的；分裂的；支离破碎的"},{"tag":"v.","zh":"（fracture 的过去式/过去分词）使断裂；使骨折"}],"collocations":[{"phrase":"fractured bone","zh":"骨折的骨头"},{"phrase":"fractured society","zh":"分裂的社会"},{"phrase":"fractured narrative","zh":"支离破碎的叙事"},{"phrase":"fractured rock","zh":"破碎的岩体"},{"phrase":"fractured relationship","zh":"破裂的关系"},{"phrase":"fractured market","zh":"割裂的市场"}],"forms":[{"label":"形容词原级","form":"fractured"},{"label":"比较级","form":"more fractured"},{"label":"最高级","form":"most fractured"},{"label":"动词原形（fracture）","form":"fracture"},{"label":"三单（he/she/it）","form":"fractures"},{"label":"现在分词","form":"fracturing"}],"derivatives":[{"word":"fracture","pos":"n./v.","zh":"断裂；裂缝；使断裂"},{"word":"fracturing","pos":"n.","zh":"破裂过程；压裂"},{"word":"fragment","pos":"n.","zh":"碎片（同出 frangere）"},{"word":"fragile","pos":"adj.","zh":"易碎的（同出 frangere）"},{"word":"fraction","pos":"n.","zh":"分数；小部分（同出 frangere）"}],"senses":[{"no":"01","title":"Cracked or broken physically","titleCN":"物理上断裂的、骨折的","definition":"having a crack or break, especially in bone, rock or a hard manufactured part","definitionCN":"出现裂缝或断口，尤指骨头、岩石或坚硬制件","example":"The X-ray shows a fractured wrist that needs a cast.","exampleCN":"X 光片显示腕部骨折，需要打石膏。","why":"fractured is simply the past participle of fracture used as an adjective, so it names the state left after the breaking event.","whyCN":"fractured 就是 fracture 的过去分词作形容词，因此它命名的是断裂事件之后留下的状态。"},{"no":"02","title":"Split into opposing groups","titleCN":"分裂成对立群体的","definition":"divided into factions or camps that no longer act as one","definitionCN":"分成若干不再作为一个整体行动的派别或阵营","example":"A fractured parliament passed nothing for six months.","exampleCN":"一个分裂的议会六个月里什么也没通过。","why":"the participle keeps the image of a solid in pieces and applies it to a body that should act as one.","whyCN":"这个分词保留了固体碎成数块的意象，并把它用于本应作为一个整体行动的机构。"},{"no":"03","title":"Disjointed in structure","titleCN":"结构上支离破碎的","definition":"lacking smooth continuity, so that the parts do not connect logically","definitionCN":"缺乏顺畅的连续性，各部分在逻辑上接不上","example":"The novel's fractured timeline jumps between three decades.","exampleCN":"这部小说破碎的时间线在三十年间来回跳跃。","why":"a narrative that does not hold together has the same defect as a cracked slab: the parts no longer meet.","whyCN":"接不上的叙事与裂开的石板有同样的缺陷：各部分不再咬合。"},{"no":"04","title":"Structurally damaged by cracks","titleCN":"因裂缝而结构受损的","definition":"weakened by cracks that run through a building, road or foundation","definitionCN":"因贯穿建筑、道路或地基的裂缝而变弱","example":"Engineers closed the fractured bridge before dawn.","exampleCN":"工程师在黎明前封闭了这座出现断裂的桥。","why":"in engineering the adjective describes a structure whose load paths are cut by cracks, not merely a surface that looks bad.","whyCN":"在工程语境里，这个形容词描述的是承力路径被裂缝切断的结构，而不只是外观难看。"},{"no":"05","title":"Divided into separate pieces of a market or land","titleCN":"市场或土地被割裂的","definition":"broken into small separate units that do not form a single system","definitionCN":"被分成互不构成单一系统的小单元","example":"Regulation left a fractured market of local monopolies.","exampleCN":"监管留下一个由地方垄断拼成的割裂市场。","why":"the sense extends the physical split to systems whose parts are prevented from joining.","whyCN":"这一义项把物理分裂扩展到那些各部分无法接合的系统。"},{"no":"06","title":"Strained or damaged in trust","titleCN":"信任受损的、关系破裂的","definition":"damaged in trust or goodwill, so that cooperation is difficult","definitionCN":"信任或善意受损，以致合作变得困难","example":"Years of silence left a fractured relationship between the cousins.","exampleCN":"多年的沉默让这对表亲的关系出现裂痕。","why":"trust is treated as something with a surface, and a surface can be cracked without being destroyed.","whyCN":"信任被当作有表面的东西，而表面可以裂开却尚未彻底毁掉。"},{"no":"07","title":"Broken and halting in speech","titleCN":"言语破碎、断断续续的","definition":"spoken in broken, interrupted phrases rather than complete fluent sentences","definitionCN":"以破碎、被打断的短语说出，而非完整流畅的句子","example":"The witness gave a fractured account of the night.","exampleCN":"目击者对那晚作了断断续续的叙述。","why":"speech that keeps stopping has the continuity of its phrases broken, which is the abstract version of a crack.","whyCN":"不断停顿的言语，其短语的连续性被打断，这就是裂缝的抽象版本。"},{"no":"08","title":"Broken by many joints in rock","titleCN":"岩体被多组节理破碎的","definition":"describing rock or an aquifer cut by many joints and small faults","definitionCN":"描述被许多节理与小断层切割的岩体或含水层","example":"Water moves quickly through the fractured limestone.","exampleCN":"水在破碎的石灰岩中流动得很快。","why":"geology uses the participle for rock whose network of breaks controls how fluids travel.","whyCN":"地质学用这个分词描述岩体，其裂隙网络控制流体的运移。"}],"etymology":{"intro":{"en":"Fractured is the past participle of fracture, which comes from Latin fractura, a breaking, from frangere, to break. As an adjective it is a modern English formation, not a separate Latin word.","cn":"fractured 是 fracture 的过去分词；fracture 来自拉丁 fractura「断裂」，源自动词 frangere「打破」。作形容词是英语自身的构词，并非另一个拉丁词。"},"items":[{"era":"LATIN FRANGERE","en":"Frangere meant to break or shatter, with the participle fractus, broken, supplying the stem behind the whole English family.","cn":"frangere 意为「打破、击碎」，分词 fractus「被打破的」提供了整个英语词族背后的词干。"},{"era":"LATIN FRACTURA","en":"Fractura named a breaking or the breach it produced; English borrowed it in the fifteenth century as the medical term for a broken bone.","cn":"fractura 指一次断裂或它造成的破口；英语在 15 世纪借入，作为骨折的医学术语。"},{"era":"ENGLISH PARTICIPLE","en":"English added -ed to fracture to form the past participle, which then took on adjective work: a fractured bone, a fractured party.","cn":"英语给 fracture 加 -ed 构成过去分词，随后它承担形容词功能：骨折的骨头、分裂的政党。"},{"era":"MODERN EXTENSIONS","en":"In the twentieth century the adjective spread to narratives, markets and relationships, where the shared idea is lost continuity.","cn":"到 20 世纪，这个形容词扩展到叙事、市场与关系，共同的要点都是失去连续性。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin only): the pre-Latin root of frangere is reconstructed rather than attested, and the exact first date of the adjective use is not recorded.","cn":"来源不确定（仅更深词源）：frangere 的拉丁语之前词根属于重构而非有据形式，形容词用法的确切首见年代亦无记录。"}]},"similar":{"note":{"en":"Group one holds forms built on the same breaking stem; group two holds adjectives of damage and division that are close in meaning.","cn":"第一组是同出「打破」词干的词形；第二组是意义相近、表示损坏与分裂的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fracture","ipa":"/ˈfræktʃə/","tag":"base noun and verb","definition":"The base form: a break, or the act of breaking; fractured is its participial adjective.","definitionCN":"基础形式：断裂，或使断裂的动作；fractured 是它的分词形容词。"},{"word":"fragmented","ipa":"/fræɡˈmentɪd/","tag":"same root family","definition":"From fragment, same Latin stock: broken into many separate pieces, often used for data or habitats.","definitionCN":"来自同出拉丁词干的 fragment：碎成许多独立小块，常用于数据或栖息地。"},{"word":"fractional","ipa":"/ˈfrækʃənl/","tag":"same root, numerical","definition":"From fraction: relating to a small numerical part, with no sense of physical cracking.","definitionCN":"来自 fraction：与数值上的小部分有关，不含物理裂开的意思。"},{"word":"refracted","ipa":"/rɪˈfræktɪd/","tag":"same root, light","definition":"From refract, re- plus frangere: bent at an angle, used of light or waves rather than solids.","definitionCN":"来自 refract，即 re- 加 frangere：以一定角度弯折，用于光或波而非固体。"}]},{"heading":"NEAR MEANING","entries":[{"word":"broken","ipa":"/ˈbrəʊkən/","tag":"plain everyday word","definition":"The common adjective for something in pieces; it is broader and less technical than fractured.","definitionCN":"表示物件碎了的日常形容词；比 fractured 更宽泛、更不技术化。"},{"word":"cracked","ipa":"/krækt/","tag":"surface line","definition":"Having a thin line of breakage, often on a surface; the parts may still be in place.","definitionCN":"表面出现细裂线；各部分可能仍在原位。"},{"word":"split","ipa":"/splɪt/","tag":"divided into parts","definition":"Separated into two or more parts, often along a clean line, as a split log or a split vote.","definitionCN":"分成两块或多块，常沿一条整齐的线，如劈开的木头或分裂的票数。"},{"word":"disjointed","ipa":"/dɪsˈdʒɔɪntɪd/","tag":"no logical joins","definition":"Lacking coherent connections between parts, used of speech, writing or policy; it does not imply physical damage.","definitionCN":"各部分缺乏连贯衔接，用于言语、写作或政策；不含物理损坏之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"fracture + -ed: the -ed turns the event into a state.","cn":"fracture + -ed：这个 -ed 把事件变成状态。"},{"en":"X-ray language fixes it: a fractured wrist, a fractured rib, a fractured femur.","cn":"X 光语境固定了它：腕部骨折、肋骨骨折、股骨骨折。"},{"en":"The figurative set is equally fixed: a fractured society, a fractured party, a fractured relationship.","cn":"比喻搭配同样固定：分裂的社会、分裂的政党、破裂的关系。"},{"en":"Geologists write of fractured rock and fractured aquifers, where cracks control flow.","cn":"地质学家写破碎岩体与裂隙含水层，其中裂缝控制水流。"},{"en":"The base verb keeps the family: fracture, fractures, fracturing, fracturing fluid.","cn":"基础动词维系着词族：fracture、fractures、fracturing、压裂液。"}],"abstract":[{"en":"Picture a vase glued back together, still visibly lined.","cn":"想象一只被粘回的花瓶，裂纹仍清晰可见。"},{"en":"Picture a conversation that keeps restarting after every interruption.","cn":"想象一段对话每被打断一次就得重来。"},{"en":"Picture a map cut along provincial borders into separate sheets.","cn":"想象一张地图沿省界被裁成几张分开的纸。"}]},"examples":[{"en":"The climber returned with a fractured ankle and a torn jacket.","cn":"登山者带着骨折的脚踝和划破的夹克回来了。"},{"en":"The documentary gives a fractured picture of the war.","cn":"这部纪录片给出了这场战争支离破碎的图景。"},{"en":"Rain soaks into the fractured bedrock within minutes.","cn":"雨水在几分钟内渗入破碎的基岩。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fract（断）+ ured」——已经被敲断的状态 → 断裂的、分裂的","word":"fractured"},"root":"fracture 的过去分词形容词：拉丁 frangere「打破」→ 分词 fractus → fractura「断裂」→ 英语 fracture + -ed。","sensesIntro":{"en":"Eight senses all describe a state after a break: the bone, the rock, the building and the market are physical; the parliament, the narrative, the relationship and the halting speech are the same loss of wholeness in other materials.","cn":"八个义项都描述断裂之后的状态：骨头、岩石、建筑与市场是物理层面；议会、叙事、关系与断续的言语则是同一种「失去完整」发生在别的材料上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a torn photograph whose pieces no longer line up.","cn":"核心意象：一张被撕开的照片，碎片再也对不上。"},"chain":["CRACKED","BONE STATE","SPLIT GROUP","BROKEN STRUCTURE","LOST CONTINUITY","DIVIDED SYSTEM"],"branches":[{"senses":"S1","en":"DIRECT STATE: the participle simply reports that a break has happened.","cn":"直接状态：分词只是报告断裂已经发生。"},{"senses":"S2 · S6","en":"SOCIAL BODY: a group or a bond is no longer one piece.","cn":"社会躯体：群体或关系不再是一整块。"},{"senses":"S3 · S7","en":"LOST FLOW: narrative and speech lose the joins that make them continuous.","cn":"失去流畅：叙事与言语失去使它们连贯的接缝。"},{"senses":"S4 · S5","en":"BUILT SYSTEMS: bridges and markets fail as systems once their parts separate.","cn":"人造系统：桥与市场一旦各部分分离，作为系统就失效。"},{"senses":"S8","en":"ROCK NETWORK: the cracks themselves become the structure that carries water.","cn":"岩石网络：裂缝本身成了输送水的结构。"}]},"affixes":{"intro":{"en":"Fractured is an English participle adjective: a Latin-derived base plus the native -ed suffix, with the Latin stem still readable inside.","cn":"fractured 是英语分词形容词：拉丁来源的词基加本族语 -ed 后缀，内部仍可读出拉丁词干。"},"latinIntro":{"en":"The base fracture goes back to Latin frangere and fractura; the -ed is English, so the word is a hybrid of Latin stem and Germanic suffix.","cn":"词基 fracture 上溯拉丁 frangere 与 fractura；-ed 属英语，因此这个词是拉丁词干与日耳曼语后缀的混合体。"},"items":[{"word":"frac-","structure":"fractus (Latin participle stem, 'broken')","meaning":"broken","meaningCN":"破碎的","example":"The stem appears in fracture, fraction and fragment.","exampleCN":"这个词干出现在 fracture、fraction 与 fragment 中。"},{"word":"fracture","structure":"fractus + -ura (Latin result noun)","meaning":"a break; to break","meaningCN":"断裂；使断裂","example":"One fracture can end a season.","exampleCN":"一次骨折就能结束一个赛季。"},{"word":"-ed","structure":"-ed (English past participial suffix)","meaning":"having undergone the action","meaningCN":"已经历该动作的","example":"The suffix turns the event into a state.","exampleCN":"这个后缀把事件转成状态。"},{"word":"fractured","structure":"fracture + -ed","meaning":"having been broken","meaningCN":"已被断裂的","example":"The fractured pipe leaked for a week.","exampleCN":"破裂的管子漏了一周。"},{"word":"fracturing","structure":"fracture + -ing (English verbal noun)","meaning":"the process of breaking","meaningCN":"破裂过程","example":"Fracturing the rock releases the gas.","exampleCN":"压裂岩体可释放气体。"},{"word":"fragment","structure":"fragmentum (Latin, a broken piece)","meaning":"a piece broken off","meaningCN":"碎片","example":"Fragments filled the bottom of the tray.","exampleCN":"碎片铺满托盘底部。"},{"word":"fraction","structure":"fractio (Latin, a breaking or portion)","meaning":"a part of a whole","meaningCN":"整体的一部分；分数","example":"A fraction of the class returned.","exampleCN":"班里只有一小部分人回来了。"},{"word":"fragile","structure":"fragilis (Latin, easily broken)","meaning":"easily broken","meaningCN":"易碎的","example":"The label reads fragile.","exampleCN":"标签上写着「易碎」。"},{"word":"refract","structure":"re- (back) + frangere (break)","meaning":"to bend light at a boundary","meaningCN":"使光折射","example":"The prism refracts the beam.","exampleCN":"棱镜使光束折射。"}],"latinEntries":[{"word":"frangere","structure":"frangere, fregi, fractum (verb, third conjugation)","meaning":"to break, shatter","meaningCN":"打破；击碎"},{"word":"fractus","structure":"fractus, -a, -um (perfect passive participle)","meaning":"broken","meaningCN":"被打破的"},{"word":"fractura","structure":"fractura, fracturae (f., first declension)","meaning":"a breaking; a fracture","meaningCN":"断裂；骨折"},{"word":"fragilis","structure":"fragilis, fragile (adjective, third declension)","meaning":"easily broken","meaningCN":"易碎的"}]}},{"word":"seismic","ipa_uk":"/ˈsiːzmɪk/","ipa_us":"/ˈsiːzmɪk/","definition_zh":"地震的；地震引起的；震动的；影响巨大的","definition_en":"relating to earthquakes or to the vibrations they send through the ground","core_image":"一条波线从地底某一点向四面扩散，经过之处墙体和地表都在轻微起伏","scene":"地震台网的值班室里，屏幕上一条波形刚刚越过警戒线。 Sensors across the valley recorded seismic activity for three minutes.","sceneCN":"这里 seismic 是「地震的」（第 1 个义项：与地震或地震引起的震动有关）；句意为谷地各处的传感器记录了三分钟的地震活动。","pos":[{"tag":"adj.","zh":"地震的；地震引起的；震动的；影响巨大的"}],"collocations":[{"phrase":"seismic activity","zh":"地震活动"},{"phrase":"seismic wave","zh":"地震波"},{"phrase":"seismic survey","zh":"地震勘探"},{"phrase":"seismic hazard","zh":"地震危险"},{"phrase":"seismic design","zh":"抗震设计"},{"phrase":"seismic shift","zh":"巨大转变"}],"forms":[{"label":"形容词原级","form":"seismic"},{"label":"比较级","form":"more seismic"},{"label":"最高级","form":"most seismic"},{"label":"副词","form":"seismically"},{"label":"名词（地震活动性）","form":"seismicity"}],"derivatives":[{"word":"seismicity","pos":"n.","zh":"地震活动性；某地区的地震频度"},{"word":"aseismic","pos":"adj.","zh":"无地震的；抗震的"},{"word":"seismism","pos":"n.","zh":"地震现象（少用）"},{"word":"seismically","pos":"adv.","zh":"在地震方面；按抗震方式"},{"word":"seismology","pos":"n.","zh":"地震学（seismo- 组合形式参与构成的学科名）"}],"senses":[{"no":"01","title":"Relating to earthquakes","titleCN":"与地震有关的","definition":"connected with earthquakes or with the shaking of the earth's crust","definitionCN":"与地震或地壳震动相关的","example":"Sensors across the valley recorded seismic activity for three minutes.","exampleCN":"谷地各处的传感器记录了三分钟的地震活动。","why":"seismic comes from Greek seismos, a shaking or earthquake, so the adjective simply points to that event.","whyCN":"seismic 来自希腊 seismos「震动、地震」，因此这个形容词直接指向那个事件。"},{"no":"02","title":"Concerning seismic waves","titleCN":"与地震波有关的","definition":"describing the elastic waves that travel through rock after a sudden rupture","definitionCN":"描述岩体突然破裂后在岩石中传播的弹性波","example":"Seismic waves arrive from the focus in several distinct phases.","exampleCN":"地震波以几个不同震相从震源抵达。","why":"once instruments could record the shaking, the adjective was attached to the waves that carry it, not only to the event.","whyCN":"当仪器能记录震动之后，这个形容词就不仅指事件，也用于承载震动的波。"},{"no":"03","title":"Monitoring ground motion","titleCN":"用于监测地面运动的","definition":"used for instruments, networks or data that detect and measure ground shaking","definitionCN":"用于探测与测量地面震动的仪器、台网或数据","example":"The seismic network sent an alert before the strongest shaking arrived.","exampleCN":"地震台网在最强震动到达前发出了警报。","why":"a monitoring system is named by what it watches, so seismic became the standard label for earthquake detection.","whyCN":"监测系统按它监视的对象命名，因此 seismic 成了地震探测的标准标签。"},{"no":"04","title":"Imaging the ground by sound","titleCN":"用声波给地下成像的","definition":"relating to the method that sends artificial vibrations into the ground and reads their echoes","definitionCN":"与向地下发送人工震动并读取回波的方法有关","example":"A seismic survey mapped the salt dome under the seabed.","exampleCN":"一次地震勘探测出了海床下的盐丘。","why":"the same physics that records earthquakes can be reversed: make a controlled shock and listen to the reflections.","whyCN":"记录地震的同一套物理可以反用：制造可控震动，再听反射。"},{"no":"05","title":"Based on seismic data","titleCN":"依据地震数据推断的","definition":"derived from recorded ground motion, as in images of rock layers or fault maps","definitionCN":"由记录到的地面运动推得，如岩层图像或断层图","example":"The seismic image shows a buried fault beneath the delta.","exampleCN":"地震图像显示三角洲下有一条被掩埋的断层。","why":"data is named by the physical signal that produced it, so seismic became a shorthand for the whole imaging method.","whyCN":"数据按产生它的物理信号命名，因此 seismic 成了整套成像方法的简称。"},{"no":"06","title":"Relating to earthquake risk","titleCN":"与地震风险有关的","definition":"concerning the probability and expected strength of shaking at a place","definitionCN":"关于某地发生震动的概率与预期强度","example":"The building code sets seismic requirements for every new school.","exampleCN":"建筑规范为每所新建学校规定了抗震要求。","why":"risk language uses the adjective because the hazard itself is the shaking, not the fault line on a map.","whyCN":"风险语言使用这个形容词，因为危险本身是震动，而不是地图上的断层线。"},{"no":"07","title":"Designed to resist earthquakes","titleCN":"为抵御地震而设计的","definition":"built or fitted so that structures can survive strong shaking","definitionCN":"为使结构能在强烈震动中存留而建造或装配","example":"Seismic isolation lets the base move while the floors stay steady.","exampleCN":"地震隔震让底座移动而楼层保持稳定。","why":"engineering turns the adjective into a design goal: whatever resists the shaking is called seismic.","whyCN":"工程学把这个形容词变成设计目标：凡是能抵御震动的都冠以 seismic。"},{"no":"08","title":"Figuratively enormous in effect","titleCN":"比喻：影响如同地震般巨大的","definition":"having an effect as sudden and far-reaching as an earthquake","definitionCN":"产生的影响如地震般突然而深远","example":"The ruling caused a seismic shift in how the industry was financed.","exampleCN":"这项裁决使该行业的融资方式发生了地震般的转变。","why":"the figurative sense borrows the scale of an earthquake: not just a change, but one that rearranges the ground under everything.","whyCN":"比喻义借用了地震的规模：不只是变化，而是把一切脚下的地面重新排布。"}],"etymology":{"intro":{"en":"Seismic was formed in English in the nineteenth century from Greek seismos, a shaking, an earthquake, built on the verb seiein, to shake, plus the adjective suffix -ic. It has no Latin ancestor.","cn":"seismic 是 19 世纪英语新造词，来自希腊 seismos「震动、地震」，其词根为动词 seiein「摇动」，加形容词后缀 -ic。它没有拉丁语祖先。"},"items":[{"era":"GREEK SEIEIN","en":"Seiein meant to shake or drive by shaking. Its deeper pre-Greek origin is not established, so any Indo-European form for it is a reconstruction.","cn":"seiein 意为「摇动、以摇动驱使」。其希腊语之前的更深来源未获证明，因此为它给出的任何印欧形式都属重构。"},{"era":"GREEK SEISMOS","en":"Seismos named a shaking or an earthquake; the same stem appears in seismology and in older medical use for trembling.","cn":"seismos 指一次震动或地震；同一词干也出现在 seismology，以及较早医学用语中的「颤抖」。"},{"era":"SCIENTIFIC COINAGE","en":"English scientists coined seismic in the mid nineteenth century to name the study and measurement of earthquakes, at a time when seismology was becoming a science.","cn":"19 世纪中叶，英语科学界造出 seismic，用来命名地震的研究与测量，当时地震学正成为一门科学。"},{"era":"EXPLORATION SENSE","en":"In the twentieth century seismic survey came to mean deliberate sound-wave imaging of rock layers for oil, gas and engineering.","cn":"到 20 世纪，seismic survey 指为石油、天然气与工程目的，用声波对岩层做主动成像。"},{"era":"FIGURATIVE USE","en":"Late modern English extended the adjective to any change of earthquake scale, as in a seismic shift in policy or markets.","cn":"现代英语晚期把这个形容词扩展到任何地震级的变化，如政策或市场上的地震式转变。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Greek root of seiein is unsettled, and the earliest printed use of seismic is dated only approximately to the 1850s.","cn":"来源不确定（更深词源与首见年代）：seiein 的希腊语之前词根尚无定论，seismic 最早的印刷用例也只能约略定在 1850 年代。"}]},"similar":{"note":{"en":"Group one holds words built on the same Greek shaking stem; group two holds adjectives that describe large earth movements or huge effects.","cn":"第一组是同出希腊「震动」词干的词；第二组是描述大规模地壳运动或巨大影响的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seismal","ipa":"/ˈsiːzməl/","tag":"same root, rare","definition":"An older synonym meaning relating to an earthquake; it is now rare beside seismic.","definitionCN":"较旧的同义词，意为「与地震有关的」；如今除 seismic 外已罕用。"},{"word":"aseismic","ipa":"/eɪˈsiːzmɪk/","tag":"negated form","definition":"Built with the Greek negative prefix a-: either free from earthquakes or designed to resist them.","definitionCN":"由希腊否定前缀 a- 构成：或指无地震的，或指抗震的。"},{"word":"seismicity","ipa":"/siːzˈmɪsəti/","tag":"same root, noun","definition":"The frequency and distribution of earthquakes in a region; the noun behind seismic activity.","definitionCN":"某地区地震的频度与分布；即 seismic activity 背后的名词。"},{"word":"seismograph","ipa":"/ˈsiːzməɡrɑːf/","tag":"same root, instrument","definition":"Seismo- plus -graph, a writing instrument: the device that draws a record of ground motion.","definitionCN":"seismo- 加 -graph「书写」：把地面运动画成记录曲线的仪器。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tectonic","ipa":"/tekˈtɒnɪk/","tag":"plate-scale geology","definition":"Relating to the structure of the earth's crust and the plates that move it; tectonic events cause earthquakes but the word does not mean seismic.","definitionCN":"与地壳结构及推动地壳的板块有关；构造事件会引发地震，但该词本身并不等于 seismic。"},{"word":"earthshaking","ipa":"/ˈɜːθʃeɪkɪŋ/","tag":"figurative only","definition":"Literally shaking the earth, but in practice almost always figurative for enormously important; seismic covers both the literal and figurative.","definitionCN":"字面为「摇动大地」，实际几乎总作比喻指「极其重大」；seismic 则兼具字面与比喻两义。"},{"word":"geophysical","ipa":"/ˌdʒiːəʊˈfɪzɪkl/","tag":"broader science","definition":"Relating to the physics of the earth as a whole, including gravity, magnetism and heat; seismic is only one branch of it.","definitionCN":"与整个地球的物理有关，包括重力、磁场与热；seismic 只是其中一个分支。"},{"word":"catastrophic","ipa":"/ˌkætəˈstrɒfɪk/","tag":"outcome, not cause","definition":"Describing a disastrous outcome; it can describe an earthquake's effects but says nothing about shaking as such.","definitionCN":"描述灾难性后果；可描述地震的影响，但本身并不指震动。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek seismos, shaking, plus -ic: the adjective of an earthquake.","cn":"希腊 seismos「震动」加 -ic：地震的形容词。"},{"en":"The family runs seismic, seismicity, aseismic, seismograph, seismometer, seismogram, seismology.","cn":"同族词包括 seismic、seismicity、aseismic、seismograph、seismometer、seismogram、seismology。"},{"en":"Fixed phrases: seismic wave, seismic survey, seismic hazard, seismic design.","cn":"固定搭配：地震波、地震勘探、地震危险、抗震设计。"},{"en":"seismo- is the combining form in instrument names, always tied to ground motion.","cn":"seismo- 是仪器名称中的组合形式，始终与地面运动相关。"},{"en":"The figurative phrase seismic shift is a set expression for a very large change.","cn":"比喻搭配 seismic shift 是「巨大转变」的固定说法。"}],"abstract":[{"en":"Picture a stone dropped in a pond, but the rings run through rock.","cn":"想象一颗石子落入池塘，只是涟漪穿过的是岩石。"},{"en":"Picture a city where every table starts sliding at the same instant.","cn":"想象一座城市里每张桌子在同一瞬间开始滑动。"},{"en":"Picture a rulebook rewritten overnight while everyone is still asleep.","cn":"想象一本规则手册在众人熟睡时被一夜改写。"}]},"examples":[{"en":"The region has been quiet, with no seismic activity for a decade.","cn":"该地区一直平静，十年来没有地震活动。"},{"en":"Seismic reflection revealed a deep basin beneath the plain.","cn":"地震反射探测揭示出平原之下有一个深盆地。"},{"en":"The new evidence caused a seismic change in the accepted theory.","cn":"新证据使公认理论发生了地震般的改变。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「seis（震）+ mic」——大地在抖动 → 地震的、震动的","word":"seismic"},"root":"希腊 seismos「震动、地震」，源自 seiein「摇动」，加形容词后缀 -ic；希腊来源，无拉丁同族，拉丁词条留空。","sensesIntro":{"en":"Eight senses follow the same shaking: first the earthquake itself, then its waves, its monitoring, its use for imaging, its data, its risk, its engineering answer, and finally any change on the same scale.","cn":"八个义项沿同一种震动展开：先是地震本身，继而它的波、监测、成像用途、数据、风险、工程对策，最后是任何同等规模的变化。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wave front spreading from one point underground, tilting everything it passes.","cn":"核心意象：一道波前从地下某点扩散，经过之处一切都在倾斜。"},"chain":["EARTHQUAKE","SHAKING WAVE","MONITORING","SOUND IMAGING","HAZARD AND DESIGN","HUGE CHANGE"],"branches":[{"senses":"S1","en":"THE EVENT: seismic points first at the earthquake itself.","cn":"事件：seismic 首先指向地震本身。"},{"senses":"S2 · S3","en":"CARRYING AND WATCHING: waves carry the shaking, instruments watch it.","cn":"承载与监视：波承载震动，仪器监视震动。"},{"senses":"S4 · S5","en":"ACTIVE USE: the same physics is turned into a lamp for the subsurface.","cn":"主动利用：同一套物理被改造为照亮地下的灯。"},{"senses":"S6 · S7","en":"RISK AND RESPONSE: shaking becomes a design load to be resisted.","cn":"风险与应对：震动变成必须抵御的设计荷载。"},{"senses":"S8","en":"METAPHOR: the scale of an earthquake is lent to social change.","cn":"比喻：把地震的规模借给社会变化。"}]},"affixes":{"intro":{"en":"Seismic is a Greek-derived adjective whose combining form seismo- appears at the front of a whole family of earth-science words.","cn":"seismic 是希腊来源的形容词，其组合形式 seismo- 出现在整族地球科学词汇的词首。"},"latinIntro":{"en":"There is no Latin ancestor: the family goes back to Greek seiein and seismos, and Latin gained only loanwords such as the medical use of tremor.","cn":"没有拉丁语祖先：这个词族上溯希腊 seiein 与 seismos；拉丁语只贡献了如医学用法的 tremor 等借词。"},"items":[{"word":"seismo-","structure":"seismo- (Greek combining form, 'earthquake')","meaning":"earthquake; shaking","meaningCN":"地震；震动","example":"Seismo- heads the names of instruments and sciences.","exampleCN":"seismo- 位于仪器与学科名称的词首。"},{"word":"seismos","structure":"seismos (Greek noun, 'a shaking')","meaning":"a shaking, an earthquake","meaningCN":"震动；地震","example":"The noun is the source of the whole family.","exampleCN":"这个名词是整个词族的来源。"},{"word":"seiein","structure":"seiein (Greek verb, 'to shake')","meaning":"to shake","meaningCN":"摇动","example":"The verb supplies the root sei-.","exampleCN":"这个动词提供词根 sei-。"},{"word":"-ic","structure":"-ikos (Greek adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix makes an adjective from the noun.","exampleCN":"这个后缀把名词变成形容词。"},{"word":"seismic","structure":"seismos + -ic","meaning":"relating to earthquakes","meaningCN":"地震的","example":"Seismic data guide the drill.","exampleCN":"地震数据指导钻探。"},{"word":"seismicity","structure":"seismic + -ity (state or quality)","meaning":"the earthquake frequency of a region","meaningCN":"区域地震活动性","example":"Low seismicity made the site attractive.","exampleCN":"地震活动性低使该场址颇具吸引力。"},{"word":"aseismic","structure":"a- (Greek negative) + seismic","meaning":"without earthquakes; quake-resistant","meaningCN":"无地震的；抗震的","example":"Aseismic bearings isolate the hall.","exampleCN":"抗震支座把大厅隔开。"},{"word":"seismograph","structure":"seismo- + -graph (writing)","meaning":"an instrument that records shaking","meaningCN":"记录震动的仪器","example":"The seismograph traced a long, low pulse.","exampleCN":"地震仪描出一条长而低的脉冲。"},{"word":"seismometer","structure":"seismo- + -meter (measure)","meaning":"an instrument that measures ground motion","meaningCN":"测量地面运动的仪器","example":"The seismometer sat on bedrock.","exampleCN":"地震计安放在基岩上。"},{"word":"seismogram","structure":"seismo- + -gram (something written)","meaning":"the record produced by a seismograph","meaningCN":"地震仪记录图","example":"The seismogram showed two arrivals.","exampleCN":"地震记录图显示两个到达震相。"},{"word":"seismology","structure":"seismo- + -logy (study of)","meaning":"the scientific study of earthquakes","meaningCN":"地震学","example":"Seismology grew from early earthquake catalogues.","exampleCN":"地震学从早期地震目录发展而来。"}],"latinEntries":[]}},{"word":"seismology","ipa_uk":"/siːzˈmɒlədʒi/","ipa_us":"/siːzˈmɑːlədʒi/","definition_zh":"地震学；研究地震与地震波的学科","definition_en":"the scientific study of earthquakes and of the waves they send through the earth","core_image":"一间地下观测室里，滚筒纸带不断走动，把来自地底的每一次轻微抖动画成曲线","scene":"大学地质系的地下观测室里，学生围着一台持续走纸的滚筒记录仪。 She chose seismology because she wanted to understand what happens miles below the surface.","sceneCN":"这里 seismology 是「地震学」（第 1 个义项：以地震为研究对象的学科）；句意为她选择地震学，是因为想弄清楚地表以下数英里处发生了什么。","pos":[{"tag":"n.","zh":"地震学（不可数名词）"}],"collocations":[{"phrase":"study seismology","zh":"学习地震学"},{"phrase":"observational seismology","zh":"观测地震学"},{"phrase":"engineering seismology","zh":"工程地震学"},{"phrase":"planetary seismology","zh":"行星地震学"},{"phrase":"exploration seismology","zh":"勘探地震学"},{"phrase":"a branch of seismology","zh":"地震学的一个分支"}],"forms":[{"label":"名词（学科，不可数）","form":"seismology"},{"label":"复数（指多个学科分支，少用）","form":"seismologies"},{"label":"形容词（地震学的）","form":"seismological"},{"label":"副词（从地震学角度）","form":"seismologically"},{"label":"从业者名词","form":"seismologist"}],"derivatives":[{"word":"seismologist","pos":"n.","zh":"地震学家"},{"word":"seismological","pos":"adj.","zh":"地震学的"},{"word":"seismologically","pos":"adv.","zh":"从地震学角度"},{"word":"seismogram","pos":"n.","zh":"地震记录图"},{"word":"seismograph","pos":"n.","zh":"地震仪"},{"word":"seismometer","pos":"n.","zh":"地震计"}],"senses":[{"no":"01","title":"The science of earthquakes","titleCN":"研究地震的科学","definition":"the branch of science that studies earthquakes, their causes and their effects","definitionCN":"研究地震、其成因与影响的科学分支","example":"She chose seismology because she wanted to understand what happens miles below the surface.","exampleCN":"她选择地震学，是因为想弄清楚地表以下数英里处发生了什么。","why":"seismology joins Greek seismos, earthquake, to -logia, the study of something, so the word says exactly what the discipline does.","whyCN":"seismology 把希腊 seismos「地震」与 -logia「对某物的研究」拼合，词面正好说出这门学科做什么。"},{"no":"02","title":"The study of seismic waves","titleCN":"研究地震波的学问","definition":"the part of the field that reads the waves travelling through rock to infer structure and rupture","definitionCN":"该领域中通过读取岩体中传播的波来推断结构与破裂的部分","example":"Modern seismology reads arrivals at hundreds of stations at once.","exampleCN":"现代地震学同时读取数百个台站的到时。","why":"earthquakes are known mostly through their waves, so the study of the event became the study of the signal it sends.","whyCN":"地震主要经由其波被认识，因此对事件的研究变成了对它发出的信号的研究。"},{"no":"03","title":"A branch of geophysics","titleCN":"地球物理学的一个分支","definition":"the subfield of geophysics that deals with elastic waves and earthquake sources","definitionCN":"地球物理学中处理弹性波与震源问题的子领域","example":"Seismology sits beside gravity and magnetism within geophysics.","exampleCN":"在地球物理学中，地震学与重力学、地磁学并列。","why":"the discipline defines itself by its physical quantities, and elastic waves are its particular instrument of measurement.","whyCN":"这门学科以所测量的物理量界定自身，而弹性波是它特有的测量手段。"},{"no":"04","title":"Observational network practice","titleCN":"观测台网的实际工作","definition":"the routine work of operating stations, archiving records and cataloguing events","definitionCN":"运行台站、归档记录与编目事件的日常工作","example":"Observational seismology depends on stations that never lose power.","exampleCN":"观测地震学依赖从不掉电的台站。","why":"a science built on rare events needs a permanent record, so the adjective observational marks the branch that keeps it.","whyCN":"一门建立在稀有事件上的科学需要永久记录，因此 observational 标出负责保存记录的那一支。"},{"no":"05","title":"Planetary seismology","titleCN":"行星地震学","definition":"the application of seismic methods to the Moon, Mars and other solid bodies","definitionCN":"把地震方法用于月球、火星及其他固态天体","example":"Planetary seismology detected moonquakes with a single station.","exampleCN":"行星地震学用单个台站探测到了月震。","why":"the instrument does not care whether the shaking happens on Earth, so the discipline extended its name to other worlds.","whyCN":"仪器并不在意震动是否发生在地球上，因此这门学科把名字扩展到了别的世界。"},{"no":"06","title":"Exploration seismology","titleCN":"勘探地震学","definition":"the industrial use of controlled seismic sources to image rock for resources or engineering","definitionCN":"用可控震源为资源或工程目的给岩层成像的工业应用","example":"Exploration seismology mapped the reservoir before any well was drilled.","exampleCN":"勘探地震学在任何井开钻之前就勾出了储层。","why":"the same theory serves a different goal, so the field is named by its purpose rather than its subject.","whyCN":"同一套理论服务于不同目标，因此这一支按用途而非研究对象命名。"},{"no":"07","title":"Engineering seismology","titleCN":"工程地震学","definition":"the branch that estimates ground shaking and supplies design values for structures","definitionCN":"估算地面震动并为结构提供设计参数的分支","example":"Engineering seismology turned the fault map into design loads.","exampleCN":"工程地震学把断层图转化为设计荷载。","why":"when the question moves from what happened to what to build, the discipline splits off a branch with its own name.","whyCN":"当问题从「发生了什么」转向「该建什么」时，学科便分出一支并另立名目。"},{"no":"08","title":"Historical and computational seismology","titleCN":"历史地震学与计算地震学","definition":"the reconstruction of past events from written records, and the numerical modelling of wave propagation","definitionCN":"从文字记录重建过去事件，以及对波传播进行数值模拟","example":"Historical seismology pushes the catalogue back three centuries.","exampleCN":"历史地震学把地震目录向前推到三个世纪。","why":"both branches work on the same object by other means: one reads old paper, the other runs new code.","whyCN":"两支用不同手段研究同一对象：一支读旧纸，一支跑新代码。"}],"etymology":{"intro":{"en":"Seismology is a modern scientific compound: Greek seismos, earthquake, plus -logia, from logos, word, reason, the study of. It was coined in the nineteenth century and has no Latin ancestor.","cn":"seismology 是现代科学复合词：希腊 seismos「地震」加 -logia，后者出自 logos「言说、道理」，意为「对……的研究」。该词于 19 世纪新造，没有拉丁语祖先。"},"items":[{"era":"GREEK SEISMOS","en":"Seismos meant a shaking or an earthquake, from seiein, to shake. The deeper pre-Greek root is not established and remains reconstructed.","cn":"seismos 意为震动或地震，来自 seiein「摇动」。其希腊语之前的更深词根未获证明，仍属重构。"},{"era":"GREEK LOGOS","en":"Logos meant word, account or reason; the suffix -logia named the study or account of a subject, as in biology and geology.","cn":"logos 意为言词、叙述或道理；后缀 -logia 表示对某一主题的研究或叙述，如 biology 与 geology。"},{"era":"NINETEENTH-CENTURY COINAGE","en":"Seismology was formed in English around the 1850s, when earthquake catalogues and instruments made a distinct science possible.","cn":"seismology 约在 1850 年代在英语中构成，当时地震目录与仪器使一门独立科学成为可能。"},{"era":"TWENTIETH-CENTURY EXPANSION","en":"The field split into observational, exploration, engineering and planetary branches as instruments spread and computing arrived.","cn":"随着仪器普及与计算技术到来，该领域分成观测、勘探、工程与行星几支。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper root): the earliest printed use is dated only approximately to the 1850s, and the pre-Greek origin of seiein is unsettled.","cn":"来源不确定（首见年代与更深词根）：最早的印刷用例只能约略定在 1850 年代，seiein 的希腊语之前来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds the instrument-and-person words that cluster around the same stem; group two holds neighbouring earth sciences.","cn":"第一组是围绕同一词干的仪器与人名词；第二组是相邻的地球科学学科。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seismological","ipa":"/ˌsiːzməˈlɒdʒɪkl/","tag":"same word, adjective","definition":"The adjective for anything belonging to seismology, as in a seismological survey or observatory.","definitionCN":"属于地震学的一切事物所用的形容词，如地震学测量或地震观测台。"},{"word":"seismologist","ipa":"/siːzˈmɒlədʒɪst/","tag":"person noun","definition":"A person who practises seismology; the -ist suffix marks the practitioner.","definitionCN":"从事地震学的人；-ist 后缀标示从业者。"},{"word":"seismicity","ipa":"/siːzˈmɪsəti/","tag":"different suffix","definition":"The measured earthquake activity of a region, not the discipline; it is what seismology studies.","definitionCN":"某地区被测得的地震活动，而非学科本身；它是地震学的研究对象。"},{"word":"seismics","ipa":"/ˈsiːzmɪks/","tag":"method noun","definition":"The practical method of using elastic waves, especially in exploration; the plural form names a technique, not a science.","definitionCN":"使用弹性波的实用方法，尤用于勘探；复数形式指技术而非学科。"}]},{"heading":"NEAR MEANING","entries":[{"word":"geophysics","ipa":"/ˌdʒiːəʊˈfɪzɪks/","tag":"parent discipline","definition":"The physics of the whole earth, including gravity, heat and magnetism; seismology is one of its branches.","definitionCN":"研究整个地球物理性质的学科，包括重力、热与磁场；地震学是其分支之一。"},{"word":"geology","ipa":"/dʒiˈɒlədʒi/","tag":"rocks and history","definition":"The study of rocks, strata and earth history; it overlaps with seismology but does not centre on shaking.","definitionCN":"研究岩石、地层与地球历史；与地震学有交集，但不以震动为核心。"},{"word":"volcanology","ipa":"/vɒlˈkænəlɒdʒi/","tag":"sister science","definition":"The study of volcanoes and volcanic activity, often paired with seismology because magma movement causes tremors.","definitionCN":"研究火山与火山活动，常与地震学配对，因为岩浆运移会引发震动。"},{"word":"geodesy","ipa":"/dʒiːˈɒdəsi/","tag":"shape and position","definition":"The measurement of the earth's shape and the movement of its surface, used alongside seismic data to track deformation.","definitionCN":"测量地球形状与地表运动，常与地震数据配合追踪形变。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"seismo-, earthquake, plus -logy, study of: the study of earthquakes.","cn":"seismo-「地震」加 -logy「研究」：研究地震的学问。"},{"en":"The family runs seismology, seismologist, seismological, seismically, seismicity.","cn":"同族词包括 seismology、seismologist、seismological、seismically、seismicity。"},{"en":"Instruments mark the field: seismograph, seismometer, seismogram all begin with seismo-.","cn":"仪器标记这门学科：seismograph、seismometer、seismogram 都以 seismo- 开头。"},{"en":"Fixed branches: observational, exploration, engineering and planetary seismology.","cn":"固定分支：观测地震学、勘探地震学、工程地震学、行星地震学。"},{"en":"-logy words name disciplines, so seismology is the discipline, not an instrument or a person.","cn":"-logy 结尾的词命名学科，因此 seismology 是学科，不是仪器或人。"}],"abstract":[{"en":"Picture a doctor listening through the ground instead of through a chest.","cn":"想象一位医生不是听诊胸腔，而是隔着大地听诊。"},{"en":"Picture a library that shelves not books but wobbling lines of ink.","cn":"想象一座图书馆，架上放的不是书，而是抖动的墨线。"},{"en":"Picture a language in which the only sentence is a wave arriving at a certain hour.","cn":"想象一种语言，其中唯一的句子就是某时到达的一道波。"}]},"examples":[{"en":"Seismology advanced quickly once stations could share timing signals.","cn":"台站能共享授时信号之后，地震学迅速进步。"},{"en":"Her textbook on seismology is used in both geology and physics departments.","cn":"她的地震学教材同时被地质系与物理系采用。"},{"en":"Planetary seismology may yet reveal a liquid core inside Mars.","cn":"行星地震学也许终将揭示火星内部的液态核。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「seismo（地震）+ logy（学科）」——研究地震的学问 → 地震学","word":"seismology"},"root":"希腊 seismos「地震」+ -logia（出自 logos「言说、道理」）→ seismologia 式复合；英语 seismology。希腊来源，无拉丁同族，拉丁词条留空。","sensesIntro":{"en":"Eight senses trace one discipline outward: the science of earthquakes, its waves, its parent field, its network work, and then its planetary, industrial, engineering, historical and computational branches.","cn":"八个义项由一门学科向外展开：地震的科学、它的波、它的母学科、它的台网工作，再到行星、工业、工程、历史与计算各分支。"},"semanticMap":{"core":{"en":"CORE IMAGE: a paper drum turning slowly, drawing every tremor as a line.","cn":"核心意象：纸鼓缓慢转动，把每一次微震画成一条线。"},"chain":["EARTHQUAKE SCIENCE","WAVE READING","GEOPHYSICS BRANCH","NETWORK PRACTICE","APPLIED BRANCHES","HISTORICAL MEMORY"],"branches":[{"senses":"S1","en":"THE SCIENCE: the name points at the discipline as a whole.","cn":"学科整体：名称首先指向这门学问全体。"},{"senses":"S2 · S3","en":"THE METHOD: waves are the instrument, geophysics the frame.","cn":"方法：波是工具，地球物理学是框架。"},{"senses":"S4","en":"THE RECORD: permanent stations turn rare events into data.","cn":"记录：永久台站把稀有事件变成数据。"},{"senses":"S5 · S6","en":"OTHER BODIES AND OTHER GOALS: the same method leaves Earth or leaves pure research.","cn":"别的天体与别的目标：同一方法离开地球，或离开纯研究。"},{"senses":"S7 · S8","en":"SERVICE AND RECONSTRUCTION: it supplies design loads and rebuilds the past.","cn":"服务与重建：它提供设计荷载，也重建过去。"}]},"affixes":{"intro":{"en":"Seismology is a transparent Greek compound: an earthquake stem at the front and a study suffix at the back.","cn":"seismology 是一个透明的希腊复合词：前部是「地震」词干，后部是「研究」后缀。"},"latinIntro":{"en":"Nothing here is Latin: both halves are Greek, and Latin only enters later as the language of scientific publication.","cn":"这里没有拉丁成分：前后两半都是希腊语，拉丁语只是后来作为科学出版语言进入。"},"items":[{"word":"seismo-","structure":"seismo- (Greek combining form, 'earthquake')","meaning":"earthquake","meaningCN":"地震","example":"Seismo- opens both science and instrument names.","exampleCN":"seismo- 既开启学科名，也开启仪器名。"},{"word":"seismos","structure":"seismos (Greek noun, 'a shaking')","meaning":"a shaking, an earthquake","meaningCN":"震动；地震","example":"The stem is borrowed whole from Greek.","exampleCN":"这个词干整体借自希腊语。"},{"word":"-logy","structure":"-logia (Greek suffix, 'study of')","meaning":"the study or account of","meaningCN":"对……的研究或论述","example":"-Logy builds names of disciplines.","exampleCN":"-logy 构成学科名称。"},{"word":"logos","structure":"logos (Greek noun, 'word, reason')","meaning":"word; reasoned account","meaningCN":"言词；有理据的论述","example":"Logos supplies the suffix -logy.","exampleCN":"logos 提供了后缀 -logy。"},{"word":"seismology","structure":"seismos + -logia","meaning":"the study of earthquakes","meaningCN":"地震学","example":"Seismology is taught in the earth sciences building.","exampleCN":"地震学在地球科学楼里授课。"},{"word":"seismologist","structure":"seismology + -ist (person who practises)","meaning":"a practitioner of seismology","meaningCN":"地震学从业者","example":"The seismologist read the record at a glance.","exampleCN":"地震学家一眼就读懂了记录。"},{"word":"seismological","structure":"seismology + -ical (relating to)","meaning":"relating to seismology","meaningCN":"地震学的","example":"The seismological observatory never closes.","exampleCN":"地震观测台从不关闭。"},{"word":"seismogram","structure":"seismo- + -gram (written record)","meaning":"the record of a seismograph","meaningCN":"地震仪记录图","example":"The seismogram is stored digitally now.","exampleCN":"地震记录图如今以数字方式保存。"},{"word":"seismograph","structure":"seismo- + -graph (writing instrument)","meaning":"an instrument that records shaking","meaningCN":"记录震动的仪器","example":"The seismograph was invented in the nineteenth century.","exampleCN":"地震仪发明于 19 世纪。"},{"word":"seismometer","structure":"seismo- + -meter (measuring instrument)","meaning":"an instrument that measures ground motion","meaningCN":"测量地面运动的仪器","example":"A broadband seismometer detects distant quakes.","exampleCN":"宽频地震计能探测远处的地震。"}],"latinEntries":[]}},{"word":"seismologist","ipa_uk":"/siːzˈmɒlədʒɪst/","ipa_us":"/siːzˈmɑːlədʒɪst/","definition_zh":"地震学家；研究地震的科学家","definition_en":"a scientist who studies earthquakes and the waves they send through the earth","core_image":"一位研究者俯身在长条记录纸前，用铅笔标出两条波线到达的时刻","scene":"老式地震观测台里，值班的人把刚到的记录纸压平在灯下。 The seismologist marked the arrival times of both phases on the record.","sceneCN":"这里 seismologist 是「地震学家」（第 1 个义项：以地震为研究对象的科学家）；句意为这位地震学家在记录图上标出两个震相的到达时刻。","pos":[{"tag":"n.","zh":"地震学家；地震研究者"}],"collocations":[{"phrase":"a leading seismologist","zh":"一位顶尖地震学家"},{"phrase":"government seismologist","zh":"政府地震学家"},{"phrase":"field seismologist","zh":"野外地震工作者"},{"phrase":"exploration seismologist","zh":"勘探地震学家"},{"phrase":"the seismologist on duty","zh":"值班地震学家"},{"phrase":"consult a seismologist","zh":"咨询地震学家"}],"forms":[{"label":"名词单数","form":"seismologist"},{"label":"名词复数","form":"seismologists"},{"label":"学科名词","form":"seismology"},{"label":"形容词","form":"seismological"},{"label":"副词","form":"seismologically"}],"derivatives":[{"word":"seismology","pos":"n.","zh":"地震学"},{"word":"seismological","pos":"adj.","zh":"地震学的"},{"word":"seismologically","pos":"adv.","zh":"从地震学角度"},{"word":"seismograph","pos":"n.","zh":"地震仪"},{"word":"seismogram","pos":"n.","zh":"地震记录图"}],"senses":[{"no":"01","title":"A scientist of earthquakes","titleCN":"研究地震的科学家","definition":"a researcher whose subject is earthquakes, their causes and their effects","definitionCN":"以地震、其成因与影响为研究对象的科研人员","example":"The seismologist marked the arrival times of both phases on the record.","exampleCN":"这位地震学家在记录图上标出两个震相的到达时刻。","why":"seismologist is seismology plus -ist, the Greek suffix for a person who practises a craft or science.","whyCN":"seismologist 是 seismology 加 -ist，后者是希腊语中表示从事某技艺或科学之人的后缀。"},{"no":"02","title":"An analyst of a seismic network","titleCN":"地震台网的分析人员","definition":"a person who runs or reads the output of a network of monitoring stations","definitionCN":"运行或解读监测台网输出的人员","example":"The network seismologist spotted a gap in the data at once.","exampleCN":"台网地震学家立刻发现了数据中的一个缺口。","why":"a science built on continuous recording needs people who watch the stream, and they take the same professional name.","whyCN":"建立在连续记录之上的科学需要有人盯着数据流，这些人也用同一个职业名称。"},{"no":"03","title":"A reader of seismograms","titleCN":"解读地震记录图的人","definition":"a specialist who locates an event and estimates its size from recorded traces","definitionCN":"根据记录曲线定位事件并估算其大小的专业人员","example":"A seismologist fixed the depth of the focus within a minute.","exampleCN":"一位地震学家在一分钟内定出了震源深度。","why":"the trace is the primary evidence, so the person who can read it is named by the discipline rather than by the instrument.","whyCN":"记录曲线是首要证据，因此能读懂它的人按学科而非按仪器命名。"},{"no":"04","title":"A field instrument deployer","titleCN":"野外布设仪器的人","definition":"a scientist who installs and services stations in remote or temporary sites","definitionCN":"在偏远或临时场地安装并维护台站的科研人员","example":"The field seismologist carried three sensors up the ridge.","exampleCN":"野外地震工作者把三台传感器背上了山脊。","why":"field marks the branch that leaves the observatory, but the title still comes from the shared discipline.","whyCN":"field 标出离开观测台的那一支，但头衔仍来自共同学科。"},{"no":"05","title":"An exploration seismologist","titleCN":"勘探地震学家","definition":"a specialist who uses controlled seismic sources to image rock for industry","definitionCN":"用可控震源为工业目的给岩层成像的专家","example":"The exploration seismologist picked the salt boundary by hand.","exampleCN":"勘探地震学家手工拾取了盐层边界。","why":"the same training serves a commercial goal, and the compound title records that shift of purpose.","whyCN":"同样的训练服务于商业目标，复合头衔记录了这一用途转变。"},{"no":"06","title":"A planetary seismologist","titleCN":"行星地震学家","definition":"a scientist who applies seismic methods to the Moon, Mars or other solid bodies","definitionCN":"把地震方法用于月球、火星或其他固态天体的科学家","example":"A planetary seismologist compared moonquakes with terrestrial ones.","exampleCN":"一位行星地震学家把月震与地球地震作了比较。","why":"planet names the object rather than the method, showing that the profession travels with the instrument.","whyCN":"planet 指对象而非方法，说明这一职业随仪器一起旅行。"},{"no":"07","title":"An engineering seismologist","titleCN":"工程地震学家","definition":"a specialist who turns seismic hazard into values used for structural design","definitionCN":"把地震危险转化为结构设计所用参数的专家","example":"The engineering seismologist supplied the design spectrum for the bridge.","exampleCN":"工程地震学家提供了这座桥的设计反应谱。","why":"engineering marks the branch whose output is a number a builder can use, not a paper.","whyCN":"engineering 标出这样一支：它的产出是建造者能用的数字，而不是论文。"},{"no":"08","title":"A historical seismologist","titleCN":"历史地震学家","definition":"a researcher who reconstructs past earthquakes from old records, diaries and damage reports","definitionCN":"从旧记录、日记与灾害报告中重建过去地震的研究者","example":"The historical seismologist found a quake missing from every catalogue.","exampleCN":"这位历史地震学家发现了一次在所有目录中都缺失的地震。","why":"history marks the branch that reads paper rather than rock, yet asks the same question about the same event.","whyCN":"history 标出读纸而非读岩的那一支，但它对同一事件提出同样的问题。"}],"etymology":{"intro":{"en":"Seismologist is seismology plus -ist, a Greek-derived agent suffix. The base goes back to Greek seismos, earthquake, and -logia, study. The whole word is a modern English formation with no Latin ancestor.","cn":"seismologist 是 seismology 加 -ist，后者是希腊来源的施事后缀。词基上溯希腊 seismos「地震」与 -logia「研究」。整个词是近代英语构词，没有拉丁语祖先。"},"items":[{"era":"GREEK SEISMOS","en":"Seismos, a shaking or earthquake, comes from seiein, to shake. The pre-Greek root is unattested and any older form is reconstructed.","cn":"seismos「震动、地震」来自 seiein「摇动」。其希腊语之前的词根没有实证，任何更早形式均属重构。"},{"era":"GREEK -ISTES","en":"The suffix -istes named a person engaged in an action or profession, and it reaches English as -ist in scientist, geologist and seismologist.","cn":"后缀 -istes 指从事某动作或职业的人，进入英语作 -ist，见于 scientist、geologist 与 seismologist。"},{"era":"NINETEENTH-CENTURY SCIENCE","en":"As seismology took shape in the 1850s, seismologist appeared for the people who measured and catalogued earthquakes.","cn":"随着地震学在 1850 年代成形，seismologist 出现，指测量与编目地震的人。"},{"era":"SPECIALIST TITLES","en":"In the twentieth century compounds such as field, exploration, engineering and planetary seismologist marked new workplaces for the same training.","cn":"到 20 世纪，field、exploration、engineering、planetary 等复合头衔标出同样训练所去的新工作场所。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): the earliest printed use of seismologist is not precisely dated and is usually placed in the second half of the nineteenth century.","cn":"来源不确定（仅首见年代）：seismologist 最早的印刷用例没有精确年代，通常被定在 19 世纪后半叶。"}]},"similar":{"note":{"en":"Group one holds words from the same stem that differ only in suffix; group two holds neighbouring earth-science professions.","cn":"第一组是同出词干、只差后缀的词；第二组是相邻的地球科学职业。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seismology","ipa":"/siːzˈmɒlədʒi/","tag":"the discipline","definition":"The science itself; -logy names the field, while -ist names the person who works in it.","definitionCN":"学科本身；-logy 命名领域，-ist 命名在其中工作的人。"},{"word":"seismological","ipa":"/ˌsiːzməˈlɒdʒɪkl/","tag":"adjective form","definition":"Relating to seismology, as in seismological observatory; it describes things, not people.","definitionCN":"与地震学有关，如地震观测台；描述事物，不描述人。"},{"word":"seismogram","ipa":"/ˈsiːzməɡræm/","tag":"the record","definition":"The paper or digital trace a seismologist reads; it is the object, not the reader.","definitionCN":"地震学家所读的纸质或数字曲线；是对象，不是读者。"},{"word":"seismometer","ipa":"/siːzˈmɒmɪtə/","tag":"the instrument","definition":"The sensor that measures motion; -meter marks a device, in contrast with the person suffix -ist.","definitionCN":"测量运动的传感器；-meter 标记装置，与表人的 -ist 形成对照。"}]},{"heading":"NEAR MEANING","entries":[{"word":"geophysicist","ipa":"/ˌdʒiːəʊˈfɪzɪsɪst/","tag":"broader profession","definition":"A scientist of the earth's physical properties in general; a seismologist is one kind of geophysicist.","definitionCN":"研究地球物理性质的总称；地震学家是地球物理学家的一种。"},{"word":"geologist","ipa":"/dʒiˈɒlədʒɪst/","tag":"rock and history","definition":"A scientist of rocks and strata; the two overlap in the field but study different evidence.","definitionCN":"研究岩石与地层的科学家；两者在野外有交集，但所研究的证据不同。"},{"word":"volcanologist","ipa":"/vɒlˈkænəlɒdʒɪst/","tag":"sister profession","definition":"A specialist in volcanoes; often works beside a seismologist because moving magma produces tremor.","definitionCN":"研究火山的专家；常与地震学家并肩工作，因为岩浆运移会产生颤动。"},{"word":"observatory staffer","ipa":"/əbˈzɜːvətəri ˈstɑːfə/","tag":"role, not title","definition":"A general description of someone who works at an observatory; it does not claim scientific training in seismology.","definitionCN":"对在观测台工作者的泛称；并不表示受过地震学的科学训练。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"seismology + -ist: the person who practises the study of earthquakes.","cn":"seismology + -ist：从事地震研究的人。"},{"en":"The title set runs seismologist, seismologists, seismology, seismological, seismologically.","cn":"头衔词族包括 seismologist、seismologists、seismology、seismological、seismologically。"},{"en":"Specialist compounds: field, exploration, engineering, planetary and historical seismologist.","cn":"专业复合词：野外、勘探、工程、行星与历史地震学家。"},{"en":"The instrument words end in -graph, -meter, -gram; the person word ends in -ist.","cn":"仪器词以 -graph、-meter、-gram 结尾；表人的词以 -ist 结尾。"},{"en":"News usage fixes the phrase: seismologists estimate the magnitude within minutes.","cn":"新闻用法固定了搭配：地震学家在几分钟内估算震级。"}],"abstract":[{"en":"Picture a translator who listens to the ground and writes down what it said.","cn":"想象一位译者，听取大地的声音，再把它写下。"},{"en":"Picture a detective arriving after the event and reading the damage as testimony.","cn":"想象一位侦探在事件之后赶到，把破坏读成证词。"},{"en":"Picture a lighthouse keeper, except the light is pointed inward at the planet.","cn":"想象一位灯塔看守，只是灯不是向外照，而是照向行星内部。"}]},"examples":[{"en":"The seismologist on duty called the emergency office before the shaking reached the city.","cn":"值班地震学家在震动抵达城市之前打电话给了应急部门。"},{"en":"A seismologist can tell a quarry blast from a natural quake by the trace.","cn":"地震学家能从记录曲线上分辨采石场爆破与天然地震。"},{"en":"The team included a seismologist, a geologist and two engineers.","cn":"团队包括一位地震学家、一位地质学家和两位工程师。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「seismo（地震）+ logist（学者）」——研究地震的学者 → 地震学家","word":"seismologist"},"root":"希腊 seismos「地震」+ -logia「研究」+ -istes「从事……的人」→ 英语 seismologist。希腊来源，无拉丁同族，拉丁词条留空。","sensesIntro":{"en":"Eight senses follow one profession through its workplaces: the researcher, the network analyst, the trace reader, the field hand, the exploration hand, the planetary hand, the engineering hand and the historian of old paper.","cn":"八个义项跟随同一职业走过不同工作场所：研究者、台网分析员、曲线解读者、野外人员、勘探人员、行星人员、工程人员，以及读旧纸的历史研究者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person bent over a long paper strip, pencil in hand, marking the exact moment a wave arrived.","cn":"核心意象：一个人俯身在长条纸带前，手握铅笔，标出波到达的准确时刻。"},"chain":["EARTHQUAKE RESEARCHER","TRACE READER","NETWORK ANALYST","FIELD DEPLOYER","SPECIALIST BRANCHES","PROFESSION"],"branches":[{"senses":"S1 · S3","en":"CORE SKILL: reading the record and turning it into an event with place, depth and size.","cn":"核心技能：读记录，并把它转成带有位置、深度与大小的事件。"},{"senses":"S2","en":"WATCHING THE STREAM: the network analyst keeps the record continuous.","cn":"盯住数据流：台网分析员让记录保持连续。"},{"senses":"S4","en":"LEAVING THE BUILDING: the field worker carries the instrument to where the signal is.","cn":"走出大楼：野外人员把仪器背到信号所在之处。"},{"senses":"S5 · S6","en":"OTHER GOALS AND OTHER WORLDS: the same training serves industry or another planet.","cn":"别的目标与别的世界：同样的训练服务工业，或服务另一颗行星。"},{"senses":"S7 · S8","en":"SERVICE AND MEMORY: one turns hazard into design values, the other recovers forgotten events.","cn":"服务与记忆：一个把危险变成设计参数，一个找回被遗忘的事件。"}]},"affixes":{"intro":{"en":"Seismologist is a three-part build: an earthquake stem, a study suffix and a person suffix, all from Greek.","cn":"seismologist 由三部分构成：「地震」词干、「研究」后缀与「人」后缀，全部来自希腊语。"},"latinIntro":{"en":"No Latin element enters the word; Latin appears only in the later language of scientific publication.","cn":"这个词里没有拉丁成分；拉丁语只出现在后来作为科学出版语言的层面。"},"items":[{"word":"seismo-","structure":"seismo- (Greek combining form, 'earthquake')","meaning":"earthquake","meaningCN":"地震","example":"Seismo- names the subject of the profession.","exampleCN":"seismo- 点明这一职业的研究对象。"},{"word":"seismos","structure":"seismos (Greek noun, 'a shaking')","meaning":"a shaking, an earthquake","meaningCN":"震动；地震","example":"The noun reaches English through scientific borrowing.","exampleCN":"这个名词经科学借词进入英语。"},{"word":"-logy","structure":"-logia (Greek suffix, 'study of')","meaning":"the study of","meaningCN":"对……的研究","example":"-Logy turns the subject into a discipline.","exampleCN":"-logy 把研究对象变成一门学科。"},{"word":"-ist","structure":"-istes (Greek agent suffix)","meaning":"a person who practises","meaningCN":"从事……的人","example":"-Ist turns the discipline into a profession.","exampleCN":"-ist 把学科变成一种职业。"},{"word":"seismology","structure":"seismos + -logia","meaning":"the study of earthquakes","meaningCN":"地震学","example":"Seismology supplied the base noun.","exampleCN":"seismology 提供了基础名词。"},{"word":"seismologist","structure":"seismology + -ist","meaning":"one who practises seismology","meaningCN":"从事地震学的人","example":"The seismologist checked the station log.","exampleCN":"地震学家核对了台站日志。"},{"word":"seismological","structure":"seismology + -ical (relating to)","meaning":"relating to seismology","meaningCN":"地震学的","example":"The seismological staff meets each morning.","exampleCN":"地震学人员每天早晨开会。"},{"word":"seismograph","structure":"seismo- + -graph (writing)","meaning":"an instrument that records shaking","meaningCN":"记录震动的仪器","example":"The seismograph ran on a clockwork drum.","exampleCN":"那台地震仪靠发条滚筒运转。"},{"word":"seismogram","structure":"seismo- + -gram (written thing)","meaning":"the record produced by the instrument","meaningCN":"仪器产生的记录","example":"The seismogram is the primary evidence.","exampleCN":"地震记录图是首要证据。"},{"word":"seismometer","structure":"seismo- + -meter (measure)","meaning":"a sensor for ground motion","meaningCN":"测量地面运动的传感器","example":"The seismometer needs a level base.","exampleCN":"地震计需要水平底座。"}],"latinEntries":[]}},{"word":"earthquake","ipa_uk":"/ˈɜːθkweɪk/","ipa_us":"/ˈɜːrθkweɪk/","definition_zh":"地震；地面震动；（比喻）剧烈动荡","definition_en":"a sudden shaking of the ground caused by movement along a fault or by volcanic activity","core_image":"铺地的砖石被摇得互相错位，墙上一道裂缝从上到下张开","scene":"小城广场上，铺地的砖石被摇得互相错动，路灯在晃。 The earthquake knocked down two walls but left the square intact.","sceneCN":"这里 earthquake 是「地震」（第 1 个义项：由断层错动或火山活动引起的地面突然震动）；句意为这场地震震塌了两堵墙，却让广场本身完好无损。","pos":[{"tag":"n.","zh":"地震；地面震动；（比喻）剧烈动荡"}],"collocations":[{"phrase":"a strong earthquake","zh":"一场强烈地震"},{"phrase":"earthquake damage","zh":"地震破坏"},{"phrase":"earthquake zone","zh":"地震区"},{"phrase":"earthquake insurance","zh":"地震保险"},{"phrase":"earthquake magnitude","zh":"地震震级"},{"phrase":"earthquake drill","zh":"地震演练"}],"forms":[{"label":"名词单数","form":"earthquake"},{"label":"名词复数","form":"earthquakes"},{"label":"所有格","form":"earthquake's"},{"label":"复合形容词（抗震的）","form":"earthquake-resistant"},{"label":"复合形容词（易受地震影响的）","form":"earthquake-prone"}],"derivatives":[{"word":"quake","pos":"n./v.","zh":"地震（口语截短）；震动、发抖"},{"word":"earthquake-proof","pos":"adj.","zh":"防震的"},{"word":"earthquake-resistant","pos":"adj.","zh":"抗震的"},{"word":"earthquake-prone","pos":"adj.","zh":"地震多发的"},{"word":"earthshaking","pos":"adj.","zh":"震撼世界的（由 earth + shake 另构，并非 earthquake 的直接派生）"}],"senses":[{"no":"01","title":"Shaking of the ground","titleCN":"地面的突然震动","definition":"a sudden shaking of the ground caused by the release of strain along a fault","definitionCN":"断层上的应变释放所引起的地面突然震动","example":"The earthquake knocked down two walls but left the square intact.","exampleCN":"这场地震震塌了两堵墙，却让广场本身完好无损。","why":"earthquake is a plain English compound: earth plus quake, a shaking, so the word names the ground doing what the verb means.","whyCN":"earthquake 是朴素的英语复合词：earth「大地」加 quake「震动」，词面就是大地在震。"},{"no":"02","title":"A recorded seismic event","titleCN":"被记录的一次地震事件","definition":"a single event entered in a catalogue with a time, location, depth and magnitude","definitionCN":"以时间、位置、深度与震级登记入目录的一次事件","example":"The catalogue lists three earthquakes within ten kilometres of the town.","exampleCN":"目录列出该镇十公里范围内的三次地震。","why":"once networks record events, earthquake becomes a countable unit of data rather than only an experience.","whyCN":"当台网记录事件之后，earthquake 就不只是人的体验，而成为可计数的数据单位。"},{"no":"03","title":"The main shock of a sequence","titleCN":"序列中的主震","definition":"the largest event of a sequence, distinguished from the smaller foreshocks and aftershocks","definitionCN":"一次序列中最大的事件，区别于较小的前震与余震","example":"The earthquake was followed by forty smaller shocks that night.","exampleCN":"那晚主震之后又发生了四十次较小的震动。","why":"a sequence needs a head, so the plain noun came to mean the main shock and the others received prefixed names.","whyCN":"一个序列需要有一个头，因此朴素名词被用来指主震，其余事件则获得带前缀的名称。"},{"no":"04","title":"An induced earthquake","titleCN":"人类活动诱发的地震","definition":"a quake triggered by human activity such as reservoir filling, mining or fluid injection","definitionCN":"由水库蓄水、采矿或流体注入等人类活动触发的地震","example":"The injection well caused an earthquake large enough to crack nearby foundations.","exampleCN":"注入井引发了足以震裂附近地基的地震。","why":"the mechanism differs but the shaking is the same, so the same noun is kept with an adjective of cause.","whyCN":"机制不同，但震动本身相同，因此保留同一个名词，另加表示成因的形容词。"},{"no":"05","title":"A quake on another world","titleCN":"其他天体上的地震","definition":"a seismic event on the Moon, Mars or another solid body","definitionCN":"月球、火星或其他固态天体上的地震事件","example":"Instruments left on the Moon recorded an earthquake deep in its crust.","exampleCN":"留在月面的仪器记录到月壳深处的一次地震。","why":"the word is extended literally to other bodies, though specialists often prefer moonquake or marsquake.","whyCN":"该词被字面扩展到其他天体，尽管专家往往更爱用 moonquake 或 marsquake。"},{"no":"06","title":"A violent upheaval in society","titleCN":"社会的剧烈动荡","definition":"a sudden, far-reaching change that shakes the established order","definitionCN":"突然而深远、动摇既有秩序的变化","example":"The reform was an earthquake in the country's legal tradition.","exampleCN":"这次改革是该国法律传统中的一场地震。","why":"the metaphor borrows the physical event wholesale: what shakes is no longer ground but an institution.","whyCN":"这个比喻整体借用了物理事件：被摇动的不再是地面，而是一套制度。"},{"no":"07","title":"A shock to a market or organization","titleCN":"对市场或组织的巨大冲击","definition":"a disruptive shock that forces rapid restructuring in business or finance","definitionCN":"迫使商业或金融迅速重组的颠覆性冲击","example":"The collapse of the carrier was an earthquake for regional airports.","exampleCN":"这家航空公司的倒闭对地区机场是一场地震。","why":"economic writing uses the same metaphor because markets, like ground, can lose their bearings.","whyCN":"经济写作使用同一比喻，因为市场与地面一样会失去依托。"},{"no":"08","title":"A disaster category","titleCN":"灾害与保险中的地震类别","definition":"a class of natural disaster used in relief planning, insurance and building codes","definitionCN":"用于救援规划、保险与建筑规范的一类自然灾害","example":"The policy covers earthquake but not flooding.","exampleCN":"该保单承保地震，但不承保洪水。","why":"institutions need to sort hazards into named categories, and the everyday word becomes an administrative one.","whyCN":"机构需要把危险归入有名字的类别，于是日常词变成了行政术语。"}],"etymology":{"intro":{"en":"Earthquake is a native English compound of earth, from Old English eorþe, and quake, from Old English cwacian, to tremble. It is recorded in English from the late thirteenth century and has no Latin ancestor.","cn":"earthquake 是英语本族复合词：earth 来自古英语 eorþe，quake 来自古英语 cwacian「颤抖」。英语文献中自 13 世纪后期即有记录，没有拉丁语祖先。"},"items":[{"era":"OLD ENGLISH EARTH","en":"Eorþe meant the ground, soil or the world; it survives as earth in modern English and supplies the first element of the compound.","cn":"eorþe 指大地、土壤或世界；它在现代英语中存为 earth，并构成这个复合词的前一部分。"},{"era":"OLD ENGLISH CWACIAN","en":"Cwacian meant to tremble or shake; its noun quake first meant a trembling of the body before it was applied to the ground.","cn":"cwacian 意为颤抖或摇动；其名词 quake 最初指身体的发抖，后来才用于地面。"},{"era":"THIRTEENTH-CENTURY COMPOUND","en":"English joined the two words in the late thirteenth century, at first in forms such as eorþe-cwace, to name the ground shaking.","cn":"英语在 13 世纪后期把两个词拼合，早期形式如 eorþe-cwace，用来指地面震动。"},{"era":"SCIENTIFIC TERM","en":"From the seventeenth century the word entered scientific writing, and later catalogues made each event a countable unit.","cn":"从 17 世纪起，该词进入科学写作；后来的地震目录把每次事件变成可计数的单位。"},{"era":"METAPHOR","en":"Modern usage extends earthquake figuratively to political, social and economic shocks that rearrange the ground under an institution.","cn":"现代用法把 earthquake 比喻扩展到政治、社会与经济冲击，它们重新排布制度脚下的地面。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): the earliest recorded spelling varies between eorþe-cwace and earthquake, and the exact first citation date is given only approximately.","cn":"来源不确定（仅首见年代）：最早的拼写形式在 eorþe-cwace 与 earthquake 之间不同，确切的最早书证年代只能给约数。"}]},"similar":{"note":{"en":"Group one holds the English words built from the same two elements; group two holds terms for shaking events and for upheavals.","cn":"第一组是由同样两个成分构成的英语词；第二组是表示震动事件与剧变的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"quake","ipa":"/kweɪk/","tag":"clipped form","definition":"The second element used alone: a verb meaning to tremble, and an informal noun for an earthquake.","definitionCN":"单独使用的后一成分：动词指颤抖，口语名词指地震。"},{"word":"earthshaking","ipa":"/ˈɜːθʃeɪkɪŋ/","tag":"parallel compound","definition":"Built on earth plus shake rather than quake, and now mostly figurative for overwhelmingly important.","definitionCN":"由 earth 加 shake 而非 quake 构成，如今多作比喻指「极其重大」。"},{"word":"earthquake-proof","ipa":"/ˈɜːθkweɪk pruːf/","tag":"compound adjective","definition":"Earthquake plus proof in the sense of resistant: built so as not to fail in a quake.","definitionCN":"earthquake 加 proof（意为「抗」）：建造得能在震中不失效。"},{"word":"earthquake-prone","ipa":"/ˈɜːθkweɪk prəʊn/","tag":"compound adjective","definition":"Earthquake plus prone: describing a region likely to experience quakes.","definitionCN":"earthquake 加 prone：描述容易发生地震的地区。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tremor","ipa":"/ˈtremə/","tag":"smaller shaking","definition":"A minor earthquake or a continuous shaking; it is usually weaker than an earthquake and can also mean a bodily shake.","definitionCN":"小地震或持续的轻微震动；通常比 earthquake 弱，也可指身体颤抖。"},{"word":"shock","ipa":"/ʃɒk/","tag":"sudden jolt","definition":"A sudden violent jolt, whether seismic, electrical or emotional; it names the impact rather than the geological event.","definitionCN":"突然的猛烈冲击，可以是地震的、电的或情绪的；指冲击而非地质事件。"},{"word":"temblor","ipa":"/ˈtemlə/","tag":"regional synonym","definition":"A chiefly American Spanish-derived term for an earthquake, common in news from seismic regions.","definitionCN":"主要在美国使用、源自西班牙语的「地震」说法，常见于地震区新闻。"},{"word":"upheaval","ipa":"/ʌpˈhiːvl/","tag":"social metaphor","definition":"A violent or major change in society or a person's life; unlike earthquake it has no literal geological use.","definitionCN":"社会或个人生活中的剧烈重大变化；与 earthquake 不同，它没有字面地质用法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"earth + quake: the ground doing the trembling.","cn":"earth + quake：大地在发抖。"},{"en":"The family runs earthquake, earthquakes, quake, earthquake-proof, earthquake-resistant, earthquake-prone.","cn":"同族词包括 earthquake、earthquakes、quake、earthquake-proof、earthquake-resistant、earthquake-prone。"},{"en":"Fixed phrases: earthquake damage, earthquake zone, earthquake drill, earthquake insurance.","cn":"固定搭配：地震破坏、地震区、地震演练、地震保险。"},{"en":"News usage: a strong earthquake struck at dawn; the magnitude was revised upward.","cn":"新闻用法：一场强震在黎明袭击；震级被上调。"},{"en":"The -quake element also appears in moonquake and marsquake for other bodies.","cn":"-quake 成分也出现在指其他天体的 moonquake 与 marsquake 中。"}],"abstract":[{"en":"Picture a boardroom table splitting down the middle during a vote.","cn":"想象一张董事会议桌在投票时从中间裂开。"},{"en":"Picture a price list whose numbers all change while the shopkeeper is still writing.","cn":"想象店主还在写价目表，上面的数字就全变了。"},{"en":"Picture a constitution whose paragraphs slide past one another like fault blocks.","cn":"想象一部宪法的条款像断块一样互相错动。"}]},"examples":[{"en":"The earthquake destroyed the old bridge and cut the only road.","cn":"地震摧毁了那座旧桥，切断了唯一的道路。"},{"en":"Engineers design hospitals to remain open after a major earthquake.","cn":"工程师把医院设计成在大地震后仍能运转。"},{"en":"The discovery of the letters was an earthquake in the study of the period.","cn":"这批信件的发现使该时期的研究发生了地震般的震荡。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「earth（大地）+ quake（抖）」——大地发抖 → 地震","word":"earthquake"},"root":"英语本族复合词：古英语 eorþe「大地」+ cwacian「颤抖」的名词 quake；无拉丁同族，拉丁词条留空。","sensesIntro":{"en":"Eight senses follow one shaking from ground to catalogue: the physical event, the recorded event, the main shock, the human-caused and off-world variants, then society, markets and finally the administrative category.","cn":"八个义项让同一场震动从地面走进目录：物理事件、被记录的事件、主震、人为与地外变体，再到社会、市场，最后成为行政类别。"},"semanticMap":{"core":{"en":"CORE IMAGE: paving stones shifted out of line and a crack opening down a wall.","cn":"核心意象：铺地砖石错位，墙体从上到下裂开。"},"chain":["GROUND SHAKING","RECORDED EVENT","MAIN SHOCK","HUMAN TRIGGER","OTHER WORLD","SOCIAL UPHEAVAL"],"branches":[{"senses":"S1","en":"THE PHYSICAL EVENT: the ground moves because strain is released.","cn":"物理事件：应变释放，地面因此移动。"},{"senses":"S2 · S3","en":"THE CATALOGUE: an event becomes a row of data, with a head and smaller followers.","cn":"目录：事件变成一行数据，有头部，也有较小的跟随者。"},{"senses":"S4 · S5","en":"CHANGED CAUSE AND PLACE: humans can trigger it, and other worlds can host it.","cn":"成因与场所的变换：人类可以触发它，别的世界也可以承载它。"},{"senses":"S6 · S7","en":"METAPHOR: institutions and markets are shaken until their old alignments fail.","cn":"比喻：制度与市场被摇到旧有对齐失效。"},{"senses":"S8","en":"ADMINISTRATIVE BOX: the event becomes a category that policies and codes refer to.","cn":"行政归类：事件变成一个保单与规范可以引用的类别。"}]},"affixes":{"intro":{"en":"Earthquake is a native compound of two free morphemes, and its second element also lives alone as a verb and an informal noun.","cn":"earthquake 是由两个自由语素构成的本族复合词，其第二成分也能独立作动词与口语名词。"},"latinIntro":{"en":"No Latin elements are involved: both halves are inherited Germanic words, though Latin terra and quatere are only semantic parallels, not sources.","cn":"不涉及拉丁成分：两半都是继承的日耳曼语词；拉丁 terra 与 quatere 只是语义上的平行词，并非来源。"},"items":[{"word":"earth","structure":"earth (Old English eorþe, 'ground, soil')","meaning":"the ground; the planet","meaningCN":"大地；地球","example":"Earth supplies the object being shaken.","exampleCN":"earth 提供被摇动的对象。"},{"word":"quake","structure":"quake (Old English cwacian, 'to tremble')","meaning":"to shake; a shaking","meaningCN":"震动；一次震动","example":"Quake supplies the event.","exampleCN":"quake 提供事件本身。"},{"word":"-quake","structure":"combining element from quake","meaning":"a shaking of a named body","meaningCN":"某天体的一次震动","example":"Moonquake and marsquake use the same element.","exampleCN":"moonquake 与 marsquake 使用同一成分。"},{"word":"earthquake","structure":"earth + quake","meaning":"a shaking of the ground","meaningCN":"地面震动","example":"The earthquake lasted less than a minute.","exampleCN":"那次地震持续不到一分钟。"},{"word":"earthquakes","structure":"earthquake + -s (plural)","meaning":"more than one quake","meaningCN":"多次地震","example":"The region records hundreds of earthquakes each year.","exampleCN":"该地区每年记录数百次地震。"},{"word":"earthquake-proof","structure":"earthquake + proof (resistant)","meaning":"able to resist a quake","meaningCN":"防震的","example":"The shelter is earthquake-proof by design.","exampleCN":"这座避难所按防震标准设计。"},{"word":"earthquake-resistant","structure":"earthquake + resistant","meaning":"built to withstand shaking","meaningCN":"抗震的","example":"Earthquake-resistant frames flex without collapsing.","exampleCN":"抗震框架会弯曲而不倒塌。"},{"word":"earthquake-prone","structure":"earthquake + prone","meaning":"likely to experience quakes","meaningCN":"易发生地震的","example":"The valley is earthquake-prone.","exampleCN":"这条谷地易发地震。"},{"word":"earthshaking","structure":"earth + shake + -ing","meaning":"world-shaking; hugely important","meaningCN":"震撼世界的；极其重大的","example":"The ruling was earthshaking for the industry.","exampleCN":"这项裁决对该行业是震撼性的。"}],"latinEntries":[]}},{"word":"tremor","ipa_uk":"/ˈtremə/","ipa_us":"/ˈtremər/","definition_zh":"轻微地震；颤动；（身体或声音的）颤抖；不自主震颤；轻微的动荡","definition_en":"a small involuntary shaking of the body, or a slight quivering of the ground, a voice or a machine","core_image":"一只手平放在桌面上，指尖却在细密地抖动，桌面落着一层薄薄的灰","scene":"深夜的地震观测室里，纸带记录仪忽然划出一小段密集的锯齿。 A faint tremor rattled the instruments on the shelf just after midnight.","sceneCN":"这里 tremor 是名词「微震、轻微地震」（第 1 个义项：规模较小、常成串出现的地震）；句意为午夜刚过，一次微弱的地震让架上的仪器轻轻震动。","pos":[{"tag":"n.","zh":"轻微地震；颤动；不自主震颤；声音的颤抖；轻微的动荡"}],"collocations":[{"phrase":"earth tremor","zh":"轻微地震；地面颤动"},{"phrase":"volcanic tremor","zh":"火山颤动"},{"phrase":"intentional tremor","zh":"意向性震颤（接近目标动作时加重）"},{"phrase":"a tremor in the voice","zh":"声音里的颤抖"},{"phrase":"tremor of excitement","zh":"兴奋引起的颤抖"},{"phrase":"harmonic tremor","zh":"谐波颤动（火山学用语）"}],"forms":[{"label":"名词复数","form":"tremors"},{"label":"单数所有格","form":"tremor's"},{"label":"复数所有格","form":"tremors'"},{"label":"名词作定语（保持原形）","form":"tremor"}],"derivatives":[{"word":"tremble","pos":"v.","zh":"发抖；轻轻颤动"},{"word":"tremulous","pos":"adj.","zh":"颤抖的；怯生生的"},{"word":"tremendous","pos":"adj.","zh":"巨大的；惊人的（源自「令人发抖」的拉丁动名词）"},{"word":"tremolo","pos":"n.","zh":"（音乐）颤音；管风琴的颤音装置"},{"word":"tremulant","pos":"adj./n.","zh":"颤动的；（管风琴）颤音音栓"}],"senses":[{"no":"01","title":"A small earthquake","titleCN":"轻微地震","definition":"a small earthquake, especially one of many that follow or precede a larger shock","definitionCN":"规模较小的地震，尤指主震前后成串出现的余震或前震","example":"A series of tremors followed the main shock.","exampleCN":"主震之后跟着一连串微震。","why":"Latin tremor named any trembling at all; seismology narrowed the word to small shocks that are clearly weaker than the main earthquake.","whyCN":"拉丁 tremor 本指任何颤抖；地震学把这个词收窄为明显弱于主震的小震。"},{"no":"02","title":"Involuntary shaking of the body","titleCN":"身体不自主地震颤","definition":"an involuntary, rhythmic shaking of part of the body, often caused by a neurological disorder or by a drug","definitionCN":"身体某部分不由自主、有节律地抖动，常由神经系统疾病或药物引起","example":"The new medication reduced the tremor in his hands.","exampleCN":"新药减轻了他双手的震颤。","why":"medicine kept the oldest sense of the Latin noun and made it clinical: a tremor is shaking the patient cannot stop.","whyCN":"医学保留了这一拉丁名词最古老的意义并使之临床化：震颤是病人止不住的抖动。"},{"no":"03","title":"A quaver from emotion","titleCN":"情绪引起的手或声音发抖","definition":"a slight shaking of the hands or voice caused by fear, cold, anger or excitement","definitionCN":"因恐惧、寒冷、愤怒或激动而出现的手部或声音的轻微发抖","example":"She answered with a slight tremor in her voice.","exampleCN":"她回答时声音微微发颤。","why":"the physical sense extends to the voice because the same muscles that shake the hand also shake the throat.","whyCN":"这一身体义能扩展到声音，是因为让手发抖的肌肉同样会让喉咙发抖。"},{"no":"04","title":"A slight shaking of the ground","titleCN":"地面的轻微震动","definition":"a faint shaking of the ground that is weaker than a real earthquake, as from traffic, blasting or a distant quake","definitionCN":"比真正地震更弱的地面抖动，可来自车辆、爆破或远处的地震","example":"A passing train sent a tremor through the floor.","exampleCN":"一辆过路的火车让地板传来一阵颤动。","why":"once the noun meant any shaking, it was natural to use it for ground movement that is felt but does not qualify as an earthquake.","whyCN":"既然这个名词本指任何抖动，用它来表示「能感觉到但算不上地震」的地面运动就很自然。"},{"no":"05","title":"Volcanic tremor","titleCN":"火山颤动","definition":"a continuous rhythmic ground vibration at a volcano, generated by the movement of magma or hydrothermal fluids","definitionCN":"火山处持续的、有节律的地面振动，由岩浆或热液流体的运动产生","example":"Harmonic tremor often precedes an eruption.","exampleCN":"谐波颤动常常出现在喷发之前。","why":"volcanology needed a word for shaking that lasts minutes to hours, unlike the sharp jolt of a tectonic quake, and borrowed the medical-seismic noun.","whyCN":"火山学需要一个词指持续数分钟到数小时的抖动，以区别于构造地震的骤然一震，于是借用了这个兼有医学与地震含义的名词。"},{"no":"06","title":"A quaver in music or speech","titleCN":"声音的颤音","definition":"a rapid, slight fluctuation of pitch in a singing voice or in the sound of an instrument","definitionCN":"歌声或乐器声中音高快速而轻微的起伏","example":"The singer's tremor added warmth to the long final note.","exampleCN":"歌手那一点颤抖让结尾的长音更有温度。","why":"the emotional quaver of sense three becomes a deliberate expressive device when a performer controls it.","whyCN":"第三个义项里情绪性的颤抖，一旦被表演者控制，就成了有意的表现手段。"},{"no":"07","title":"Mild social or political unrest","titleCN":"社会或政治的轻微动荡","definition":"a slight wave of unrest or anxiety passing through a group, institution or society","definitionCN":"在群体、机构或社会中掠过的一阵轻微不安或动荡","example":"Tremors of discontent ran through the party after the vote.","exampleCN":"投票之后，不满的微澜掠过整个政党。","why":"the image of a body shaking without falling apart fits a society that is disturbed but not yet broken.","whyCN":"身体抖动却尚未散架的意象，正好对应一个受到扰动但还未破裂的社会。"},{"no":"08","title":"Sustained mechanical or acoustic vibration","titleCN":"声学或机械的持续振动","definition":"a continuous low-level vibration measured in a machine, a structure or a sound field","definitionCN":"在机器、结构或声场中被测量到的持续低频振动","example":"Engineers measured the tremor of the turbine housing.","exampleCN":"工程师测量了涡轮外壳的持续振动。","why":"engineering uses the word for unwanted steady shaking that is weaker than a fault but still tells a story about wear.","whyCN":"工程上用这个词指不受欢迎的稳定抖动，它比故障轻，却仍然透露磨损的信息。"}],"etymology":{"intro":{"en":"Tremor comes from Latin tremor, a trembling, a noun built on the verb tremere, to tremble or quake. It entered English in the fourteenth century through medical writing and later acquired seismic, musical and engineering senses.","cn":"tremor 来自拉丁 tremor「颤抖」，是建于动词 tremere「发抖、震动」之上的名词。该词于十四世纪经医学著作进入英语，后来又发展出地震、音乐与工程方面的义项。"},"items":[{"era":"LATIN TREMERE","en":"Tremere meant to shake, quake or tremble with fear. It is the verb behind the whole English family, including tremble, tremulous and tremendous.","cn":"tremere 意为「震动、发抖、因恐惧而颤抖」。它是整个英语同族词的动词来源，包括「发抖」「颤抖的」与「令人发抖的」诸词。"},{"era":"LATIN TREMOR","en":"Tremor was the noun of state, the trembling itself rather than the act of starting to tremble; English took the noun, not the verb.","cn":"tremor 是状态名词，指颤抖本身，而不是「开始发抖」的动作；英语借入的是名词，而非动词。"},{"era":"TREMULUS AND TREMENDUS","en":"Tremulus meant trembling and gave English tremulous. The gerundive tremendus, to be trembled at, gave tremendous, whose modern sense of huge is a later weakening of dreadful.","cn":"tremulus 意为「颤抖的」，衍生出英语中表示「颤抖的」形容词。动名词 tremendus 意为「令人发抖的」，衍生出表示「巨大的」形容词，其现代「庞大」义是「可怕」义的后期弱化。"},{"era":"FRENCH TREMBLER","en":"The everyday verb tremble came through Old French trembler, generally considered a development of Latin tremulare from tremulus rather than a direct borrowing of tremere.","cn":"日常动词「发抖」经古法语而来，一般认为是拉丁 tremulare（出自 tremulus）的发展，而非直接借自 tremere。"},{"era":"MEDICAL AND SEISMIC ENGLISH","en":"Medical texts fixed tremor as the clinical name for involuntary shaking. Seismology then used it for small shocks, and twentieth-century volcanology added volcanic tremor for continuous volcanic shaking.","cn":"医学文献把 tremor 固定为不自主颤抖的临床名称。地震学随后用它指小震，二十世纪的火山学又加上了「火山颤动」这一搭配，指持续的火山抖动。"},{"era":"UNCERTAIN DETAILS","en":"Two tiers of doubt: the first date of the seismic sense is only approximate, a dating question; the deeper root of tremere is usually reconstructed as an Indo-European trembling stem, which is a reconstruction and not a recorded form, a root question.","cn":"来源不确定，分两档：地震义的首见年代只是约数，属年代存疑；tremere 更深的词根通常被重构为一个印欧语「发抖」词干，属重构形式而非有记录的形式，属词根存疑。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin trembling stock; group two holds near neighbours that name other kinds of shaking.","cn":"第一组是同出拉丁「发抖」词干的词；第二组是同样表示抖动的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tremble","ipa":"/ˈtrembl/","tag":"same stock, everyday verb","definition":"To shake with small rapid movements, usually from fear, cold or weakness; it is the plain verb where tremor is the clinical noun.","definitionCN":"以细小的快速动作抖动，通常因恐惧、寒冷或虚弱；tremble 是日常动词，tremor 则是临床名词。"},{"word":"tremulous","ipa":"/ˈtremjələs/","tag":"same stock, adjective","definition":"Shaking slightly, or showing such shaking, as a tremulous voice or a tremulous smile.","definitionCN":"轻微颤抖的，或显出这种颤抖的，如发颤的声音或怯怯的微笑。"},{"word":"tremendous","ipa":"/trɪˈmendəs/","tag":"same stock, shifted sense","definition":"From the Latin gerundive meaning to be trembled at; English shifted it from dreadful to simply enormous.","definitionCN":"来自意为「令人发抖」的拉丁动名词；英语把「可怕」义转为单纯的「巨大」。"},{"word":"tremolo","ipa":"/ˈtremələʊ/","tag":"same stock via Italian","definition":"A musical effect of rapid repeated notes or a wavering tone, borrowed from Italian, where the Latin root kept its shaking sense.","definitionCN":"由快速重复的音或摇摆的音色构成的音乐效果，借自意大利语，那里拉丁词根仍保留抖动义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"shudder","ipa":"/ˈʃʌdə/","tag":"whole-body shake","definition":"A sudden convulsive shaking of the whole body, often from horror or cold; it is stronger and briefer than a tremor.","definitionCN":"全身突然的痉挛式抖动，常因恐惧或寒冷；比 tremor 更强烈也更短促。"},{"word":"quake","ipa":"/kweɪk/","tag":"ground or body shake","definition":"To shake violently, used both of the earth and of a person's limbs; the noun form is the short word for an earthquake.","definitionCN":"剧烈抖动，既用于大地也用于人的四肢；其名词形式是「地震」的简短说法。"},{"word":"vibration","ipa":"/vaɪˈbreɪʃn/","tag":"repeated back-and-forth motion","definition":"A rapid alternation of position about a rest point; it is the physical pattern of which a tremor is one felt instance.","definitionCN":"围绕静止位置快速往复运动；它是物理模式，tremor 则是一次被感觉到的实例。"},{"word":"quiver","ipa":"/ˈkwɪvə/","tag":"fine rapid shaking","definition":"A slight, fine trembling, as of a leaf in wind or a lip before tears; it is softer and more delicate than tremor.","definitionCN":"轻微细密的抖动，如风中的叶子或落泪前的嘴唇；比 tremor 更轻柔细微。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin stem, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的拉丁词干、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"trem- is the shaking stem: Latin tremere shook, and tremor is the shaking itself.","cn":"trem- 是「抖」的词干：拉丁 tremere 是发抖，tremor 就是那阵抖动本身。"},{"en":"The family splits by part of speech: a noun, a daily verb, an adjective of shaking and a musical noun.","cn":"同族按词性分流：一个名词、一个日常动词、一个表示颤抖的形容词与一个音乐名词。"},{"en":"Earth tremor is the mildest seismic word; earthquake names the full event.","cn":"「地面颤动」是最轻的地震说法，「地震」则指完整事件。"},{"en":"Medical texts pair tremor with intention, rest and posture, the three situations that change how it appears.","cn":"医学文献把震颤与意向、静止、姿势三种情形搭配，因为它们会改变震颤的表现。"},{"en":"A tremor in the voice is the body's shaking heard through sound.","cn":"声音里的颤抖，就是身体的抖动被听见。"}],"abstract":[{"en":"Picture a glass of water on a train table, its surface never quite still.","cn":"想象列车小桌上的一杯水，水面始终静不下来。"},{"en":"Picture a singer whose last note wobbles like a plucked wire.","cn":"想象一位歌手，最后一个音像被拨动的金属丝一样摇摆。"},{"en":"Picture a room where everyone speaks calmly but no one meets anyone's eyes.","cn":"想象一间屋子里人人语气平静，却没有人对上彼此的目光。"}]},"examples":[{"en":"The first tremor came before dawn and lasted only a few seconds.","cn":"第一次微震在天亮前到来，只持续了几秒钟。"},{"en":"His hand showed a fine tremor when he tried to write.","cn":"他想写字时，手出现细密的颤抖。"},{"en":"Volcanic tremor is continuous, unlike the sharp jolt of a tectonic quake.","cn":"火山颤动是持续的，不像构造地震那样骤然一震。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「trem（抖）+ or」——手一直抖，地轻轻颤 → 震颤、微震、颤音","word":"tremor"},"root":"拉丁 tremere「发抖、震动」的名词形式 tremor「颤抖」；同族另有形容词 tremulus「颤抖的」与动名词 tremendus「令人发抖的」，经法语还派生出日常动词「发抖」一支。","sensesIntro":{"en":"Eight senses follow one sensation: a fine shaking too weak to break anything. It starts in the body, moves to the voice, then to the ground, then narrows into a small quake, a volcanic signal, a social mood and a machine reading.","cn":"八个义项沿同一种感觉展开：一种细密、弱到不足以弄断任何东西的抖动。它从身体出发，转到声音，再到地面，随后收窄为小震、火山信号、社会情绪与机器读数。"},"semanticMap":{"core":{"en":"CORE IMAGE: a fine rapid shaking that never grows into a full break.","cn":"核心意象：一种细密快速的抖动，始终没有发展成彻底的断裂。"},"chain":["INVOLUNTARY BODY SHAKE","EMOTIONAL QUAVER","GROUND SHAKE","SMALL EARTHQUAKE","VOLCANIC TREMOR","MECHANICAL VIBRATION"],"branches":[{"senses":"S2 · S3","en":"BODY AND EMOTION: the original human shaking, caused by nerves or by feeling.","cn":"身体与情绪：最初的人身抖动，由神经或情绪引起。"},{"senses":"S6","en":"VOICE: the same shaking made audible, then controlled as expression.","cn":"声音：同一种抖动被听见，随后被控制成表现手段。"},{"senses":"S1 · S4","en":"GROUND: shaking felt in the earth, first as a slight movement, then as a small quake.","cn":"地面：在大地上感到的抖动，先是轻微运动，再成为小震。"},{"senses":"S5","en":"VOLCANO: a continuous signal that magma is moving and pressure is building.","cn":"火山：岩浆在移动、压力在积累时发出的持续信号。"},{"senses":"S7 · S8","en":"SYSTEMS: the same weak, steady shaking read into a society or a machine.","cn":"系统：同一种微弱而稳定的抖动被读进社会或机器之中。"}]},"affixes":{"intro":{"en":"Tremor is a Latin noun of state built directly on a verb, and its stem recurs in adjectives, a verb and an Italian musical borrowing.","cn":"tremor 是直接建于动词之上的拉丁状态名词，其词干在形容词、动词与一个意大利语音乐借词中反复出现。"},"latinIntro":{"en":"Latin tremere, tremor, tremulus and tremendus underlie tremor, tremulous, tremendous and tremolo.","cn":"拉丁 tremere、tremor、tremulus 与 tremendus 构成本词及「颤抖的」「令人发抖的」「颤音」等同族词。"},"items":[{"word":"trem-","structure":"tremere (Latin verb stem, 'to tremble')","meaning":"shake, quake","meaningCN":"发抖；震动","example":"The stem trem- names the shaking itself.","exampleCN":"词干 trem- 直接指抖动本身。"},{"word":"-or","structure":"-or (Latin noun suffix, state or quality)","meaning":"the state of doing","meaningCN":"状态或性质","example":"Tremor is the state of trembling.","exampleCN":"这个词指的就是「正在发抖」的状态。"},{"word":"tremor","structure":"tremere + -or","meaning":"a trembling; a small quake","meaningCN":"颤抖；微震","example":"The tremor lasted a few seconds.","exampleCN":"那次微震持续了几秒钟。"},{"word":"tremulous","structure":"tremulus + -ous","meaning":"trembling, timid","meaningCN":"颤抖的；怯生生的","example":"Her tremulous voice betrayed her nerves.","exampleCN":"她颤抖的声音泄露了紧张。"},{"word":"tremendous","structure":"tremendus (Latin gerundive, 'to be trembled at')","meaning":"arousing awe; hence enormous","meaningCN":"令人发抖的，后转指巨大","example":"A tremendous roar came from the crater.","exampleCN":"火山口传来一声令人震骇的轰鸣。"},{"word":"tremble","structure":"Old French trembler, generally considered from Latin tremulare","meaning":"to shake slightly","meaningCN":"轻轻发抖","example":"Her hands tremble in the cold.","exampleCN":"她的双手在寒冷中发抖。"},{"word":"tremolo","structure":"Italian tremolo, from Latin tremulus","meaning":"a quivering musical effect","meaningCN":"颤音效果","example":"The strings played a soft tremolo.","exampleCN":"弦乐奏出一段柔和的颤音。"},{"word":"tremulant","structure":"Latin tremulare + -ant","meaning":"trembling; an organ tremolo stop","meaningCN":"颤动的；管风琴颤音音栓","example":"The organ's tremulant swelled the final chord.","exampleCN":"管风琴的颤音音栓让结尾和弦饱满起来。"},{"word":"tremulously","structure":"tremulous + -ly","meaning":"in a trembling way","meaningCN":"颤抖地","example":"She tremulously asked whether the quake was over.","exampleCN":"她声音发颤地问地震是否过去了。"}],"latinEntries":[{"word":"tremere","structure":"tremere, tremui (verb, third conjugation)","meaning":"to tremble, to quake","meaningCN":"发抖；震动"},{"word":"tremor","structure":"tremor, tremoris (m., third declension)","meaning":"a trembling","meaningCN":"颤抖"},{"word":"tremulus","structure":"tremulus, -a, -um (adjective)","meaning":"trembling","meaningCN":"颤抖的"},{"word":"tremendus","structure":"tremendus, -a, -um (gerundive)","meaning":"to be trembled at, dreadful","meaningCN":"令人发抖的；可怕的"}]}},{"word":"vibration","ipa_uk":"/vaɪˈbreɪʃn/","ipa_us":"/vaɪˈbreɪʃn/","definition_zh":"振动；颤动；（地面或建筑传来的）震动；（口语）氛围、气场；振动能","definition_en":"a rapid movement back and forth about a fixed point, or the shaking and energy that such movement produces","core_image":"一根被拨动的琴弦在两个极限位置之间来回，留下残影般的一道弧线","scene":"音乐教室的午后，老师把音叉敲响后，将柄端抵在木桌边缘，桌上的纸片轻轻跳起。 A faint vibration passes through the table and makes the paper slip.","sceneCN":"这里 vibration 是名词「通过固体传导的震动」（第 3 个义项：地面或建筑结构接收并传递的振动）；句意为一次微弱的振动穿过桌面，使纸片滑了一下。","pos":[{"tag":"n.","zh":"振动；颤动；传导的震动；（口语）氛围、气场；振动能"}],"collocations":[{"phrase":"mechanical vibration","zh":"机械振动"},{"phrase":"vibration frequency","zh":"振动频率"},{"phrase":"vibration isolation","zh":"隔振"},{"phrase":"good vibrations","zh":"良好的氛围（口语）"},{"phrase":"sympathetic vibration","zh":"共振；共鸣振动"},{"phrase":"vibration amplitude","zh":"振幅"}],"forms":[{"label":"名词复数","form":"vibrations"},{"label":"单数所有格","form":"vibration's"},{"label":"复数所有格","form":"vibrations'"},{"label":"名词作定语（保持原形）","form":"vibration"}],"derivatives":[{"word":"vibrate","pos":"v.","zh":"振动；颤动；使振动"},{"word":"vibrant","pos":"adj.","zh":"充满生气的；鲜明的；（声音）洪亮的"},{"word":"vibrancy","pos":"n.","zh":"活力；鲜明；洪亮"},{"word":"vibrato","pos":"n.","zh":"（音乐）颤音（意大利语借词，同根）"},{"word":"vibrator","pos":"n.","zh":"振动器；振动装置"}],"senses":[{"no":"01","title":"Rapid back-and-forth motion","titleCN":"快速的往复运动","definition":"a rapid alternation of position about a rest point, as of a pendulum, a string or a membrane","definitionCN":"围绕静止位置快速交替位移，如摆、弦或膜的运动","example":"The vibration of the plucked string dies away within a second.","exampleCN":"被拨动的琴弦一秒内就停止了振动。","why":"Latin vibrare meant to move quickly to and fro, so the noun names the pattern itself before it names any particular object that shakes.","whyCN":"拉丁 vibrare 意为快速来回移动，因此这个名词先指运动模式本身，而非某个具体的抖动之物。"},{"no":"02","title":"Mechanical vibration","titleCN":"机械振动","definition":"the shaking of a machine, engine or structure during normal running or because of wear","definitionCN":"机器、发动机或结构在正常运转中或因磨损而产生的抖动","example":"Engineers track vibration in the gearbox as an early sign of wear.","exampleCN":"工程师监测齿轮箱的振动，把它当作磨损的早期信号。","why":"industry needed a measurable name for unwanted shaking, and the general physical noun supplied it without metaphor.","whyCN":"工业需要一个可测量的词来指不受欢迎的抖动，这个一般物理名词无需比喻就提供了它。"},{"no":"03","title":"Shaking transmitted through a solid","titleCN":"通过固体传导的震动","definition":"movement or shaking that passes through the ground, a floor or a building from a distant source","definitionCN":"由远处震源传来、穿过地面、楼板或建筑结构的运动或抖动","example":"Passing trucks send vibration through the old brick wall.","exampleCN":"过路的卡车把振动传过老砖墙。","why":"the physical sense easily extends from the object that shakes to the path along which the shaking travels.","whyCN":"这个物理义很容易从「抖动的物体」扩展到「抖动传播所经过的路径」。"},{"no":"04","title":"Vibration of strings and vocal cords","titleCN":"琴弦与声带的振动","definition":"the rapid oscillation of a stretched string or of the vocal folds that produces sound","definitionCN":"张紧的弦或声带快速振荡并由此产生声音","example":"The vocal cords produce sound through rapid vibration.","exampleCN":"声带通过快速振动发出声音。","why":"sound is literally vibration in air, so acoustics uses the same word for the source and for what reaches the ear.","whyCN":"声音本来就是空气的振动，所以声学用同一个词既指声源，也指传到耳朵的东西。"},{"no":"05","title":"Frequency and amplitude","titleCN":"振动频率与振幅","definition":"the measurable rate and size of a vibration, usually given in cycles per second and in displacement","definitionCN":"振动可测量的快慢与幅度，通常以每秒周期数和位移来表示","example":"The device records vibration at two frequencies at once.","exampleCN":"该装置同时记录两个频率上的振动。","why":"once vibration became an engineering quantity, it needed numbers: how often it repeats and how far it moves.","whyCN":"一旦振动成为工程量，就需要数字：它重复得多快，以及移动得多远。"},{"no":"06","title":"Isolation and damping","titleCN":"隔振与阻尼","definition":"the engineering practice of reducing unwanted vibration before it reaches people, instruments or buildings","definitionCN":"在不受欢迎的振动传到人、仪器或建筑之前削减它的工程做法","example":"Rubber mounts provide vibration isolation for the sensitive microscope.","exampleCN":"橡胶支座为敏感显微镜提供隔振。","why":"the noun can stand for the thing being controlled, as in isolation and damping, because the problem and its remedy share one name.","whyCN":"这个名词可以指被控制的对象，如隔振与阻尼，因为问题与对策共用同一个名称。"},{"no":"07","title":"Atmosphere or emotional quality","titleCN":"氛围与气场（口语）","definition":"an emotional quality felt in a place, a group or a piece of music, often used in the plural","definitionCN":"某地、某群体或某段音乐给人的情绪感受，常用复数","example":"The room had good vibrations that put everyone at ease.","exampleCN":"那个房间有一种让人放松的良好氛围。","why":"the sixties turned the physical word into slang for a felt atmosphere, as if mood were something transmitted through a room.","whyCN":"二十世纪六十年代把这一物理词变成指可感氛围的俚语，仿佛情绪也能在房间里传播。"},{"no":"08","title":"Vibrational energy","titleCN":"振动能量","definition":"the energy carried by an oscillating system, counted in physics as part of its internal energy","definitionCN":"振荡系统所携带的能量，物理学上计为其内能的一部分","example":"The sensor converts vibration into electrical current.","exampleCN":"传感器把振动能转换成电流。","why":"physics treats vibration as a form of energy, so the noun can name the quantity that a device harvests.","whyCN":"物理学把振动视为一种能量，因此这个名词也能指装置所收集的那个量。"}],"etymology":{"intro":{"en":"Vibration comes from Latin vibratio, a shaking or brandishing, built on the verb vibrare. English took the noun in the seventeenth century, and acoustics and engineering later gave it measured frequency and amplitude.","cn":"vibration 来自拉丁 vibratio「摇动、挥舞」，建于动词 vibrare 之上。英语于十七世纪借入这个名词，声学与工程后来给它加上了可测的频率与振幅。"},"items":[{"era":"LATIN VIBRARE","en":"Vibrare meant to move rapidly to and fro, to brandish or wave a weapon, and also to quiver. It is the single verb behind the whole English family.","cn":"vibrare 意为快速来回移动、挥舞武器，也指抖动。整个英语同族词都出自这一个动词。"},{"era":"LATIN VIBRATIO","en":"Vibratio was the noun of action, a shaking or a waving, formed with the same -tio suffix seen in many Latin action nouns.","cn":"vibratio 是动作名词，指摇动或挥舞，用与许多拉丁动作名词相同的 -tio 后缀构成。"},{"era":"LATIN VIBRATUS","en":"The perfect participle vibratus, having been shaken, supplied the stem vibrat- that passed through French into English vibration.","cn":"完成分词 vibratus 意为「已被摇动」，提供了经法语进入英语 vibration 的词干 vibrat-。"},{"era":"ITALIAN VIBRATO","en":"Vibrato is an Italian borrowing from the same Latin root, naming a rapid fluctuation of pitch in singing or playing. It is a cousin of vibration, not a child of it.","cn":"vibrato 是从同一拉丁词根借入意大利语的词，指歌唱或演奏中音高的快速起伏。它是 vibration 的同族表亲，而非其派生词。"},{"era":"SCIENTIFIC ENGLISH","en":"English vibration is generally dated to the seventeenth century as a word for shaking; the modern technical senses of frequency, amplitude and isolation belong to later physics and engineering.","cn":"英语 vibration 一般被认为是十七世纪表示「摇动」的词；频率、振幅与隔振等现代技术义属于后来的物理学与工程学。"},{"era":"UNCERTAIN DETAILS","en":"Two tiers of doubt: the first date of the technical senses is approximate, a dating question; the deeper root of vibrare is usually linked to a reconstructed Indo-European word for quivering, but that link is a reconstruction, not a recorded form, a root question.","cn":"来源不确定，分两档：技术义的首见年代只是约数，属年代存疑；vibrare 更深的词根通常被联系到一个重构的印欧语「抖动」词，但这一联系属于重构，并非有记录的形式，属词根存疑。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin shaking stock; group two holds near neighbours for motion, sound and felt atmosphere.","cn":"第一组是同出拉丁「摇动」词干的词；第二组是表示运动、声音与可感氛围的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"vibrate","ipa":"/vaɪˈbreɪt/","tag":"same stock, verb","definition":"To move rapidly back and forth, or to cause something to do so; it is the action behind every noun sense of vibration.","definitionCN":"快速来回运动，或使某物如此运动；它是 vibration 各名词义背后的动作。"},{"word":"vibrant","ipa":"/ˈvaɪbrənt/","tag":"same stock, adjective","definition":"Full of life, color or sound, literally vibrating; the physical sense survives in descriptions of rich color and strong voices.","definitionCN":"充满生气、色彩或声音的，字面义为「正在振动」；其物理义仍残留在对浓烈色彩与洪亮嗓音的描写中。"},{"word":"vibrato","ipa":"/vɪˈbrɑːtəʊ/","tag":"same root via Italian","definition":"A controlled, rapid variation in pitch in music; it shares the Latin root but reached English through Italian, not through the noun vibration.","definitionCN":"音乐中受控的快速音高变化；它与本词共享拉丁词根，但经意大利语进入英语，而非由 vibration 派生。"},{"word":"vibrancy","ipa":"/ˈvaɪbrənsi/","tag":"same stock, noun of quality","definition":"The quality of being vibrant: liveliness of color, sound or personality, with the physical shaking faded into metaphor.","definitionCN":"「有活力」的性质：色彩、声音或个性的鲜活，其中的物理抖动已淡化为比喻。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tremor","ipa":"/ˈtremə/","tag":"shaking, often involuntary","definition":"A fine shaking, especially of the body or the ground; unlike vibration it usually suggests something unwanted or uncontrollable.","definitionCN":"细密的抖动，尤其指身体或地面；与 vibration 不同，它通常暗示不受欢迎或无法控制。"},{"word":"oscillation","ipa":"/ˌɒsɪˈleɪʃn/","tag":"regular swing","definition":"A regular swinging from one side to the other, often slower and more orderly than vibration.","definitionCN":"有规律地从一侧摆到另一侧，通常比振动更慢、更有秩序。"},{"word":"shaking","ipa":"/ˈʃeɪkɪŋ/","tag":"plain everyday word","definition":"The general act of moving something quickly up and down or side to side; vibration is its technical, repetitive counterpart.","definitionCN":"使某物快速上下或左右移动的一般动作；vibration 是它技术化、重复化的对应词。"},{"word":"resonance","ipa":"/ˈrezənəns/","tag":"amplified response","definition":"The strong response of a system when it is driven at its natural frequency, producing a much larger vibration.","definitionCN":"系统在固有频率被驱动时产生的强烈响应，会形成大得多的振动。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin stem, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的拉丁词干、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"vibr- is the shaking stem: Latin vibrare waved and quivered, and vibration is the pattern it leaves.","cn":"vibr- 是「摇动」的词干：拉丁 vibrare 是挥舞与抖动，vibration 是它留下的运动模式。"},{"en":"The family splits by part of speech: a verb, an adjective, a noun of quality and a musical noun.","cn":"同族按词性分流：一个动词、一个形容词、一个表性质的抽象名词与一个音乐名词。"},{"en":"Frequency and amplitude are the two numbers engineers give a vibration.","cn":"频率与振幅是工程师描述一次振动时给出的两个数字。"},{"en":"The plural turns physical: good vibrations is about mood, not machinery.","cn":"复数形式转向心理：所谓「良好的氛围」说的是情绪，而非机器。"},{"en":"Isolation and damping are the practical side: stop the vibration before it arrives.","cn":"隔振与阻尼是实用的一面：在振动到达之前就拦住它。"}],"abstract":[{"en":"Picture a guitar string blurred into a fan shape while it sounds.","cn":"想象一根吉他弦发声时模糊成扇形的一道残影。"},{"en":"Picture a wine glass singing until the note turns dangerous.","cn":"想象一只酒杯一直鸣响，直到那个音变得危险。"},{"en":"Picture a room whose mood changes the moment one person walks in.","cn":"想象一间屋子，某个人一走进来，气氛立刻变了。"}]},"examples":[{"en":"The bridge was closed after sensors detected unusual vibration in one span.","cn":"传感器在一跨桥段检测到异常振动后，大桥被关闭。"},{"en":"He felt the vibration of the train long before it appeared.","cn":"火车还没出现，他就感到了它的振动。"},{"en":"Rubber pads reduce the vibration that reaches the microscope.","cn":"橡胶垫减少了传到显微镜的振动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「vibr（摇摆）+ ation」——像琴弦来回摆动 → 振动、颤动、氛围气场","word":"vibration"},"root":"拉丁 vibrare「快速来回移动、挥动」的动名词 vibratio「摇动」；同族有动词「振动」、形容词「鲜明的、有活力的」与意大利语借词「颤音」，另有名词「振动器」。","sensesIntro":{"en":"Eight senses follow one pattern: something moves back and forth around a rest point. The pattern is first named in itself, then located in machines, buildings, strings and voices, measured, controlled, and finally read as mood or as energy.","cn":"八个义项沿同一种模式展开：某物围绕静止位置来回运动。这个模式先被命名，再依次落到机器、建筑、琴弦与声音上，被测量、被控制，最后被读成氛围或能量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a taut string swinging between two extremes and never resting at the middle.","cn":"核心意象：一根绷紧的弦在两个极端之间来回，从不在中间停留。"},"chain":["RAPID BACK-AND-FORTH","MACHINE SHAKING","TRANSMITTED SHAKE","SOUND SOURCE","MEASUREMENT","MOOD AND ENERGY"],"branches":[{"senses":"S1","en":"MOTION ITSELF: the bare physical pattern, before any object or use is attached.","cn":"运动本身：尚未附上任何物体或用途的纯粹物理模式。"},{"senses":"S2 · S6","en":"MACHINE AND CONTROL: shaking as a symptom to be watched and then reduced.","cn":"机器与控制：抖动先是需要监测的症状，随后被削减。"},{"senses":"S3","en":"STRUCTURE: the same shaking travels through ground, floor and wall.","cn":"结构：同一种抖动穿过地面、楼板与墙体。"},{"senses":"S4 · S5","en":"SOUND AND MEASURE: strings and vocal folds make it audible, instruments make it countable.","cn":"声音与测量：琴弦与声带让它被听见，仪器让它可计数。"},{"senses":"S7 · S8","en":"MOOD AND ENERGY: the pattern is felt as atmosphere or harvested as power.","cn":"氛围与能量：这种模式或被感受为气氛，或被收集为能量。"}]},"affixes":{"intro":{"en":"Vibration is a Latin action noun built from a verb stem plus a suffix, with the same stem surviving in a verb, two adjectives and an Italian musical borrowing.","cn":"vibration 是由动词词干加后缀构成的拉丁动作名词，同一词干还留存在一个动词、两个形容词与一个意大利语音乐借词中。"},"latinIntro":{"en":"Latin vibrare, vibratio and vibratus feed vibration, vibrate, vibrant and vibrato.","cn":"拉丁 vibrare、vibratio 与 vibratus 衍生出本词及「振动」「有活力的」「颤音」等同族词。"},"items":[{"word":"vibr-","structure":"vibrare (Latin verb stem, 'to shake, brandish')","meaning":"shake, swing","meaningCN":"摇动；摆动","example":"The stem vibr- carries the swinging motion.","exampleCN":"词干 vibr- 承载来回摆动的动作。"},{"word":"-ation","structure":"-atio (Latin noun suffix, action or state)","meaning":"the act or state of doing","meaningCN":"动作或状态","example":"Vibration is the state of being shaken.","exampleCN":"该名词指「被摇动」的状态。"},{"word":"vibration","structure":"vibrare + -ation","meaning":"a shaking; a rapid oscillation","meaningCN":"振动；快速振荡","example":"The vibration was measured at fifty cycles per second.","exampleCN":"测得的振动为每秒五十个周期。"},{"word":"vibrate","structure":"vibratus + -ate (English verb)","meaning":"to shake rapidly","meaningCN":"振动；使振动","example":"The phone vibrates on the desk.","exampleCN":"手机在桌上振动。"},{"word":"vibrant","structure":"vibrare + -ant (present participle suffix)","meaning":"vibrating; full of life","meaningCN":"振动的；充满生气的","example":"The market was vibrant with color and noise.","exampleCN":"市场色彩鲜明、人声鼎沸。"},{"word":"vibrancy","structure":"vibrant + -cy (noun of quality)","meaning":"liveliness","meaningCN":"活力；鲜明","example":"The vibrancy of the paint surprised the curator.","exampleCN":"颜料的鲜亮让策展人吃惊。"},{"word":"vibrato","structure":"Italian vibrato, from Latin vibratus","meaning":"a wavering musical tone","meaningCN":"音乐中的颤音","example":"The violinist added vibrato to the slow passage.","exampleCN":"小提琴手在缓慢的乐段里加了颤音。"},{"word":"vibrator","structure":"vibrate + -or (agent suffix)","meaning":"a device that shakes","meaningCN":"振动装置","example":"A small vibrator tested the loose connection.","exampleCN":"一个小振动器测试了松动的接头。"},{"word":"vibrational","structure":"vibration + -al","meaning":"relating to vibration","meaningCN":"振动的","example":"The spectrum shows vibrational energy levels.","exampleCN":"光谱显示出振动能级。"}],"latinEntries":[{"word":"vibrare","structure":"vibrare, vibravi, vibratum (verb, first conjugation)","meaning":"to shake, brandish, quiver","meaningCN":"摇动；挥舞；抖动"},{"word":"vibratio","structure":"vibratio, vibrationis (f., third declension)","meaning":"a shaking","meaningCN":"摇动"},{"word":"vibratus","structure":"vibratus, -a, -um (perfect passive participle)","meaning":"shaken","meaningCN":"被摇动的"}]}},{"word":"volcanic","ipa_uk":"/vɒlˈkænɪk/","ipa_us":"/vɑːlˈkænɪk/","definition_zh":"火山的；火山造成的；火山岩的；火山土的；（脾气或局势）一触即发的","definition_en":"relating to or produced by a volcano, or, of a mood or situation, ready to explode like one","core_image":"一座锥形山体顶端喷出灰柱，黑色熔岩顺坡流下，冷却成坚硬的石","scene":"海边的小村旁，黑色砂粒在浪里翻滚，孩子弯腰捧起一把，掌心留下细小的黑色颗粒。 The black sand under our feet is volcanic, worn from old lava by the sea.","sceneCN":"这里 volcanic 是形容词「由火山物质形成的」（第 2 个义项：火山岩、火山灰等喷出物构成的）；句意为脚下的黑沙是火山物质，由古老熔岩被海水磨碎而成。","pos":[{"tag":"adj.","zh":"火山的；火山造成的；火山岩的；火山土的；（比喻）一触即发的"}],"collocations":[{"phrase":"volcanic eruption","zh":"火山喷发"},{"phrase":"volcanic ash","zh":"火山灰"},{"phrase":"volcanic rock","zh":"火山岩"},{"phrase":"volcanic activity","zh":"火山活动"},{"phrase":"volcanic soil","zh":"火山土"},{"phrase":"volcanic glass","zh":"火山玻璃"},{"phrase":"volcanic arc","zh":"火山弧"}],"forms":[{"label":"原级","form":"volcanic"},{"label":"比较级","form":"more volcanic"},{"label":"最高级","form":"most volcanic"},{"label":"副词形式","form":"volcanically"},{"label":"名词化用法（前加定冠词，指火山岩类）","form":"the volcanic"}],"derivatives":[{"word":"volcanically","pos":"adv.","zh":"由火山作用地；火山性地"},{"word":"volcanism","pos":"n.","zh":"火山活动；火山作用"},{"word":"volcanology","pos":"n.","zh":"火山学"},{"word":"volcanologist","pos":"n.","zh":"火山学家"},{"word":"volcanogenic","pos":"adj.","zh":"火山成因的"}],"senses":[{"no":"01","title":"Relating to a volcano","titleCN":"与火山有关的","definition":"relating to a volcano or to the fire, ash and rock it produces","definitionCN":"与火山或与其产生的火、灰、岩石有关的","example":"The island's volcanic peaks rise straight from the sea.","exampleCN":"这座岛上的火山峰从海面直直升起。","why":"the adjective simply marks belonging: volcanic scenery, volcanic origin, volcanic island all attach the noun to the fire mountain.","whyCN":"这个形容词只标记归属：火山地貌、火山成因、火山岛，都是把名词挂到那座火之山上。"},{"no":"02","title":"Rock and ash from a volcano","titleCN":"火山岩与火山灰","definition":"made of or consisting of material thrown out by a volcano, such as lava, ash or pumice","definitionCN":"由火山喷出的物质（如熔岩、火山灰或浮石）构成或组成的","example":"Layers of volcanic ash lie between the coal seams.","exampleCN":"煤层之间夹着层层火山灰。","why":"geology uses the adjective for the material itself, so a rock can be called volcanic without naming a particular mountain.","whyCN":"地质学用这个形容词指材料本身，因此一块岩石可以被称为火山的，而不必指明某座具体的山。"},{"no":"03","title":"Volcanic activity or eruption","titleCN":"火山活动或喷发","definition":"caused by or showing the action of a volcano, including eruptions, tremors and gas release","definitionCN":"由火山作用引起或表现出的，包括喷发、颤动与气体释放","example":"Volcanic activity increased sharply before the evacuation.","exampleCN":"撤离之前，火山活动急剧增加。","why":"the adjective shifts from the place to the process, naming an event rather than a mountain or a stone.","whyCN":"这个形容词从「地点」转到「过程」，指事件而非山体或石头。"},{"no":"04","title":"Fertile volcanic soil","titleCN":"肥沃的火山土","definition":"describing soil formed from weathered volcanic material, which is often rich in minerals and very productive","definitionCN":"描述由风化火山物质形成的土壤，常富含矿物质且十分肥沃","example":"Farmers prize the deep volcanic soil for its minerals.","exampleCN":"农民看重深厚的火山土，因为它富含矿物质。","why":"the destructive mountain leaves a gift behind, and the adjective carries that unlikely pairing of fire and fertility.","whyCN":"毁灭性的山体留下了一份礼物，这个形容词就承载着「火与肥沃」这种出人意料的组合。"},{"no":"05","title":"Volcanic glass","titleCN":"火山玻璃","definition":"a natural glass formed when lava cools too quickly to crystallize, as in obsidian","definitionCN":"熔岩冷却过快、来不及结晶时形成的天然玻璃，如黑曜岩","example":"Volcanic glass forms when lava cools too fast to crystallize.","exampleCN":"熔岩冷却得太快、来不及结晶时就形成火山玻璃。","why":"the adjective names the origin of the material, while glass names its structure, so the phrase combines a source and a texture.","whyCN":"这个形容词指明材料的来源，玻璃指明其结构，因此这个短语把来源与质地组合在一起。"},{"no":"06","title":"Volcanic winter","titleCN":"火山冬天","definition":"a period of global cooling caused by ash and sulfur aerosols from a very large eruption blocking sunlight","definitionCN":"极大规模喷发产生的灰与硫气溶胶遮挡阳光、造成全球降温的一段时期","example":"A large eruption can cause a volcanic winter that cools the whole planet.","exampleCN":"一次大喷发可能引发火山冬天，使整个行星降温。","why":"climate science extended the adjective from the mountain to the planet, because the effects of an eruption travel far beyond the cone.","whyCN":"气候科学把这个形容词从山体扩展到行星，因为喷发的影响会远远超出火山锥。"},{"no":"07","title":"Volcanic arc","titleCN":"火山弧","definition":"a curved chain of volcanoes formed above a descending tectonic plate at a subduction zone","definitionCN":"在俯冲带、位于下沉板块之上形成的一列弧形火山链","example":"The islands form a volcanic arc above the subducting plate.","exampleCN":"这些岛屿在俯冲板块之上构成一条火山弧。","why":"plate tectonics needed a term for a whole line of volcanoes, and the adjective turned a single mountain into a geographic pattern.","whyCN":"板块构造学需要一个指整条火山链的术语，这个形容词把单座山变成了地理格局。"},{"no":"08","title":"Ready to explode, of temper or tension","titleCN":"比喻：脾气或局势一触即发","definition":"extremely explosive, violent or unstable, used of a person's temper or of a tense situation","definitionCN":"极其易爆、猛烈或不稳定的，用于人的脾气或紧张的局势","example":"His volcanic temper emptied the meeting room in seconds.","exampleCN":"他那火山般的脾气几秒钟内就让会议室空了。","why":"the metaphor is almost too easy: a volcano gives warning, then erupts, and so does a temper that has been held down too long.","whyCN":"这个比喻几乎太顺理成章：火山先有预兆再喷发，被压抑太久的脾气也是如此。"}],"etymology":{"intro":{"en":"Volcanic is volcano plus the adjective suffix -ic. Volcano reached English through Italian from Latin Volcanus, also spelled Vulcanus, the Roman god of fire and metalworking. The suffix -ic came from Greek -ikos by way of Latin -icus.","cn":"volcanic 是在表示火山的那个英语名词上加形容词后缀 -ic 构成。那个名词经意大利语来自拉丁 Volcanus（亦作 Vulcanus），即罗马的火与冶金之神。后缀 -ic 由希腊 -ikos 经拉丁 -icus 进入英语。"},"items":[{"era":"LATIN VOLCANUS","en":"Volcanus was the Roman god of fire and the forge. His name was also given to burning ground and to the fire itself, which is why a mountain that burns bears it.","cn":"Volcanus 是罗马的火与锻造之神。他的名字也被用于燃烧的地面与火本身，因此一座会燃烧的山沿用此名。"},{"era":"ITALIAN VULCANO","en":"Italian vulcano named a burning mountain, and English borrowed the word as volcano, generally in the seventeenth century, through Italian or French.","cn":"意大利语中的火山之名本指「燃烧的山」，英语一般在十七世纪经意大利语或法语借入这个词，成为表示火山的名称。"},{"era":"GREEK -IKOS THROUGH LATIN -ICUS","en":"The suffix -ic entered English from Latin -icus, itself from Greek -ikos, meaning belonging to or connected with; it turns a noun into an adjective of relation.","cn":"后缀 -ic 由拉丁 -icus 进入英语，而 -icus 又出自希腊 -ikos，意为「属于……的、与……有关的」；它把名词变成表示关系的形容词。"},{"era":"VOLCANIC IN ENGLISH","en":"Volcanic was formed on volcano in the late eighteenth century, first describing rocks and terrain produced by fire, then widening to the whole subject.","cn":"volcanic 于十八世纪后期在火山这一名词上构成，最初描述火造成的岩石与地貌，随后扩展到整个主题。"},{"era":"SCIENTIFIC EXTENSIONS","en":"Geology added volcanic arc, volcanic glass and volcaniclastic; climatology added volcanic winter. All keep the original image of a mountain that burns.","cn":"地质学增添了火山弧、火山玻璃与火山碎屑等说法；气候学增添了火山冬天。它们都保留着「会燃烧的山」这一原初意象。"},{"era":"UNCERTAIN DETAILS","en":"Two tiers of doubt: the origin of the god's name is uncertain, with an Etruscan source often suggested but never proved, a root question; the first date of the rock sense is only approximate, a dating question.","cn":"来源不确定，分两档：火神之名的来源不确定，常有人提出源自伊特鲁里亚语，但从未得到证实，属词根存疑；岩石义的首见年代只是约数，属年代存疑。"}]},"similar":{"note":{"en":"Group one holds words built on the volcano family; group two holds near neighbours that describe fire, rock and eruption.","cn":"第一组是建于火山这一词族之上的词；第二组是描述火、岩石与喷发的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"volcano","ipa":"/vɒlˈkeɪnəʊ/","tag":"the base noun","definition":"The mountain itself, from which volcanic is formed by adding -ic; the direction is noun to adjective, never the reverse.","definitionCN":"指山体本身；volcanic 是在它之上加 -ic 构成的形容词，方向是名词到形容词，绝非反向。"},{"word":"volcanism","ipa":"/ˈvɒlkənɪzəm/","tag":"same family, process noun","definition":"The whole set of processes by which magma reaches the surface; it names the activity, not a single mountain.","definitionCN":"岩浆到达地表的整套过程；它指活动，而非单座山。"},{"word":"volcanology","ipa":"/ˌvɒlkəˈnɒlədʒi/","tag":"same family, discipline","definition":"The scientific study of volcanoes and volcanic phenomena, built with the study suffix -logy.","definitionCN":"研究火山与火山现象的科学，由表示「学科」的后缀构成。"},{"word":"volcanically","ipa":"/vɒlˈkænɪkli/","tag":"same family, adverb","definition":"In a volcanic manner or by volcanic action, as in a volcanically active region.","definitionCN":"以火山的方式或由火山作用地，如「火山活动活跃的地区」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"igneous","ipa":"/ˈɪɡniəs/","tag":"rock formed from magma","definition":"Relating to rock solidified from magma or lava; broader than volcanic, because it also covers rock that cooled deep underground.","definitionCN":"指由岩浆或熔岩固结而成的岩石；比 volcanic 更广，因为它也包括地下深处冷却的岩石。"},{"word":"eruptive","ipa":"/ɪˈrʌptɪv/","tag":"sudden bursting out","definition":"Relating to an eruption or tending to burst out suddenly, used of volcanoes, skin rashes and tempers alike.","definitionCN":"与喷发有关的，或倾向于突然爆发的，火山、皮疹与脾气都可用。"},{"word":"pyroclastic","ipa":"/ˌpaɪrəˈklæstɪk/","tag":"fragmental volcanic material","definition":"Made of fragments of hot rock and ash thrown out by an eruption, a narrower technical term than volcanic.","definitionCN":"由喷发抛出的炽热岩石碎片与灰构成的，是比 volcanic 更窄的术语。"},{"word":"fiery","ipa":"/ˈfaɪəri/","tag":"burning, passionate","definition":"Burning or glowing like fire, or intensely passionate; it shares the heat image but not the geological meaning.","definitionCN":"像火一样燃烧或发光的，或极其炽烈的；它共享「热」的意象，但没有地质含义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin name, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的拉丁名称、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Volcan- is the fire god's name, so the root already contains a mountain that burns.","cn":"volcan- 就是火神的名字，因此词根本身已经含着一座会燃烧的山。"},{"en":"The suffix -ic makes an adjective of belonging: relating to the fire mountain.","cn":"后缀 -ic 造出表示归属的形容词：与那座火之山有关的。"},{"en":"Volcanic describes origin and material; the noun names the mountain. Keep the direction straight.","cn":"volcanic 描述来源与材料，名词则指山本身；要把构词方向记牢。"},{"en":"Each science borrows the adjective for its own object: winter, glass, arc, soil.","cn":"每门学科都借这个形容词指自己的对象：冬天、玻璃、弧、土。"},{"en":"The figurative use keeps the eruption: a volcanic temper erupts, it does not simmer.","cn":"比喻用法保留喷发的意象：火山般的脾气是爆发，而不是慢炖。"}],"abstract":[{"en":"Picture a pressure cooker whose lid lifts before anyone expects it.","cn":"想象一只压力锅，锅盖在谁都没预料到的时候被顶起。"},{"en":"Picture a classroom silent because one person's anger fills it.","cn":"想象一间教室鸦雀无声，只因一个人的怒气充满了整个空间。"},{"en":"Picture a hillside green with vines growing on old ash.","cn":"想象一片山坡绿意盎然，藤蔓长在陈年的火山灰上。"}]},"examples":[{"en":"Volcanic ash grounded flights across the region.","cn":"火山灰使整个地区的航班停飞。"},{"en":"The vineyard thrives on volcanic soil.","cn":"这片葡萄园在火山土上长势旺盛。"},{"en":"He has a volcanic temper that shows up without warning.","cn":"他有一种毫无预兆就爆发的火暴脾气。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「volcan（火神）+ ic」——火神的山一喷就炸 → 火山的、火山岩的、一触即发的","word":"volcanic"},"root":"拉丁 Volcanus（罗马火神，亦作 Vulcanus）经意大利语进入英语，成为表示火山的那个名词；本词是在该名词上加希腊来源、经拉丁而来的形容词后缀 -ic 构成，方向是名词加后缀，而非反向派生。","sensesIntro":{"en":"Eight senses follow one source: a mountain that opens and pours out fire, ash and stone. The adjective first marks the mountain, then its material, its activity, its gifts to soil, glass and climate, its geography, and finally an explosive human mood.","cn":"八个义项沿同一个源头展开：一座裂开并喷出火、灰与石的山。这个形容词先标记山体，再依次标记其材料、活动、对土壤与玻璃与气候的馈赠、其地理格局，最后落到人的爆发性情绪。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mountain that opens and pours fire, ash and black glass.","cn":"核心意象：一座裂开、喷出火、灰与黑色玻璃的山。"},"chain":["FIRE MOUNTAIN","ERUPTION","ASH AND ROCK","SOIL AND GLASS","CLIMATE AND ARC","EXPLOSIVE MOOD"],"branches":[{"senses":"S1","en":"THE MOUNTAIN ITSELF: the plain adjective of belonging, with no special object yet.","cn":"山体本身：最朴素的归属形容词，尚未挂上特定对象。"},{"senses":"S2 · S3","en":"MATERIAL AND PROCESS: what comes out of the mountain, and the act of it coming out.","cn":"材料与过程：山喷出的东西，以及它喷出的那个动作。"},{"senses":"S4 · S5","en":"PRODUCTS ON LAND: the same material becomes fertile soil or natural glass.","cn":"陆地上的产物：同一种材料变成肥沃的土或天然的玻璃。"},{"senses":"S6 · S7","en":"PLANETARY SCALE: one eruption reaches the climate, many eruptions make an arc.","cn":"行星尺度：一次喷发触及气候，许多次喷发连成一道弧。"},{"senses":"S8","en":"FIGURATIVE FIRE: a person or a situation that holds pressure until it blows.","cn":"比喻之火：一个人或一种局势积压着压力，直到炸开。"}]},"affixes":{"intro":{"en":"Volcanic is a noun of place turned into an adjective by one suffix, and that same root supports a whole vocabulary of fire, rock and study.","cn":"volcanic 是由地名名词经一个后缀变成的形容词，而同一词根支撑起整套关于火、岩石与研究的词汇。"},"latinIntro":{"en":"Latin Volcanus, the fire god, and the Greek-origin suffix -icus give volcanic and its relatives volcano, volcanism and volcanology.","cn":"拉丁 Volcanus（火神）与希腊来源的后缀 -icus 构成本词及其同族词，包括表示火山的那个名词、火山作用与火山学。"},"items":[{"word":"volcan-","structure":"Volcanus (Latin god of fire)","meaning":"fire mountain","meaningCN":"火之山","example":"The stem volcan- names the fire god and his mountain.","exampleCN":"词干 volcan- 指火神与他的山。"},{"word":"volcano","structure":"Italian vulcano, from Latin Volcanus","meaning":"a mountain that erupts","meaningCN":"会喷发的山；火山","example":"The volcano rises from the sea.","exampleCN":"那座火山从海面升起。"},{"word":"-ic","structure":"Latin -icus, from Greek -ikos (belonging to)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix -ic turns a noun of place into an adjective.","exampleCN":"后缀 -ic 把指地点的名词变成形容词。"},{"word":"volcanic","structure":"volcano + -ic","meaning":"relating to a volcano","meaningCN":"火山的","example":"The island has a volcanic origin.","exampleCN":"这座岛有火山成因。"},{"word":"volcanically","structure":"volcanic + -ally","meaning":"by volcanic action","meaningCN":"由火山作用地","example":"The ridge was volcanically active for ages.","exampleCN":"这条山脊长期处于火山活动之中。"},{"word":"volcanism","structure":"volcan- + -ism","meaning":"volcanic activity","meaningCN":"火山活动；火山作用","example":"Volcanism shaped the whole plateau.","exampleCN":"火山作用塑造了整个高原。"},{"word":"volcanology","structure":"volcan- + -logy (study of)","meaning":"the study of volcanoes","meaningCN":"火山学","example":"Volcanology combines geology and chemistry.","exampleCN":"火山学结合了地质学与化学。"},{"word":"volcanologist","structure":"volcanology + -ist","meaning":"a specialist in volcanoes","meaningCN":"火山学家","example":"The volcanologist measured the swelling of the cone.","exampleCN":"火山学家测量了锥体的膨胀。"},{"word":"volcanogenic","structure":"volcano + -genic (produced by)","meaning":"produced by volcanic action","meaningCN":"火山成因的","example":"The sediment is volcanogenic, not river-borne.","exampleCN":"这种沉积物是火山成因的，而非河流搬运的。"},{"word":"volcaniclastic","structure":"volcanic + -clastic (broken)","meaning":"made of broken volcanic fragments","meaningCN":"火山碎屑的","example":"The cliff is built of volcaniclastic layers.","exampleCN":"这处崖壁由火山碎屑层构成。"}],"latinEntries":[{"word":"Volcanus","structure":"Volcanus, -i (m., second declension)","meaning":"the Roman god of fire","meaningCN":"罗马火神"},{"word":"Vulcanus","structure":"Vulcanus, -i (m., variant spelling)","meaning":"the same god, the spelling behind the Italian name for a burning mountain","meaningCN":"同一位火神的另一种拼写，也是意大利语火山之名的来源拼写"},{"word":"-icus","structure":"-icus, -a, -um (Latin adjective suffix, from Greek -ikos)","meaning":"belonging to","meaningCN":"属于……的"}]}},{"word":"volcano","ipa_uk":"/vɒlˈkeɪnəʊ/","ipa_us":"/vɑːlˈkeɪnoʊ/","definition_zh":"火山；火山体；火山口构造；海底火山；泥火山；（比喻）一触即发的局势；其他天体上的火山","definition_en":"a mountain or hill built around an opening in a planet's crust through which lava, ash and gases escape, or the opening and structure around it","core_image":"一座锥形山体顶端凹成圆口，暗红的岩流沿坡面向下缓慢推进","scene":"夜里的海岛，锥形山顶映着暗红的光，岩流沿坡面朝海边推进。 The volcano has been quiet for a century, but its summit still glows after dark.","sceneCN":"这里 volcano 是「火山」（第 1 个义项：能喷出岩浆、火山灰与气体的山体）；句意为这座火山已安静了一个世纪，但天黑之后山顶仍在发光。","pos":[{"tag":"n.","zh":"火山；火山体；火山构造；海底火山；泥火山"},{"tag":"n.","zh":"（比喻）一触即发的局势；随时可能爆发的局面"}],"collocations":[{"phrase":"an active volcano","zh":"活火山"},{"phrase":"a dormant volcano","zh":"休眠火山"},{"phrase":"an extinct volcano","zh":"死火山"},{"phrase":"a submarine volcano","zh":"海底火山"},{"phrase":"a mud volcano","zh":"泥火山"},{"phrase":"the slopes of a volcano","zh":"火山的山坡"}],"forms":[{"label":"名词复数","form":"volcanoes"},{"label":"名词所有格","form":"volcano's"},{"label":"形容词（火山的；火山造成的）","form":"volcanic"},{"label":"副词（以火山方式）","form":"volcanically"},{"label":"名词（火山学）","form":"volcanology"}],"derivatives":[{"word":"volcanic","pos":"adj.","zh":"火山的；火山造成的；火山似的"},{"word":"volcanically","pos":"adv.","zh":"以火山的方式；火山地"},{"word":"volcanology","pos":"n.","zh":"火山学"},{"word":"volcanologist","pos":"n.","zh":"火山学家"},{"word":"volcanism","pos":"n.","zh":"火山作用；火山活动"}],"senses":[{"no":"01","title":"A mountain that erupts","titleCN":"能喷出岩浆与火山灰的山体","definition":"a mountain or hill built around an opening through which lava, ash and gas escape from the interior","definitionCN":"围绕一个通道堆积而成、岩浆、火山灰与气体由此从内部逸出的山体","example":"The volcano has been quiet for a century, but its summit still glows after dark.","exampleCN":"这座火山已安静了一个世纪，但天黑之后山顶仍在发光。","why":"volcano names the whole hill, and the name came from an island whose smoking summit was treated as the workshop of the Roman fire god.","whyCN":"volcano 指整座山丘，这个名字来自一座岛：岛上冒烟的峰顶被当作罗马火神的作坊。"},{"no":"02","title":"The vent and the edifice around it","titleCN":"火山通道与喷口构造","definition":"the opening in the crust together with the pipe, crater and layers of ejected material that surround it","definitionCN":"地壳上的开口，连同其周围的通道、火山口与喷出物层","example":"Drills reached the throat of the volcano but not the magma chamber beneath it.","exampleCN":"钻头抵达了这座火山的喉管，却没有到达其下的岩浆房。","why":"specialists use volcano for the plumbed structure, not merely the visible cone, so the word covers what feeds the summit as well as what is seen.","whyCN":"专家用 volcano 指带通道的整座构造，而不只是可见的锥体，因此这个词既涵盖山顶所见，也涵盖向它供料的部分。"},{"no":"03","title":"Active, dormant or extinct","titleCN":"活火山、休眠火山与死火山","definition":"a volcano classified by whether it is currently erupting, may erupt again, or has no remaining supply of magma","definitionCN":"按当前是否喷发、是否可能再喷发、或已无岩浆补给而分类的火山","example":"Geologists classed the volcano as dormant rather than extinct.","exampleCN":"地质学家把这座火山归为休眠火山，而不是死火山。","why":"once volcanoes were sorted by behaviour, the noun carried a state as well as a shape, which is why the three labels attach to it so naturally.","whyCN":"当火山按活动性被分类之后，这个名词便同时承载状态与形状，因此三个标签能如此自然地附在它上面。"},{"no":"04","title":"A volcano beneath the sea","titleCN":"海底火山","definition":"a volcano on the ocean floor, which may build a ridge or an island without ever reaching the surface","definitionCN":"位于海底的火山，可能堆出海岭或岛屿，却始终未必露出水面","example":"A submarine volcano can raise a ridge without breaking the surface.","exampleCN":"海底火山可以堆起一道海岭，却不露出水面。","why":"the same structure exists under water, so the noun needs only a place adjective and keeps its full meaning.","whyCN":"同样的构造存在于水下，因此这个名词只需加一个地点形容词，含义完全保留。"},{"no":"05","title":"A mud volcano","titleCN":"泥火山","definition":"a vent that pushes mud, water and gas to the surface without any molten rock","definitionCN":"把泥浆、水与气体推上地表、但并不含熔岩的喷口","example":"The mud volcano bubbled grey slurry into the field.","exampleCN":"那座泥火山把灰色泥浆冒到田里。","why":"the cone shape and the outpouring resemble a real volcano, so the word was borrowed although the fluid is not magma.","whyCN":"锥形与喷涌的样子都像真正的火山，尽管流体并非岩浆，词仍被借用。"},{"no":"06","title":"A situation ready to explode","titleCN":"比喻：一触即发的局势","definition":"a place, group or issue holding so much tension that a small trigger could set off open conflict","definitionCN":"张力极大、只需一点触发就可能爆发公开冲突的地方、群体或议题","example":"The border dispute is a volcano waiting to erupt.","exampleCN":"这场边界争端是一座随时会喷发的火山。","why":"the metaphor keeps the pressure and the vent: something below is hot and the surface above it is too thin.","whyCN":"这个比喻保留了压力与喷口：底下滚烫，上面的地表太薄。"},{"no":"07","title":"A volcano on another world","titleCN":"其他天体上的火山","definition":"a volcanic construct on a planet, moon or asteroid, built by lava, ice or other fluids rising through a crust","definitionCN":"行星、卫星或小行星上由熔岩、冰或其他流体穿过地壳上升而堆成的火山构造","example":"Olympus Mons is the largest volcano in the solar system.","exampleCN":"奥林匹斯山是太阳系中最大的火山。","why":"the word travelled with the concept, and planetary geologists apply it wherever material rises through a crust, whatever the fluid.","whyCN":"词随概念一起迁移，行星地质学家把物质穿过地壳上升之处都称作火山，不论流体是什么。"},{"no":"08","title":"The landform mapped as a whole","titleCN":"作为整体地貌来测绘的火山","definition":"the entire landform, including summit, slopes, apron and associated deposits, treated as one mapped unit","definitionCN":"包括山顶、山坡、山麓与相关堆积在内的整个地貌，被视为一个测绘单元","example":"The survey mapped the volcano from summit to outer apron.","exampleCN":"这次测绘把这座火山从山顶到外缘山麓都画了出来。","why":"mapping needs a bounded object, so the everyday noun became a unit on a geological map with edges that can be drawn.","whyCN":"测绘需要一个有边界的对象，于是这个日常名词成为地质图上一个边界可画的单元。"}],"etymology":{"intro":{"en":"Volcano comes from Italian vulcano, the name of the island north of Sicily now called Vulcano, which goes back to Latin Volcanus, the Roman god of fire and metalworking. The deeper origin is uncertain and possibly Etruscan.","cn":"volcano 来自意大利语 vulcano，即西西里以北如今名为武尔卡诺的岛，该名又上溯到拉丁 Volcanus——罗马的火与锻造之神。更深来源不确定，可能与伊特鲁里亚语有关。"},"items":[{"era":"LATIN VOLCANUS","en":"Volcanus was the Roman god of fire and the forge; his name was also attached to a small island whose smoking summit was read as his workshop.","cn":"Volcanus 是罗马的火与锻造之神；他的名字也被附在一座小岛上，岛上冒烟的峰顶被看作他的作坊。"},{"era":"ITALIAN VULCANO","en":"Italian vulcano named that island and then any burning mountain in the region, so a proper name became a common noun.","cn":"意大利语 vulcano 先指那座岛，继而指该地区任何燃烧的山，一个专名由此变成普通名词。"},{"era":"ENGLISH VOLCANO","en":"English records the word in the early seventeenth century, often spelled vulcano at first; the modern spelling settled later.","cn":"英语文献在十七世纪初记录到这个词，早期多拼作 vulcano，现代拼写较晚才固定。"},{"era":"SCIENTIFIC BROADENING","en":"Geology widened the word from one mountain to any vent with its built edifice, including submarine and mud examples.","cn":"地质学把该词从一座山扩展到任何喷口及其堆成的构造，包括海底与泥火山的例子。"},{"era":"PLANETARY USE","en":"Space science then applied it to other solid bodies, where relief is built from lava, ice or sulfur rather than the Mediterranean model.","cn":"空间科学随后把它用于其他固态天体，那里的地形由熔岩、冰或硫建成，而非地中海式样板。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin only): the Etruscan link for Volcanus is a reasonable hypothesis rather than a proven etymology, and the earliest English citation is dated only approximately.","cn":"来源不确定（仅更深词源）：Volcanus 与伊特鲁里亚语的联系只是合理假说，并非已证实的词源；最早英语书证的年代也只能给约数。"}]},"similar":{"note":{"en":"Group one holds words built on the same fire-god stem or on the modern volcano stem; group two holds landform neighbours that share shape or setting.","cn":"第一组是由同一个火神词干或现代 volcano 词干构成的词；第二组是形状或环境相近的地貌词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"volcanic","ipa":"/vɒlˈkænɪk/","tag":"adjective from volcano","definition":"Of, produced by or resembling a volcano; it describes a quality or origin, while volcano names the thing itself.","definitionCN":"火山的、火山造成的或火山似的；描述性质或来源，而 volcano 指事物本身。"},{"word":"volcanism","ipa":"/ˈvɒlkənɪzəm/","tag":"process noun","definition":"The set of processes by which magma reaches the surface; it names the activity, not any single mountain.","definitionCN":"岩浆到达地表的一整套过程；指活动，而非某座山。"},{"word":"Vulcan","ipa":"/ˈvʌlkən/","tag":"the god's name","definition":"The Roman fire god whose name underlies volcano; in modern use it is also the name of a hypothetical planet inside Mercury's orbit.","definitionCN":"罗马火神，其名是 volcano 的来源；现代也指水星轨道以内的一颗假想行星。"},{"word":"vulcanize","ipa":"/ˈvʌlkənaɪz/","tag":"same god, different trade","definition":"To harden rubber by heat and sulfur; it comes from the same divine name but has nothing to do with mountains.","definitionCN":"用加热与硫使橡胶硬化；同出那个神名，却与山无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mountain","ipa":"/ˈmaʊntɪn/","tag":"general height","definition":"Any large natural elevation of the land; a volcano is one kind of mountain, so the word is broader and says nothing about magma.","definitionCN":"任何高大的天然隆起；火山只是山的一类，因此这个词更宽，也不涉及岩浆。"},{"word":"crater","ipa":"/ˈkreɪtə/","tag":"the hollow","definition":"The bowl-shaped hollow at the top of a volcano or left by an impact; it names only the depression, not the whole edifice.","definitionCN":"火山顶部或撞击留下的碗状凹坑；只指那个凹陷，不指整座构造。"},{"word":"caldera","ipa":"/kælˈdɪərə/","tag":"collapsed hollow","definition":"A large hollow formed when a volcano's summit collapses after a major eruption, much wider than an ordinary crater.","definitionCN":"火山在一次大喷发后顶部塌陷形成的大凹地，比普通火山口宽得多。"},{"word":"vent","ipa":"/vent/","tag":"the opening alone","definition":"The actual opening from which lava or gas escapes; a vent can exist without any mountain built around it.","definitionCN":"岩浆或气体逸出的实际开口；喷口可以存在，却没有任何山体围绕。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"volcano is Italian vulcano, the smoking island that Romans linked to their fire god Volcanus.","cn":"volcano 就是意大利语 vulcano，那座冒烟的岛被罗马人联系到火神 Volcanus。"},{"en":"The family runs volcano, volcanoes, volcanic, volcanically, volcanism, volcanology and volcanologist.","cn":"同族词包括 volcano、volcanoes、volcanic、volcanically、volcanism、volcanology、volcanologist。"},{"en":"Phrases grade activity: an active volcano, a dormant volcano, an extinct volcano.","cn":"搭配按活动性分级：活火山、休眠火山、死火山。"},{"en":"The old spelling survives in place names: the island of Vulcano still lies north of Sicily.","cn":"旧拼写留在地名里：武尔卡诺岛仍在西西里以北。"},{"en":"The metaphor is always about pressure: a volcano waiting to erupt, a political volcano.","cn":"比喻始终围绕压力：一座随时喷发的火山、一个政治火山。"}],"abstract":[{"en":"Picture a pressure cooker whose lid has been welded shut.","cn":"想象一只盖子被焊死的压力锅。"},{"en":"Picture a polite dinner table where one remark could turn the room into shouting.","cn":"想象一张客气的餐桌，一句评语就能让整屋人吵起来。"},{"en":"Picture a chart that has been flat for years and then jumps off the page.","cn":"想象一张多年持平的图表，然后突然跳出纸面。"}]},"examples":[{"en":"The volcano threw ash high enough to close the airport.","cn":"这座火山把火山灰抛得足够高，致使机场关闭。"},{"en":"Farmers still keep vineyards on the lower slopes of the volcano.","cn":"农民仍在火山的低坡上经营葡萄园。"},{"en":"Analysts called the loan market a volcano that could blow at any time.","cn":"分析人士把贷款市场称为一座随时可能爆发的火山。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「volcan（火神）＋o（山口）」——火神的作坊冒着烟 → 火山","word":"volcano"},"root":"意大利语 vulcano（岛名）← 拉丁 Volcanus（罗马火神）→ 英语 volcano；深层来源可能与伊特鲁里亚语有关，但不确。","sensesIntro":{"en":"Eight senses move from the hill that erupts to the plumbing that feeds it: a mountain, a vent system, an activity state, a submarine and a muddy variant, a political metaphor, a construct on another world, and finally a bounded landform on a map.","cn":"八个义项从会喷发的山体走向给它供料的通道：山、喷口系统、活动状态、海底与泥浆变体、政治比喻、其他天体上的构造，最后是地图上有边界的整体地貌。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cone with a hollow summit, dark melt creeping down its slope toward the sea.","cn":"核心意象：顶端凹陷的锥体，暗色熔融物沿坡面向海推进。"},"chain":["ERUPTING MOUNTAIN","VENT AND EDIFICE","ACTIVITY STATE","UNDER THE SEA","READY TO EXPLODE","OTHER WORLD"],"branches":[{"senses":"S1 · S2","en":"MOUNTAIN AND PLUMBING: what is seen above ground and the pipe that feeds it.","cn":"山体与管道：地表所见之物，以及给它供料的通道。"},{"senses":"S3","en":"STATE: a volcano is also a status, from active through dormant to extinct.","cn":"状态：火山也是一种状态，从活到休眠再到死。"},{"senses":"S4 · S5","en":"HIDDEN FLUIDS: under the sea, or mud and gas instead of magma.","cn":"隐蔽的流体：在海底，或以泥浆与气体代替岩浆。"},{"senses":"S6","en":"METAPHOR: pressure held under a surface too thin to contain it.","cn":"比喻：压力被压在一层过于薄弱的表面之下。"},{"senses":"S7 · S8","en":"OTHER WORLDS AND MAPS: a construct on any solid body, and a bounded unit to survey.","cn":"异星与地图：任何固态天体上的构造，以及可供测绘的有界单元。"}]},"affixes":{"intro":{"en":"Volcano is not built from productive English affixes; it is a borrowed Italian word whose stem carries the name of a Roman god.","cn":"volcano 并非由能产的英语词缀构成，而是一个借入的意大利语词，其词干承载着一位罗马神的名字。"},"latinIntro":{"en":"Latin Volcanus, the fire god, reaches English through Italian vulcano and also through the adjective volcanic and the process noun volcanism.","cn":"拉丁 Volcanus（火神）经意大利语 vulcano 进入英语，也经形容词 volcanic 与过程名词 volcanism 进入英语。"},"items":[{"word":"volcan-","structure":"Volcanus (Latin name of the fire god)","meaning":"the fire god; fire and the forge","meaningCN":"火神；火与锻造","example":"The stem volcan- carries the god's name into the mountain word.","exampleCN":"词干 volcan- 把这位神的名字带进了指山的词。"},{"word":"-o","structure":"-o (Italian masculine noun ending)","meaning":"noun ending, not a meaning of its own","meaningCN":"名词词尾，本身不表义","example":"Vulcano was reshaped as volcano with the Italian ending kept.","exampleCN":"vulcano 被改造成 volcano，意大利语词尾保留了下来。"},{"word":"volcano","structure":"volcan- + -o (Italian borrowing)","meaning":"the fire god's mountain","meaningCN":"火神的山","example":"The volcano rose straight from the sea.","exampleCN":"这座火山直接从海里升起。"},{"word":"volcanic","structure":"volcano + -ic (adjective-forming)","meaning":"of or produced by a volcano","meaningCN":"火山的；火山造成的","example":"Volcanic ash grounded the flights for two days.","exampleCN":"火山灰使航班停飞了两天。"},{"word":"volcanically","structure":"volcanic + -ally (adverb-forming)","meaning":"in a volcanic manner; by volcanic action","meaningCN":"以火山方式；由火山作用","example":"The ridge is volcanically active today.","exampleCN":"这道海岭如今火山活动活跃。"},{"word":"volcanism","structure":"volcano + -ism (process noun)","meaning":"the process of volcanic activity","meaningCN":"火山作用这一过程","example":"Volcanism built the whole island chain.","exampleCN":"火山作用建起了整条岛链。"},{"word":"volcanology","structure":"volcano + -logy (study of)","meaning":"the scientific study of volcanoes","meaningCN":"火山学","example":"Volcanology combines field mapping with gas chemistry.","exampleCN":"火山学把野外测绘与气体化学结合起来。"},{"word":"volcanologist","structure":"volcanology + -ist (person who)","meaning":"a specialist in volcanoes","meaningCN":"火山学家","example":"A volcanologist sampled the plume on the windward side.","exampleCN":"一位火山学家在迎风面采集了烟柱样品。"},{"word":"vulcanize","structure":"Vulcan + -ize (verb-forming)","meaning":"to harden rubber with heat and sulfur","meaningCN":"用加热与硫使橡胶硬化","example":"The plant vulcanizes rubber under pressure.","exampleCN":"这家工厂在加压下使橡胶硫化。"}],"latinEntries":[{"word":"Volcanus","structure":"Volcanus, Volcani (m., second declension; also spelled Vulcanus)","meaning":"Roman god of fire and the forge","meaningCN":"罗马的火与锻造之神"}]}},{"word":"volcanism","ipa_uk":"/ˈvɒlkənɪzəm/","ipa_us":"/ˈvɑːlkənɪzəm/","definition_zh":"火山作用；火山活动；火山现象；行星火山作用","definition_en":"the set of processes by which magma, gases and other fluids rise from a planet's interior to its surface, and the phenomena that result","core_image":"地下的熔融物质沿裂隙上涌，在地表堆出锥丘、铺开岩流，同时把气体送入大气","scene":"裂谷边缘，勘察队刚布好仪器，地面正在缓慢抬升。 Along the rift, volcanism keeps building new crust even between eruptions.","sceneCN":"这里 volcanism 是「火山作用」（第 1 个义项：岩浆与气体由星球内部上升到地表的过程及其产物）；句意为裂谷一带的火山作用在两次喷发之间仍在不断生成新的地壳。","pos":[{"tag":"n.","zh":"火山作用；火山活动；火山现象的总称"}],"collocations":[{"phrase":"active volcanism","zh":"活跃的火山作用"},{"phrase":"global volcanism","zh":"全球火山作用"},{"phrase":"planetary volcanism","zh":"行星火山作用"},{"phrase":"effusive volcanism","zh":"溢流式火山作用"},{"phrase":"explosive volcanism","zh":"爆炸式火山作用"},{"phrase":"subglacial volcanism","zh":"冰下火山作用"}],"forms":[{"label":"名词（不可数，通例单数）","form":"volcanism"},{"label":"名词复数（指多种类型）","form":"volcanisms"},{"label":"形容词（火山的；火山作用的）","form":"volcanic"},{"label":"副词（以火山方式）","form":"volcanically"},{"label":"名词（火山学家）","form":"volcanologist"},{"label":"异体拼写（旧式）","form":"vulcanism"}],"derivatives":[{"word":"volcanic","pos":"adj.","zh":"火山的；火山作用的；火山似的"},{"word":"volcanically","pos":"adv.","zh":"以火山方式；由火山作用"},{"word":"volcanology","pos":"n.","zh":"火山学"},{"word":"volcanologist","pos":"n.","zh":"火山学家"},{"word":"cryovolcanism","pos":"n.","zh":"冰火山作用（喷出的是水、氨等挥发性物质）"}],"senses":[{"no":"01","title":"The process itself","titleCN":"火山作用这一过程","definition":"the rise of magma and associated fluids from the interior to the surface, together with the phenomena it produces","definitionCN":"岩浆及相关流体由内部上升到地表的过程，连同它所造成的现象","example":"Along the rift, volcanism keeps building new crust even between eruptions.","exampleCN":"裂谷一带的火山作用在两次喷发之间仍在不断生成新的地壳。","why":"volcanism adds -ism to volcano, and that suffix turns a thing into a process, so the word names activity rather than a mountain.","whyCN":"volcanism 在 volcano 之后加 -ism，这个后缀把事物变成过程，因此此词指活动而非山体。"},{"no":"02","title":"The global pattern of activity","titleCN":"全球火山作用的分布格局","definition":"the worldwide distribution of volcanic activity, concentrated at plate boundaries, rifts and hot spots","definitionCN":"全球火山活动的分布，集中于板块边界、裂谷与热点","example":"Global volcanism clusters along the rim of the Pacific.","exampleCN":"全球火山作用集中分布在太平洋边缘。","why":"once the process was mapped, the same noun could name a pattern on a world map rather than a single vent.","whyCN":"当这个过程被绘制成图之后，同一个名词便能指世界地图上的格局，而不只是一个喷口。"},{"no":"03","title":"Volcanic activity on other worlds","titleCN":"行星火山作用","definition":"volcanic activity on any solid body, driven by internal heat from tidal flexing, decay or residual accretion","definitionCN":"任何固态天体上的火山活动，由潮汐揉搓、放射性衰变或残余吸积的内热驱动","example":"On Io, volcanism renews the surface faster than impacts can mark it.","exampleCN":"在木卫一上，火山作用更新表面的速度快过撞击留下痕迹的速度。","why":"the process does not depend on Earth's particular tectonics, so planetary science kept the noun and changed only the setting.","whyCN":"这一过程并不依赖地球特有的构造机制，因此行星科学保留了这个名词，只更换了场景。"},{"no":"04","title":"Effusive versus explosive style","titleCN":"溢流式与爆炸式喷发方式","definition":"the manner in which material leaves a vent, from quiet lava flows to violent fragmentation and tall columns","definitionCN":"物质离开喷口的方式，从安静的岩流到猛烈的碎化与高耸灰柱","example":"Effusive volcanism builds broad shields instead of steep cones.","exampleCN":"溢流式火山作用堆出宽阔的盾状体，而不是陡峭的锥体。","why":"the noun covers the whole process, so a style adjective can pick out one mode of that process without changing the noun.","whyCN":"这个名词涵盖整个过程，因此加一个方式形容词就能挑出其中一种模式，而名词本身不变。"},{"no":"05","title":"Ancient volcanism in the rock record","titleCN":"岩石记录中的古老火山作用","definition":"volcanic activity of the geological past, read from lava flows, ash layers and intrusive bodies","definitionCN":"地质历史时期的火山活动，从岩流、火山灰层与侵入体读出","example":"Ancient volcanism left thick basalt flows across the basin.","exampleCN":"古老的火山作用在整个盆地留下厚厚的玄武岩流。","why":"a process can be ancient, so the same noun describes activity known only from its products, with no live vent left.","whyCN":"过程可以是古老的，因此同一个名词能描述仅由产物得知、已无活动喷口的活动。"},{"no":"06","title":"Cryovolcanism","titleCN":"冰火山作用","definition":"eruption of water, ammonia or other volatiles instead of molten rock, chiefly on icy bodies","definitionCN":"喷出的是水、氨或其他挥发性物质而非熔岩，主要见于冰质天体","example":"Cryovolcanism on icy moons releases water through cracks in the shell.","exampleCN":"冰质卫星上的冰火山作用通过冰壳裂缝释放水。","why":"the prefix cryo- marks the fluid as cold, while volcanism supplies the whole rising-and-erupting frame.","whyCN":"前缀 cryo- 标明流体是冷的，而 volcanism 提供整套上涌并喷出的框架。"},{"no":"07","title":"Volcanism and climate","titleCN":"火山作用与气候","definition":"the effect of volcanic gases and particles on atmospheric temperature, chemistry and circulation","definitionCN":"火山气体与颗粒对大气温度、化学成分与环流的影响","example":"Large-scale volcanism can cool the climate for several years.","exampleCN":"大规模的火山作用能使气候变冷数年。","why":"because the word names a process with outputs, it easily takes a second noun naming what those outputs act upon.","whyCN":"因为此词指带产物的过程，它很容易再接一个名词，说明这些产物作用于什么。"},{"no":"08","title":"The object of a science","titleCN":"火山学的研究对象","definition":"the process as observed, measured and modelled by volcanologists","definitionCN":"被火山学家观测、测量与建模的过程","example":"Researchers treat volcanism as a process to be measured, not merely described.","exampleCN":"研究者把火山作用视为需要测量的过程，而不只是加以描述。","why":"a named process can become a research object, so the noun also serves as the subject matter of a discipline.","whyCN":"被命名的过程可以成为研究对象，因此这个名词也充当一门学科的主题。"}],"etymology":{"intro":{"en":"Volcanism is an English coinage of the nineteenth century: volcano plus the suffix -ism, which reached English through French and Latin from Greek -ismos. It names the process rather than the mountain.","cn":"volcanism 是十九世纪英语新构的词：volcano 加后缀 -ism，而 -ism 经法语与拉丁语来自希腊语 -ismos。它指过程，而非山体。"},"items":[{"era":"LATIN VOLCANUS","en":"Volcanus was the Roman god of fire and the forge, and his name passed to a smoking island north of Sicily.","cn":"Volcanus 是罗马的火与锻造之神，他的名字传给了西西里以北一座冒烟的岛。"},{"era":"ITALIAN VULCANO TO VOLCANO","en":"Italian vulcano gave English volcano, so the stem already meant a burning mountain before any suffix was added.","cn":"意大利语 vulcano 给了英语 volcano，因此在加任何后缀之前，这个词干已指燃烧的山。"},{"era":"GREEK -ISMOS","en":"-ismos was a Greek suffix forming nouns of action, practice or system; Latin -ismus and French -isme carried it into English.","cn":"-ismos 是希腊语后缀，构成表示动作、实践或体系的名词；拉丁 -ismus 与法语 -isme 把它带入英语。"},{"era":"NINETEENTH-CENTURY COINAGE","en":"English formed volcanism to name the process as a subject of study, at a time when geology was separating into specialised fields.","cn":"英语构造出 volcanism，把这一过程作为研究对象命名，当时地质学正分化为若干专门领域。"},{"era":"PLANETARY EXTENSION","en":"Twentieth-century planetary science widened volcanism to any solid world and coined cryovolcanism for icy bodies.","cn":"二十世纪的行星科学把 volcanism 扩展到任何固态天体，并为冰质天体造出 cryovolcanism。"},{"era":"SPELLING AND UNCERTAINTY","en":"The older spelling vulcanism persists in some texts and carried alchemical overtones; the deeper origin of Volcanus is uncertain and possibly Etruscan.","cn":"较旧的拼法 vulcanism 仍见于部分文本，并带炼金术色彩；Volcanus 的更深来源不确定，可能与伊特鲁里亚语有关。"}]},"similar":{"note":{"en":"Group one holds forms built on the same volcano stem, including the old spelling; group two holds terms for the activity or its products.","cn":"第一组是由同一个 volcano 词干构成的形式，包括旧拼法；第二组是表示这种活动或其产物的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"volcano","ipa":"/vɒlˈkeɪnəʊ/","tag":"the thing, not the process","definition":"The mountain or vent structure itself; volcanism is what that structure does over time.","definitionCN":"山体或喷口构造本身；volcanism 是这种构造在时间中的活动。"},{"word":"volcanic","ipa":"/vɒlˈkænɪk/","tag":"adjective","definition":"Of or produced by a volcano; it describes material or origin, while volcanism names the whole process.","definitionCN":"火山的或火山造成的；描述材料或来源，而 volcanism 指整个过程。"},{"word":"vulcanism","ipa":"/ˈvʌlkənɪzəm/","tag":"older spelling","definition":"An older variant spelling of volcanism, also used in alchemical writing for the action of fire; not a separate process.","definitionCN":"volcanism 的较旧异体拼写，也用于炼金术文献指火的作用；并非另一种过程。"},{"word":"volcanology","ipa":"/vɒlˈkænələdʒi/","tag":"the study","definition":"The science that studies volcanism and its products; the discipline is named after the process, not the reverse.","definitionCN":"研究火山作用及其产物的学科；学科名由过程名而来，而非相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"magmatism","ipa":"/ˈmæɡmətɪzəm/","tag":"broader internal process","definition":"The generation and movement of magma anywhere in a planet, including bodies that never reach the surface; volcanism is its surface expression.","definitionCN":"行星内部岩浆的生成与运移，包括从未到达地表的部分；volcanism 是它的地表表现。"},{"word":"eruption","ipa":"/ɪˈrʌpʃn/","tag":"one event","definition":"A single act of material bursting out; volcanism is the long-running process that produces many such events.","definitionCN":"物质冲出的一次动作；volcanism 是产生许多此类事件的长过程。"},{"word":"igneous activity","ipa":"/ˈɪɡniəs ækˈtɪvəti/","tag":"rock-centred phrase","definition":"Activity involving molten rock and its solidification; it stresses the rock produced rather than the surface phenomena.","definitionCN":"涉及熔融岩石及其固结的活动；强调生成的岩石，而非地表现象。"},{"word":"geothermal activity","ipa":"/ˌdʒiːəʊˈθɜːml ækˈtɪvəti/","tag":"heat-centred phrase","definition":"Surface evidence of internal heat such as hot springs and steam; it can occur with little or no magma involved.","definitionCN":"内部热量的地表表现，如温泉与蒸汽；可以在很少或没有岩浆参与时发生。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"volcano plus -ism: the mountain name turned into the name of a process.","cn":"volcano 加 -ism：山名变成了过程名。"},{"en":"The family runs volcanism, volcanic, volcanically, volcanology, volcanologist and cryovolcanism.","cn":"同族词包括 volcanism、volcanic、volcanically、volcanology、volcanologist、cryovolcanism。"},{"en":"Style pairs fix the meaning: effusive volcanism, explosive volcanism.","cn":"方式搭配固定词义：溢流式火山作用、爆炸式火山作用。"},{"en":"Planetary contexts extend it: global volcanism, planetary volcanism, subglacial volcanism.","cn":"行星语境扩展它的用法：全球火山作用、行星火山作用、冰下火山作用。"},{"en":"Spelling note: modern science writes volcanism, while vulcanism survives as an older and alchemy-tinged variant.","cn":"拼写提示：现代科学写作 volcanism，而 vulcanism 作为较旧且带炼金术色彩的异体仍存。"}],"abstract":[{"en":"Picture a kettle that never stops steaming, even when nobody is watching.","cn":"想象一只没人看守却始终冒汽的水壶。"},{"en":"Picture a slow conveyor laying new floor tiles from below, year after year.","cn":"想象一条缓慢的传送带，年复一年从下面铺出新地砖。"},{"en":"Picture a city whose subway map shows many lines rising from one deep source.","cn":"想象一张地铁图，许多线路从同一个深处源头升起。"}]},"examples":[{"en":"Volcanism built the island chain over millions of years.","cn":"火山作用在数百万年间建起了这条岛链。"},{"en":"Satellite images revealed active volcanism beneath the ice sheet.","cn":"卫星图像显示冰盖之下存在活跃的火山作用。"},{"en":"The course compares Earth's volcanism with the ice-driven kind on distant moons.","cn":"这门课程把地球的火山作用与遥远卫星上由冰驱动的类型作比较。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「volcan（火山）＋ism（过程、体系）」——把山名变成持续发生的过程 → 火山作用","word":"volcanism"},"root":"volcano（← 意大利语 vulcano ← 拉丁 Volcanus「火神」）+ 后缀 -ism（← 希腊 -ismos，经拉丁 -ismus）→ volcanism；词指过程，不指山体。","sensesIntro":{"en":"Eight senses follow a process rather than an object: the process itself, its global pattern, its planetary reach, its eruption styles, its record in old rock, its icy variant, its effect on climate, and its status as a measured science.","cn":"八个义项沿着一个过程而非一个物件展开：过程本身、全球格局、行星范围、喷发方式、古老岩石中的记录、冰质变体、对气候的影响，最后成为被测量的学科对象。"},"semanticMap":{"core":{"en":"CORE IMAGE: melt rising through a crack, piling a cone and feeding the air above.","cn":"核心意象：熔融物沿裂缝上涌，堆起锥丘，并向上方大气供料。"},"chain":["THE PROCESS","GLOBAL PATTERN","PLANETARY REACH","ERUPTION STYLE","ANCIENT RECORD","ICE AND CLIMATE"],"branches":[{"senses":"S1","en":"THE PROCESS: activity, not a thing, which is what -ism contributes.","cn":"过程本身：是活动而非物件，这正是 -ism 带来的意义。"},{"senses":"S2 · S3","en":"WHERE IT HAPPENS: a pattern on a world map, then a process on any solid body.","cn":"发生之处：先是世界地图上的格局，随后是任何固态天体上的过程。"},{"senses":"S4","en":"HOW IT HAPPENS: quiet flows and violent columns are two modes of one process.","cn":"发生方式：安静的岩流与猛烈的灰柱是同一过程的两种模式。"},{"senses":"S5 · S6","en":"DEEP TIME AND COLD FLUIDS: the same frame survives in old rock and in icy eruptions.","cn":"深时与冷流体：同一框架在古老岩石与冰质喷发中都成立。"},{"senses":"S7 · S8","en":"EFFECT AND STUDY: outputs change the climate, and the process becomes a measured object.","cn":"影响与研究：产物改变气候，过程本身成为被测量的对象。"}]},"affixes":{"intro":{"en":"Volcanism joins a borrowed proper-name stem to a productive suffix, which is why the word names a process despite its foreign root.","cn":"volcanism 把一个借入的专名词干接到一个能产后缀上，因此尽管词根来自外语，这个词却指一种过程。"},"latinIntro":{"en":"Latin Volcanus supplies the stem, and Latin -ismus, from Greek -ismos, supplies the process suffix seen in volcanism.","cn":"拉丁 Volcanus 提供词干，来自希腊 -ismos 的拉丁 -ismus 提供 volcanism 中所见的过程后缀。"},"items":[{"word":"volcan-","structure":"Volcanus (Latin name of the fire god)","meaning":"the fire god; fire and the forge","meaningCN":"火神；火与锻造","example":"The stem volcan- is the name of the fire god.","exampleCN":"词干 volcan- 就是那位火神的名字。"},{"word":"-o","structure":"-o (Italian masculine noun ending)","meaning":"noun ending carried over from Italian","meaningCN":"从意大利语带来的名词词尾","example":"The Italian ending -o survives in the borrowed volcano.","exampleCN":"意大利语词尾 -o 在借入的 volcano 中保留下来。"},{"word":"-ism","structure":"-ismos (Greek), -ismus (Latin), -isme (French)","meaning":"action, practice or system","meaningCN":"动作、实践或体系","example":"The suffix -ism turns a thing into a practice or process.","exampleCN":"后缀 -ism 把事物变成实践或过程。"},{"word":"volcanism","structure":"volcan- + -o + -ism","meaning":"the process of volcanic activity","meaningCN":"火山作用这一过程","example":"Volcanism is the process, not the mountain.","exampleCN":"volcanism 指过程，而不是山。"},{"word":"volcanic","structure":"volcano + -ic (adjective-forming)","meaning":"of or produced by a volcano","meaningCN":"火山的；火山造成的","example":"The volcanic layer marks a pause in deposition.","exampleCN":"火山层标志着沉积的一次停顿。"},{"word":"volcanically","structure":"volcanic + -ally (adverb-forming)","meaning":"by volcanic action","meaningCN":"由火山作用","example":"The region is volcanically active along its axis.","exampleCN":"该区域沿轴部火山活动活跃。"},{"word":"volcanology","structure":"volcan- + -logy (study of)","meaning":"the scientific study of volcanic processes","meaningCN":"研究火山过程的学科","example":"Volcanology draws on geophysics and petrology.","exampleCN":"火山学借助地球物理学与岩石学。"},{"word":"volcanologist","structure":"volcanology + -ist (person who)","meaning":"a specialist in volcanic processes","meaningCN":"研究火山过程的专家","example":"A volcanologist watched the tilt meter all night.","exampleCN":"一位火山学家整夜盯着倾斜仪。"},{"word":"cryovolcanism","structure":"cryo- (cold) + volcanism","meaning":"eruption of cold volatiles such as water or ammonia","meaningCN":"喷出冰冷挥发物（如水或氨）的火山作用","example":"Cryovolcanism builds domes of frozen water on icy moons.","exampleCN":"冰火山作用在冰质卫星上堆出冻结的水丘。"},{"word":"vulcanism","structure":"Vulcan + -ism (older spelling)","meaning":"older spelling of volcanism","meaningCN":"volcanism 的旧拼法","example":"Older texts write vulcanism where modern science writes volcanism.","exampleCN":"较早的文本写作 vulcanism，现代科学写作 volcanism。"}],"latinEntries":[{"word":"Volcanus","structure":"Volcanus, Volcani (m., second declension; also spelled Vulcanus)","meaning":"Roman god of fire and the forge","meaningCN":"罗马的火与锻造之神"},{"word":"ismus","structure":"-ismus (Latin suffix, from Greek -ismos)","meaning":"suffix of action, practice or system","meaningCN":"表示动作、实践或体系的后缀"}]}},{"word":"eruption","ipa_uk":"/ɪˈrʌpʃn/","ipa_us":"/ɪˈrʌpʃn/","definition_zh":"喷发；（火山）爆发；（皮疹）暴发；（牙齿）萌出；（情绪）爆发；突然大量涌现；气体或液体的喷出","definition_en":"a sudden bursting out of material, energy or emotion, especially lava and ash from a volcano","core_image":"封闭的岩层被地下压力顶开，灰柱与熔岩同时冲上天空","scene":"观测站的屏幕上，灰柱从火山口骤然升起，值班员抓起对讲机。 The eruption sent a column of ash high above the island.","sceneCN":"这里 eruption 是「喷发」（第 1 个义项：火山把岩浆、火山灰与气体突然喷出）；句意为这次喷发把一根灰柱送到岛屿上空的高处。","pos":[{"tag":"n.","zh":"喷发；爆发；突然大量涌现；（情绪）爆发"},{"tag":"n.","zh":"（医学）皮疹；疹子；牙齿萌出"}],"collocations":[{"phrase":"a volcanic eruption","zh":"火山喷发"},{"phrase":"an explosive eruption","zh":"爆炸式喷发"},{"phrase":"the eruption column","zh":"喷发柱"},{"phrase":"a skin eruption","zh":"皮疹"},{"phrase":"the eruption of a tooth","zh":"牙齿的萌出"},{"phrase":"an eruption of anger","zh":"怒火的突然爆发"}],"forms":[{"label":"名词复数","form":"eruptions"},{"label":"名词所有格","form":"eruption's"},{"label":"动词（喷发；爆发）","form":"erupt"},{"label":"形容词（喷发的；爆发性的）","form":"eruptive"},{"label":"副词（爆发地）","form":"eruptively"}],"derivatives":[{"word":"erupt","pos":"v.","zh":"喷发；爆发；（皮疹）冒出"},{"word":"eruptive","pos":"adj.","zh":"喷发的；爆发性的；火成的"},{"word":"eruptively","pos":"adv.","zh":"以爆发的方式"},{"word":"erupting","pos":"n./adj.","zh":"喷发（进行中的动作）；正在喷发的"}],"senses":[{"no":"01","title":"A volcanic eruption","titleCN":"火山喷发","definition":"a sudden release of lava, ash and gas from a volcano into the air or onto the surface","definitionCN":"火山把岩浆、火山灰与气体突然释放到空中或地表","example":"The eruption sent a column of ash high above the island.","exampleCN":"这次喷发把一根灰柱送到岛屿上空的高处。","why":"eruption comes from Latin eruptio, a bursting forth, from erumpere, to break out, so a volcano literally breaks out of its crust.","whyCN":"eruption 来自拉丁 eruptio「冲出」，出自动词 erumpere「破出」，因此火山字面上就是冲破地壳而出。"},{"no":"02","title":"An outbreak of rash on the skin","titleCN":"皮肤病疹的暴发","definition":"the sudden appearance and spread of a rash over the body as part of a disease","definitionCN":"作为疾病的一部分，皮疹在全身突然出现并蔓延","example":"Measles brings a widespread eruption that starts behind the ears.","exampleCN":"麻疹会引起一片广泛的皮疹，先从耳后开始。","why":"the old medical use is native to the word: Latin eruptio already named skin lesions breaking out, long before it named mountains.","whyCN":"医学用法是这个词固有的：拉丁 eruptio 早在指火山之前，就已经指皮肤病变的暴出。"},{"no":"03","title":"A tooth breaking through the gum","titleCN":"牙齿萌出","definition":"the process by which a developing tooth pushes through the gum and appears in the mouth","definitionCN":"发育中的牙齿顶穿牙龈、出现在口腔中的过程","example":"The dentist charted the eruption of the first molars.","exampleCN":"牙医记录了第一磨牙的萌出情况。","why":"a tooth physically breaks through tissue, so the same image of breaking out applies without any change of meaning.","whyCN":"牙齿确实顶破组织而出，因此同一个「破出」意象直接适用，词义无需变化。"},{"no":"04","title":"A violent outburst of feeling","titleCN":"暴力或情绪的爆发","definition":"a sudden, forceful expression of anger, laughter or other strong feeling","definitionCN":"愤怒、笑声或其他强烈情绪的突然有力表露","example":"His eruption of anger silenced the room.","exampleCN":"他怒火的爆发让全场安静下来。","why":"what was held under pressure breaks out, exactly as magma does, so the metaphor needs no new vocabulary.","whyCN":"被压住的东西破壳而出，与岩浆完全一样，因此这个比喻不需要新词。"},{"no":"05","title":"A geyser's jet","titleCN":"间歇泉的喷发","definition":"a periodic burst of hot water and steam from a geyser or hot spring","definitionCN":"间歇泉或温泉周期性喷出的热水与蒸汽","example":"The geyser's eruption lasts about four minutes.","exampleCN":"这眼间歇泉的喷发持续约四分钟。","why":"pressurised water finds a narrow opening and shoots out, which is the same physical story as a volcano without the magma.","whyCN":"受压的水找到狭窄开口后冲出去，这与火山是同一个物理故事，只是没有岩浆。"},{"no":"06","title":"A sudden flood of something abstract","titleCN":"抽象事物突然大量涌现","definition":"a sudden large appearance of praise, data, complaints or similar things","definitionCN":"赞誉、数据、抱怨之类事物突然大量出现","example":"The film brought an eruption of praise from critics.","exampleCN":"这部影片引来影评人一片赞誉。","why":"the count noun was extended to anything that arrives suddenly and in quantity, keeping the image of something bursting out.","whyCN":"这个可数名词被扩展到一切突然且大量到来的事物，保留了「冲出」的意象。"},{"no":"07","title":"A single spot on the skin","titleCN":"医学上的单个皮疹","definition":"one small lesion or pimple on the skin, as counted and described by a clinician","definitionCN":"皮肤上的一处小病变或小脓疱，由医生计数并描述","example":"A single eruption appeared on the forearm and faded in a week.","exampleCN":"前臂上出现了一处皮疹，一周内消退。","why":"medicine counts what breaks out, so the mass event and the individual spot share one noun.","whyCN":"医学要对冒出的东西计数，因此整体暴发与单个斑点共用同一个名词。"},{"no":"08","title":"Gas or liquid escaping under pressure","titleCN":"气体或液体受压喷出","definition":"a sudden escape of steam, gas or liquid through a weak point or opening","definitionCN":"蒸汽、气体或液体通过薄弱处或开口突然逸出","example":"A sudden eruption of steam cracked the pipe.","exampleCN":"蒸汽的骤然喷出使管道开裂。","why":"the core event is material breaking out of a container, and a pipe is only a smaller container than a mountain.","whyCN":"核心事件是物质破开容器而出，而管道只是一个比山更小的容器。"}],"etymology":{"intro":{"en":"Eruption comes from Latin eruptio, a bursting forth, from erumpere, built from e-, out, and rumpere, to break. The same rumpere supplies rupture, interrupt, corrupt, abrupt and, through French and Italian, bankrupt.","cn":"eruption 来自拉丁 eruptio「冲出」，出自动词 erumpere，由 e-「出」与 rumpere「破」构成。同一个 rumpere 还衍生出 rupture、interrupt、corrupt、abrupt，并经法语与意大利语衍生出 bankrupt。"},"items":[{"era":"LATIN RUMPERE","en":"Rumpere meant to break or burst; its past participle ruptus supplied the stem rupt- that runs through the whole family.","cn":"rumpere 意为打破或爆裂；其过去分词 ruptus 提供了贯穿整个词族的词干 rupt-。"},{"era":"LATIN ERUMPERE","en":"The prefix e-, out, plus rumpere made erumpere, to break out or burst forth, used for anything escaping a container.","cn":"前缀 e-「出」加 rumpere 构成 erumpere，意为破出、冲出，用于任何从容器中逸出之物。"},{"era":"LATIN ERUPTIO","en":"Eruptio named the act of bursting out; medical Latin used it for rashes breaking out on the skin before geology used it for mountains.","cn":"eruptio 指「冲出」这一动作；医学拉丁语用它指皮肤上暴出的皮疹，比地质学用它指火山更早。"},{"era":"SEVENTEENTH-CENTURY ENGLISH","en":"English borrowed eruption in the seventeenth century, at first chiefly in medical writing about rashes and fevers.","cn":"英语在十七世纪借入 eruption，最初主要用于论皮疹与热病的医学写作。"},{"era":"VOLCANIC AND MODERN SPREAD","en":"The volcanic sense became dominant later, and the word then spread to geysers, teeth, emotions, crowds of praise and escaping steam.","cn":"火山义后来成为主导，这个词随后扩展到间歇泉、牙齿、情绪、如潮的赞誉与逸出的蒸汽。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use only): the earliest English examples are chiefly medical and the date of the volcanic sense is given only approximately.","cn":"来源不确定（仅首用义）：最早的英语例证主要是医学用法，火山义的年代只能给约数。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin breaking stem; group two holds near neighbours for sudden outbursts and their results.","cn":"第一组是同出拉丁「破」词干的词；第二组是表示突然爆发及其结果的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"erupt","ipa":"/ɪˈrʌpt/","tag":"the verb behind it","definition":"To burst out suddenly; eruption is the noun of that action, so the pair differs only in word class.","definitionCN":"突然冲出；eruption 是这一动作的名词形式，两者只差词类。"},{"word":"eruptive","ipa":"/ɪˈrʌptɪv/","tag":"adjective","definition":"Tending to burst out, or produced by an eruption; it describes a quality or origin rather than the event.","definitionCN":"易爆发的，或由喷发造成的；描述性质或来源，而非事件本身。"},{"word":"rupture","ipa":"/ˈrʌptʃə/","tag":"same rupt- stem","definition":"A tear or burst of a pipe, tendon or membrane; it shares the breaking stem but lacks the outward prefix.","definitionCN":"管道、肌腱或膜的撕裂或破裂；共用「破」词干，但没有表示向外的前缀。"},{"word":"interrupt","ipa":"/ˌɪntəˈrʌpt/","tag":"same rupt- stem","definition":"To break into something in progress; the prefix inter- puts the break between two things rather than outward.","definitionCN":"打断正在进行之事；前缀 inter- 让断裂发生在两者之间，而非向外。"}]},{"heading":"NEAR MEANING","entries":[{"word":"outburst","ipa":"/ˈaʊtbɜːst/","tag":"emotional or sudden release","definition":"A sudden release of strong feeling or activity; it is commoner than eruption for laughter or rage and rare for volcanoes.","definitionCN":"强烈情绪或活动的突然释放；用于笑声或愤怒时比 eruption 更常见，用于火山则少见。"},{"word":"explosion","ipa":"/ɪkˈspləʊʒn/","tag":"violent expansion","definition":"A violent expansion driven by a chemical or nuclear reaction; it implies blast energy, not merely material escaping.","definitionCN":"由化学或核反应驱动的猛烈膨胀；强调爆炸能量，而不只是物质逸出。"},{"word":"blast","ipa":"/blɑːst/","tag":"shock wave","definition":"A strong sudden wave of air or heat from an explosion; it names the pressure effect rather than the outpouring.","definitionCN":"爆炸产生的突然强气流或热浪；指压力效应，而非喷出物。"},{"word":"outbreak","ipa":"/ˈaʊtbreɪk/","tag":"disease or conflict","definition":"The sudden start of disease, war or violence; it overlaps with eruption in medicine but not in geology.","definitionCN":"疾病、战争或暴力的突然开始；在医学上与 eruption 重叠，在地质上则不重叠。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"e- out plus rupt- break: to break out, and the noun names that breaking out.","cn":"e-「出」加 rupt-「破」：破壳而出，名词就指这个破出的动作。"},{"en":"The rupt- family runs eruption, erupt, eruptive, rupture, interrupt, corrupt, abrupt and bankrupt.","cn":"rupt- 词族包括 eruption、erupt、eruptive、rupture、interrupt、corrupt、abrupt、bankrupt。"},{"en":"Volcano phrases: a volcanic eruption, an explosive eruption, the eruption column.","cn":"火山搭配：火山喷发、爆炸式喷发、喷发柱。"},{"en":"Medical use survives: a skin eruption, a drug eruption, the eruption of a tooth.","cn":"医学用法仍在：皮疹、药疹、牙齿萌出。"},{"en":"Word class pair: lava erupts, so the result is an eruption; the verb is erupt, not erupt.","cn":"词类配对：岩浆喷出，结果就是一次喷发；动词是 erupt，名词才是 eruption。"}],"abstract":[{"en":"Picture a sealed jar of fermenting liquid with a crack in the lid.","cn":"想象一只密封的发酵罐，盖子上有一道裂缝。"},{"en":"Picture a classroom where one joke sets off a wave of laughter.","cn":"想象一间教室，一个笑话引发一阵笑声。"},{"en":"Picture an inbox that goes from two messages to hundreds overnight.","cn":"想象一个收件箱，一夜之间从两封变成数百封。"}]},"examples":[{"en":"The eruption forced the airline to cancel every flight to the island.","cn":"这次喷发迫使航空公司取消了所有飞往该岛的航班。"},{"en":"A drug eruption covered her arms within hours of the first dose.","cn":"首剂用药后数小时内，药疹就布满了她的双臂。"},{"en":"The announcement produced an eruption of questions from the audience.","cn":"这项宣布引来听众一片问题。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「e（出）＋rupt（破）」——压力从里面破壳而出 → 喷发、爆发","word":"eruption"},"root":"拉丁 eruptio ← erumpere（e-「出」+ rumpere「破」）→ eruption；同族含 erupt、rupture、interrupt、corrupt、abrupt、bankrupt。","sensesIntro":{"en":"Eight senses keep one gesture: something held inside breaks out. The event is volcanic, then medical, dental, emotional, geothermal, statistical, a single lesion, and finally any pressurised fluid.","cn":"八个义项保留同一个动作：被关在里面的东西破壳而出。这个事件先是火山的，然后是医学的、牙齿的、情绪的、地热的、数量上的，再到单个病灶，最后是任何受压流体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sealed layer splitting and material shooting upward and outward.","cn":"核心意象：封闭的岩层裂开，物质向上向外冲出。"},"chain":["VOLCANIC BURST","SKIN OUTBREAK","TOOTH EMERGES","EMOTIONAL OUTBURST","GEYSER JET","SUDDEN ABUNDANCE"],"branches":[{"senses":"S1 · S5 · S8","en":"PRESSURISED MATERIAL: magma, hot water and steam all escape through an opening.","cn":"受压物质：岩浆、热水与蒸汽都通过开口逸出。"},{"senses":"S2 · S7","en":"SKIN: the mass outbreak and the single spot are two scales of the same medical event.","cn":"皮肤：整体暴发与单个斑点，是同一医学事件的两种尺度。"},{"senses":"S3","en":"TEETH: a hard object physically breaks through soft tissue.","cn":"牙齿：坚硬之物确实顶破柔软组织。"},{"senses":"S4","en":"FEELING: what was contained breaks out as anger or laughter.","cn":"情绪：被压住的感受以愤怒或笑声冲出。"},{"senses":"S6","en":"QUANTITY: praise or data arrives suddenly and in bulk.","cn":"数量：赞誉或数据突然且成批地到来。"}]},"affixes":{"intro":{"en":"Eruption is a Latin noun of action: a prefix meaning out, a breaking stem, and a noun suffix, all three visible in the English word.","cn":"eruption 是拉丁动作名词：一个表示「出」的前缀、一个表示「破」的词干、一个名词后缀，三者都保留在英语词里。"},"latinIntro":{"en":"Latin rumpere, erumpere, eruptio and eruptus give eruption, erupt, eruptive, rupture, interrupt, corrupt, abrupt and, through French and Italian, bankrupt.","cn":"拉丁 rumpere、erumpere、eruptio 与 eruptus 衍生 eruption、erupt、eruptive、rupture、interrupt、corrupt、abrupt，并经法语与意大利语衍生 bankrupt。"},"items":[{"word":"e-","structure":"e- (Latin prefix, out of)","meaning":"out, outward","meaningCN":"出；向外","example":"The prefix e- marks movement out of a container.","exampleCN":"前缀 e- 标记离开容器的运动。"},{"word":"rupt-","structure":"ruptus (Latin participle stem of rumpere, 'broken')","meaning":"broken; to break","meaningCN":"破裂的；打破","example":"The stem rupt- carries the breaking in every word of the family.","exampleCN":"词干 rupt- 在词族的每个词里都承载「破」。"},{"word":"-ion","structure":"-io, -ionis (Latin noun suffix of action)","meaning":"the act or result of doing","meaningCN":"动作或结果","example":"Eruptio is the action noun built on the verb.","exampleCN":"eruptio 是在动词之上构成的动作名词。"},{"word":"eruption","structure":"e- + rupt- + -ion","meaning":"a breaking out; a bursting forth","meaningCN":"破出；冲出；喷发","example":"The eruption began before dawn.","exampleCN":"喷发在天亮前开始。"},{"word":"erupt","structure":"e- + rumpere (verb)","meaning":"to burst out","meaningCN":"喷发；爆发","example":"The seam erupted without warning.","exampleCN":"裂缝在毫无预警的情况下喷发。"},{"word":"eruptive","structure":"erupt + -ive (adjective-forming)","meaning":"bursting out; produced by eruption","meaningCN":"爆发性的；喷发造成的","example":"The eruptive phase lasted three weeks.","exampleCN":"喷发阶段持续了三周。"},{"word":"rupture","structure":"rupt- + -ure (noun suffix of result)","meaning":"a break or tear","meaningCN":"破裂；撕裂","example":"The rupture in the pipe released steam.","exampleCN":"管道上的破裂释放出蒸汽。"},{"word":"interrupt","structure":"inter- (between) + rumpere (break)","meaning":"to break in between","meaningCN":"打断；中断","example":"A shout interrupted the reading.","exampleCN":"一声喊叫打断了朗读。"},{"word":"corrupt","structure":"cor- (thoroughly) + rumpere (break)","meaning":"to break morally; to spoil","meaningCN":"使腐化；败坏","example":"The offer corrupted the clerk.","exampleCN":"这份好处使那名职员腐化。"},{"word":"abrupt","structure":"ab- (away, off) + rumpere (break)","meaning":"broken off short; sudden","meaningCN":"突然的；断裂般的","example":"The meeting came to an abrupt end.","exampleCN":"会议突然结束。"},{"word":"bankrupt","structure":"banca rotta (Italian, 'broken bench') via French, from Latin rupta","meaning":"financially broken","meaningCN":"破产的","example":"The firm went bankrupt that winter.","exampleCN":"那家公司在那个冬天破产了。"}],"latinEntries":[{"word":"rumpere","structure":"rumpere, rupi, ruptum (verb, third conjugation)","meaning":"to break, burst","meaningCN":"打破；爆裂"},{"word":"erumpere","structure":"erumpere, erupi, eruptum (verb, third conjugation)","meaning":"to break out, burst forth","meaningCN":"破出；冲出"},{"word":"eruptio","structure":"eruptio, eruptionis (f., third declension)","meaning":"a bursting forth; an outbreak","meaningCN":"冲出；暴发"},{"word":"eruptus","structure":"eruptus, -a, -um (perfect passive participle)","meaning":"having burst forth","meaningCN":"已冲出的"}]}},{"word":"erupt","ipa_uk":"/ɪˈrʌpt/","ipa_us":"/ɪˈrʌpt/","definition_zh":"（火山）喷发；喷出（熔岩、气体、灰）；突然爆发（怒气、笑声、暴力）；突然出现（皮疹）；（牙齿）萌出","definition_en":"to burst out suddenly, especially of a volcano throwing out lava and ash, or of anger, laughter, noise, a rash or a tooth breaking through","core_image":"地下的压力积到极限，黑色山口忽然撕开，火光、灰柱与石块一起冲向天空","scene":"火山观测站的屏幕上，地表微微鼓起，仪器指针剧烈跳动。 The volcano began to erupt just after midnight, throwing ash high above the island.","sceneCN":"这里 erupt 指火山喷发（第 1 个义项：熔岩、气体与火山灰从火山口猛烈喷出）；句意为那座火山在午夜刚过时开始喷发，把火山灰抛到岛屿上空。","pos":[{"tag":"v.","zh":"（火山）喷发；喷出（熔岩、气体、火山灰）"},{"tag":"v.","zh":"突然爆发（怒气、笑声、掌声、暴力）"},{"tag":"v.","zh":"突然出现（皮疹、斑点）；（牙齿）萌出"}],"collocations":[{"phrase":"erupt into violence","zh":"突然演变为暴力冲突"},{"phrase":"erupt in laughter","zh":"爆发出笑声"},{"phrase":"erupt with anger","zh":"勃然大怒"},{"phrase":"a volcano erupts","zh":"火山喷发"},{"phrase":"erupt through the crust","zh":"冲破地壳喷出"},{"phrase":"erupt at regular intervals","zh":"按固定间隔喷发"}],"forms":[{"label":"三单（he/she/it）","form":"erupts"},{"label":"过去式","form":"erupted"},{"label":"过去分词","form":"erupted"},{"label":"现在分词","form":"erupting"},{"label":"名词（喷发）","form":"eruption"}],"derivatives":[{"word":"eruption","pos":"n.","zh":"喷发；爆发；皮疹"},{"word":"eruptive","pos":"adj.","zh":"喷发性的；突发的；发疹的"},{"word":"rupture","pos":"n.","zh":"破裂；断裂（同出拉丁 rumpere，强调撕裂）"},{"word":"interrupt","pos":"v.","zh":"打断；中断（inter- 加 rumpere，本义「在中间断开」）"},{"word":"corrupt","pos":"v.","zh":"腐蚀；使腐败（cor- 加 rumpere，本义「彻底破坏」）"},{"word":"abrupt","pos":"adj.","zh":"突然的；生硬的（ab- 加 rumpere，本义「被折断」）"}],"senses":[{"no":"01","title":"A volcano bursts open","titleCN":"火山喷发","definition":"to send out lava, ash and gas suddenly and violently from a volcano","definitionCN":"火山突然而猛烈地喷出熔岩、火山灰与气体","example":"Mount Etna erupted again last night, closing the airport.","exampleCN":"埃特纳火山昨夜再次喷发，导致机场关闭。","why":"erupt comes from Latin erumpere, to break out, from e- out plus rumpere to burst; a volcano literally breaks through its own sealed throat.","whyCN":"erupt 来自拉丁 erumpere「冲出」，由 e-「出」加 rumpere「破裂」构成；火山正是冲破自己封闭的通道。"},{"no":"02","title":"Anger or laughter bursts out","titleCN":"怒气或笑声爆发","definition":"to express a strong feeling suddenly and with force, especially anger or laughter","definitionCN":"猛然有力地表达强烈情绪，尤指愤怒或大笑","example":"The crowd erupted in laughter at the mimic's first line.","exampleCN":"模仿者一开口，人群就爆发出笑声。","why":"the same break-out image moves from rock to feeling: something held under pressure finally leaves the body.","whyCN":"同一个「冲破」意象从岩石移到情绪：被压住的东西终于冲出体外。"},{"no":"03","title":"A rash appears suddenly","titleCN":"皮疹突然发出","definition":"to appear suddenly on the skin as a rash or spots","definitionCN":"以皮疹或斑点的形式突然出现在皮肤表面","example":"A red rash erupted across his arms after the hike.","exampleCN":"徒步之后，他双臂突然起了一片红疹。","why":"medicine borrowed the volcano image: the skin surface is where hidden irritation breaks out.","whyCN":"医学借用了火山的意象：皮肤表面正是隐藏的刺激「冲破」出来的地方。"},{"no":"04","title":"A tooth breaks through the gum","titleCN":"牙齿萌出","definition":"of a tooth, to push through the gum and become visible","definitionCN":"指牙齿顶破牙龈、露出表面","example":"Her first molar erupted without any trouble.","exampleCN":"她的第一颗臼齿顺利萌出，没有不适。","why":"a tooth literally breaks out of the gum, so the Latin sense of bursting through fits exactly.","whyCN":"牙齿确实从牙龈里「破出」，拉丁语「冲破而出」的本义完全吻合。"},{"no":"05","title":"Violence or conflict breaks out","titleCN":"暴力或冲突突然爆发","definition":"to start suddenly and violently, of fighting, protest or conflict","definitionCN":"指打斗、抗议或冲突突然而猛烈地开始","example":"Protests erupted in several cities after the announcement.","exampleCN":"声明发布后，数个城市突然爆发抗议。","why":"a conflict that erupts appears without warning, like a vent opening in ground thought to be quiet.","whyCN":"爆发的冲突毫无预兆地出现，就像看似平静的地面忽然裂开一个喷口。"},{"no":"06","title":"A geyser shoots up","titleCN":"间歇泉喷发","definition":"of a geyser or hot spring, to send a column of water and steam into the air","definitionCN":"指间歇泉或温泉把水柱与蒸汽喷向空中","example":"The geyser erupts every ninety minutes or so.","exampleCN":"这处间歇泉大约每九十分钟喷发一次。","why":"hot water under pressure behaves like magma: it waits, then breaks out through a narrow channel.","whyCN":"受压的热水和岩浆一样：先积蓄，再从狭窄通道冲破而出。"},{"no":"07","title":"A sound or applause breaks out","titleCN":"声音或掌声骤然响起","definition":"of a sound, cheer or applause, to begin suddenly and loudly","definitionCN":"指声音、欢呼或掌声突然而响亮地开始","example":"Applause erupted the moment the curtain fell.","exampleCN":"幕布落下的瞬间，掌声骤然响起。","why":"sound also has a moment of breaking through silence, and the verb marks that sudden start.","whyCN":"声音也有「冲破寂静」的一刻，这个动词标记的正是那突然的起点。"},{"no":"08","title":"Liquid or gas spurts out","titleCN":"液体或气体喷出","definition":"of liquid, gas or steam, to come out forcefully through a narrow opening","definitionCN":"指液体、气体或蒸汽从狭窄开口有力地喷出","example":"Steam erupted from a crack in the pipe.","exampleCN":"蒸汽从管道的裂缝中喷出。","why":"the physical core remains: a substance under pressure finds a small opening and leaves it fast.","whyCN":"物理核心仍在：受压的物质找到一个小开口，迅速冲出去。"}],"etymology":{"intro":{"en":"Erupt comes from Latin eruptus, the past participle of erumpere, to break out, built from e- (out) and rumpere (to break). English borrowed it in the seventeenth century; the volcano sense came first, and the emotional, medical and acoustic senses followed.","cn":"erupt 来自拉丁 eruptus，即 erumpere「冲出、破出」的过去分词，由 e-「出」与 rumpere「破」构成。英语于十七世纪借入，最早用于火山喷发，情绪义、医学义与听觉义随后扩展。"},"items":[{"era":"LATIN RUMPERE","en":"Rumpere meant to break, burst or tear apart. Its past participle ruptum gives the stem rupt- seen in rupture, interrupt, corrupt, abrupt and bankrupt.","cn":"rumpere 意为「打破、爆裂、撕裂」。其过去分词 ruptum 提供 rupture（破裂）、interrupt（打断）、corrupt（腐蚀）、abrupt（突然的）、bankrupt（破产的）中所见的 rupt- 词干。"},{"era":"LATIN E- (EX-)","en":"The prefix e-, shortened from ex-, meant out of or forth; joined to rumpere it produced erumpere, to break out.","cn":"前缀 e- 是 ex- 的缩略，意为「向外、出来」；与 rumpere 结合构成 erumpere「破出」。"},{"era":"LATIN ERUMPERE","en":"Erumpere was used for soldiers bursting from a gate, for water breaking from a pipe, and for a buried force escaping its container.","cn":"erumpere 曾用于士兵冲出城门、水冲破管道，以及被压住的力量脱离容器而出。"},{"era":"LATIN ERUPTUS AND ERUPTIO","en":"The participle eruptus described what had burst out; the noun eruptio named the bursting forth and gives English eruption.","cn":"分词 eruptus 描述已经冲出的东西；名词 eruptio 指「冲出」这一事件，衍生英语 eruption（喷发）。"},{"era":"ENGLISH ERUPT","en":"English took the verb in the seventeenth century. Early examples describe volcanoes and wounds; the sense of a sudden outbreak of feeling is later.","cn":"英语在十七世纪借入这个动词。早期例子描述火山与创口；情绪突然爆发的义项出现较晚。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates only): the Latin forms themselves are recorded and the root is not in doubt, but the exact first date of each English sense is only approximate, with the emotional sense arriving later. Rupture keeps the plain sense of tearing, so it is a cousin in root rather than a synonym.","cn":"来源不确定（仅首见年代）：拉丁形式本身有记录，词根无争议；但各英语义项的确切首见年代只能给约数，其中情绪爆发义出现较晚。rupture 保留「撕裂」本义，因此只是同根近亲，并非同义词。"}]},"similar":{"note":{"en":"Group one shares the Latin stem rupt-; group two holds verbs of sudden outward release.","cn":"第一组共享拉丁词干 rupt-；第二组是表示突然向外释放的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"abrupt","ipa":"/əˈbrʌpt/","tag":"same root, cut off short","definition":"From ab- (away) plus rumpere: literally broken off, hence sudden or brusque, with no preparation.","definitionCN":"由 ab-「离开」加 rumpere 构成：本义「被折断」，因此表示突然、生硬、毫无铺垫。"},{"word":"rupture","ipa":"/ˈrʌptʃə/","tag":"same root, tear","definition":"A tearing or bursting of something under strain, such as a pipe, a tendon or a treaty; it stresses the tear itself.","definitionCN":"受力之物撕裂或爆开，如管道、肌腱或条约；强调撕裂本身。"},{"word":"interrupt","ipa":"/ˌɪntəˈrʌpt/","tag":"same root, break between","definition":"From inter- (between) plus rumpere: to break into something between its parts, hence to cut a conversation short.","definitionCN":"由 inter-「之间」加 rumpere：在部分之间插入断开，因此指打断谈话。"},{"word":"corrupt","ipa":"/kəˈrʌpt/","tag":"same root, thoroughly broken","definition":"From com- (thoroughly) plus rumpere: morally broken through, hence dishonest or decayed.","definitionCN":"由 com-「彻底」加 rumpere：道德上被彻底折断，因此指腐败、败坏的。"},{"word":"bankrupt","ipa":"/ˈbæŋkrʌpt/","tag":"same root, broken bench","definition":"From Italian banca rotta, a broken bench: a merchant's table smashed, hence unable to pay debts.","definitionCN":"来自意大利语 banca rotta「折断的凳子」：商人的摊桌被砸，因此指无力偿债、破产的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"explode","ipa":"/ɪkˈspləʊd/","tag":"burst with a bang","definition":"To blow up with a report, from a chemical or nuclear reaction; erupt stresses emergence through an opening rather than a bang.","definitionCN":"因化学反应或核反应而伴巨响炸开；erupt 强调从开口冲出，而非一声爆响。"},{"word":"burst","ipa":"/bɜːst/","tag":"plain everyday word","definition":"The general English verb for breaking open from inside; erupt is its geological and dramatic counterpart.","definitionCN":"表示由内向外破开的日常动词；erupt 是其地质与戏剧化的对应词。"},{"word":"spew","ipa":"/spjuː/","tag":"throw out matter","definition":"To send out large amounts of something, often violently and messily; it fits the lava and gas sense closely.","definitionCN":"大量、常常猛烈而杂乱地喷出某物；与熔岩与气体的义项很贴合。"},{"word":"vent","ipa":"/vent/","tag":"release through an opening","definition":"To release pressure or feeling through an outlet; the focus is on the opening and the relief, not the burst.","definitionCN":"通过一个出口释放压力或情绪；重点在出口与缓解，而非爆开。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"e- means out and rupt- means broken: erupt is the broken-out event.","cn":"e- 是「出」，rupt- 是「破」：erupt 就是「破出」这一事件。"},{"en":"The rupt- family is large: eruption, eruptive, rupture, interrupt, corrupt, abrupt, bankrupt.","cn":"rupt- 家族很大：eruption（喷发）、eruptive（喷发性的）、rupture（破裂）、interrupt（打断）、corrupt（腐蚀）、abrupt（突然的）、bankrupt（破产的）。"},{"en":"Volcano phrases fix the first sense: a volcano erupts, lava erupts, ash erupts from the vent.","cn":"火山搭配固定第一义：火山喷发、熔岩喷出、火山灰从喷口喷出。"},{"en":"Body phrases fix the medical sense: a rash erupts, a tooth erupts, spots erupt on the skin.","cn":"身体搭配固定医学义：皮疹发出、牙齿萌出、皮肤上冒出斑点。"},{"en":"Emotion phrases take a phrase of manner: erupt in laughter, erupt with anger, erupt into violence.","cn":"情绪搭配后面常接表示方式的短语：爆发出笑声、勃然大怒、突然演变为暴力。"}],"abstract":[{"en":"Picture a sealed kettle whose lid lifts without warning.","cn":"想象一只密封的水壶，盖子毫无预兆地被顶开。"},{"en":"Picture a quiet classroom where one laugh sets off the whole room.","cn":"想象安静的教室里，一声笑把整间屋子点燃。"},{"en":"Picture a pinhole in a hot pipe and a white jet cutting the air.","cn":"想象热管道上的一个针孔，白色气流割开空气。"}]},"examples":[{"en":"The volcano erupted for the first time in a century, forcing nearby villages to evacuate.","cn":"这座火山一世纪以来首次喷发，附近村庄被迫撤离。"},{"en":"She erupted in anger when the results were announced.","cn":"结果公布时，她勃然大怒。"},{"en":"A rash erupted on his back after he touched the plant.","cn":"他碰过那株植物后，背上突然起了一片疹子。"}],"dict_mnemonic":{"note":"构词记忆 · 非词源","text":"「e（出）加 rupt（破）」——地底的压力破壳而出 → 喷发、爆发、突然冒出","word":"erupt"},"root":"拉丁 rumpere「破裂」加前缀 e-「出」构成 erumpere「冲破而出」，其过去分词 eruptus 直接进入英语作 erupt；名词为同源的 eruptio（喷发）。同族含 rupture（破裂）、interrupt（打断）、corrupt（腐蚀）、abrupt（突然的）。","sensesIntro":{"en":"Eight senses all record the same instant: something sealed gives way and its contents leave fast. The first and sixth are geological, the second, fifth and seventh put the burst in feeling, streets and sound, the third and fourth place it on the body, and the eighth keeps the plain physical jet.","cn":"八个义项记录的都是同一个瞬间：封闭之物让开，里面的东西迅速冲出。第一与第六义属地质，第二、第五与第七义把爆发放在情绪、街巷与声音里，第三与第四义落在身体上，第八义保留最朴素的物理喷射。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sealed chamber under pressure whose wall finally gives way.","cn":"核心意象：一个受压的封闭腔体，壁面终于让开。"},"chain":["PRESSURE BUILDS","SEAL BREAKS","MATTER LEAVES FAST","FEELING LEAVES FAST","SURFACE SIGN APPEARS","CONFLICT OR SOUND STARTS"],"branches":[{"senses":"S1 · S6","en":"GEOLOGICAL VENT: a volcano and a geyser both wait under pressure, then open a channel.","cn":"地质喷口：火山与间歇泉都先受压等待，再打开通道。"},{"senses":"S2 · S5","en":"FEELING AND CONFLICT: anger, laughter and street fighting all leave the body or the crowd at once.","cn":"情绪与冲突：怒气、笑声与街头打斗都一下子离开身体或人群。"},{"senses":"S3 · S4","en":"BODY SURFACE: a rash and a tooth both become visible by breaking through a covering.","cn":"身体表面：皮疹与牙齿都靠冲破一层覆盖物才被看见。"},{"senses":"S7","en":"SOUND: applause breaks the silence exactly as lava breaks the crust.","cn":"声音：掌声打破寂静，正如熔岩冲破地壳。"},{"senses":"S8","en":"MATTER UNDER PRESSURE: gas and liquid find a narrow crack and leave it at speed.","cn":"受压物质：气体与液体找到狭窄裂缝，高速离去。"}]},"affixes":{"intro":{"en":"Erupt is a Latin compound verb: a prefix of direction plus a verb of breaking, with the participle supplying the English form.","cn":"erupt 是一个拉丁复合动词：方向前缀加「破」动词，英语形式取自其过去分词。"},"latinIntro":{"en":"Latin rumpere, erumpere, eruptus and eruptio supply erupt, eruption and the wider rupt- family.","cn":"拉丁 rumpere、erumpere、eruptus 与 eruptio 衍生 erupt、eruption（喷发）以及整个 rupt- 词族。"},"items":[{"word":"e-","structure":"e- (Latin prefix, shortened from ex-, 'out, forth')","meaning":"out; forth","meaningCN":"向外；出来","example":"The prefix e- marks movement out of a container.","exampleCN":"前缀 e- 标记「离开容器向外」的运动。"},{"word":"rupt-","structure":"ruptus (Latin participle stem of rumpere, 'broken')","meaning":"broken; burst","meaningCN":"破裂的；爆开的","example":"Every word in the rupt- family carries a break.","exampleCN":"rupt- 词族的每个词都带着一个「破」义。"},{"word":"erupt","structure":"e- + rumpere, participle eruptus","meaning":"to break out; to burst forth","meaningCN":"喷发；爆发；突然出现","example":"The vent began to erupt at dawn.","exampleCN":"喷口在黎明时开始喷发。"},{"word":"eruption","structure":"eruptio (Latin noun of action, from eruptus)","meaning":"a bursting forth","meaningCN":"喷发；爆发；皮疹","example":"The eruption covered the slope in ash.","exampleCN":"这次喷发把山坡覆满火山灰。"},{"word":"eruptive","structure":"erupt + -ive (adjective suffix of tendency)","meaning":"tending to burst out","meaningCN":"喷发性的；突发的","example":"The eruptive phase lasted three weeks.","exampleCN":"喷发阶段持续了三周。"},{"word":"rupture","structure":"ruptus + -ura (Latin noun of result)","meaning":"a tearing; a break","meaningCN":"破裂；断裂","example":"The pipe suffered a rupture at the joint.","exampleCN":"管道在接头处发生破裂。"},{"word":"interrupt","structure":"inter- (between) + rumpere (break)","meaning":"to break in between","meaningCN":"打断；中断","example":"Do not interrupt the speaker.","exampleCN":"不要打断发言者。"},{"word":"corrupt","structure":"cor- (thoroughly) + rumpere (break)","meaning":"to break through morally; to decay","meaningCN":"腐蚀；使腐败","example":"The officials were corrupted by easy money.","exampleCN":"官员们被轻易到手的钱腐蚀了。"},{"word":"abrupt","structure":"ab- (away) + rumpere (break)","meaning":"broken off short; sudden","meaningCN":"突然的；生硬的","example":"The road ends in an abrupt turn.","exampleCN":"这条路以一个突然的转弯结束。"},{"word":"bankrupt","structure":"banca rotta (Italian, 'broken bench')","meaning":"unable to pay debts","meaningCN":"破产的","example":"The firm went bankrupt within a year.","exampleCN":"这家公司在一年内破产。"}],"latinEntries":[{"word":"rumpere","structure":"rumpere, rupi, ruptum (verb, third conjugation)","meaning":"to break, burst, tear","meaningCN":"打破；爆裂；撕裂"},{"word":"erumpere","structure":"e- + rumpere (compound verb)","meaning":"to break out, burst forth","meaningCN":"冲出；破出"},{"word":"eruptus","structure":"eruptus, -a, -um (perfect passive participle of erumpere)","meaning":"having burst out","meaningCN":"已经冲出的"},{"word":"eruptio","structure":"eruptio, eruptionis (f., third declension)","meaning":"a bursting forth","meaningCN":"冲出；喷发"}]}},{"word":"magma","ipa_uk":"/ˈmæɡmə/","ipa_us":"/ˈmæɡmə/","definition_zh":"岩浆；地下熔融岩石；岩浆房；岩浆类型（玄武质、花岗质）；行星岩浆洋；泛指熔融物质；比喻压抑的强烈情绪或力量","definition_en":"molten rock stored beneath the surface of a planet, which may cool to form igneous rock or reach the surface as lava","core_image":"地表之下极深处，一汪橙红的黏稠熔体在岩壁间缓慢翻滚，被上方厚重的岩层死死压住","scene":"钻探船的甲板上，仪器显示地下深处有一层缓慢流动的高温熔体，压力正在上升。 Scientists drill into the ocean floor to sample the magma before it reaches the surface.","sceneCN":"这里 magma 指仍在地下的熔融岩石（第 1 个义项：位于地表之下、尚未喷出的熔融态岩石）；句意为科学家钻入海底，在岩浆到达地表之前取样。","pos":[{"tag":"n.","zh":"岩浆；地下熔融岩石"},{"tag":"n.","zh":"岩浆体（如岩浆房、岩浆洋）"},{"tag":"n.","zh":"泛指熔融物质；比喻压抑的强烈情绪或力量"}],"collocations":[{"phrase":"magma chamber","zh":"岩浆房"},{"phrase":"magma ocean","zh":"岩浆洋"},{"phrase":"magma mixing","zh":"岩浆混合"},{"phrase":"basaltic magma","zh":"玄武质岩浆"},{"phrase":"granitic magma","zh":"花岗质岩浆"},{"phrase":"parental magma","zh":"母岩浆"},{"phrase":"molten magma","zh":"熔融岩浆"}],"forms":[{"label":"名词复数","form":"magmas"},{"label":"名词复数（拉丁式，少见）","form":"magmata"},{"label":"形容词（岩浆的）","form":"magmatic"},{"label":"名词（岩浆活动）","form":"magmatism"}],"derivatives":[{"word":"magmatic","pos":"adj.","zh":"岩浆的；与岩浆作用有关的"},{"word":"magmatism","pos":"n.","zh":"岩浆活动；岩浆作用"},{"word":"magmatology","pos":"n.","zh":"岩浆学（较少见的学科名称）"},{"word":"magma chamber","pos":"n.","zh":"岩浆房（复合术语，指储存岩浆的地下腔体）"},{"word":"magma ocean","pos":"n.","zh":"岩浆洋（复合术语，指行星早期的全球性熔融层）"}],"senses":[{"no":"01","title":"Molten rock underground","titleCN":"地下的熔融岩石","definition":"molten or partly molten rock stored beneath the surface of a planet","definitionCN":"储存于行星地表之下、呈熔融或半熔融状态的岩石","example":"The magma rose slowly through a network of cracks.","exampleCN":"岩浆沿着裂隙网络缓慢上升。","why":"Greek magma meant a kneaded mass; geologists applied it to rock softened by heat into a paste-like body.","whyCN":"希腊 magma 意为「揉成的团块」；地质学家用它指被热软化成糊状团块的岩石。"},{"no":"02","title":"A chamber that stores magma","titleCN":"岩浆房","definition":"a large body of magma held within the crust, often feeding a volcano","definitionCN":"地壳中储存大量岩浆的腔体，常为火山提供补给","example":"Seismic surveys revealed a magma chamber three kilometres below the summit.","exampleCN":"地震勘测显示峰顶下方三公里处有一个岩浆房。","why":"the mass had to be located somewhere, so the container sense grew out of the material sense.","whyCN":"这团熔体总得存在于某处，于是「容器」义从「材料」义中生长出来。"},{"no":"03","title":"Magma typed by composition","titleCN":"按成分划分的岩浆类型","definition":"a melt described by its chemical composition, such as basaltic or granitic magma","definitionCN":"按化学成分描述的熔体，如玄武质岩浆或花岗质岩浆","example":"Basaltic magma is hotter and runnier than granitic melt.","exampleCN":"玄武质岩浆比花岗质熔体更热、更稀。","why":"composition decides how a melt behaves, so the word came to name varieties rather than one substance.","whyCN":"成分决定熔体的行为，因此这个词开始指称不同品种，而非单一物质。"},{"no":"04","title":"Any molten material","titleCN":"泛指熔融物质","definition":"a general term for a hot melt, including molten metal, glass or ice","definitionCN":"对高温熔体的泛称，包括熔融金属、玻璃或冰","example":"The furnace stirred a magma of molten glass and ash.","exampleCN":"炉中翻搅着一团熔融玻璃与灰的混合物。","why":"the paste image is broad enough to cover industrial and planetary melts that are not rock.","whyCN":"「糊状团块」的意象足够宽，可覆盖并非岩石的工业熔体与行星熔体。"},{"no":"05","title":"A planet-wide magma ocean","titleCN":"行星岩浆洋","definition":"a global layer of molten rock on a young planet or moon","definitionCN":"年轻行星或卫星上全球性的熔融岩石层","example":"The early Moon probably had a magma ocean hundreds of kilometres deep.","exampleCN":"早期的月球可能有一层深达数百公里的岩浆洋。","why":"planetary science extended the underground body to the whole surface of a young world.","whyCN":"行星科学把地下的熔体扩展到年轻天体的整个表面。"},{"no":"06","title":"Mixing of two magmas","titleCN":"岩浆混合","definition":"the process in which two different magmas meet and blend, often before an eruption","definitionCN":"两种不同岩浆相遇并混合的过程，常发生在喷发之前","example":"Textures in the lava record magma mixing just before the blast.","exampleCN":"熔岩中的结构记录了爆发前一刻的岩浆混合。","why":"the word works as an attributive noun here, so the compound can name a process between two bodies of melt.","whyCN":"在这个复合术语中该词作定语名词，因此整个复合词能指两团熔体之间的过程。"},{"no":"07","title":"The parent magma","titleCN":"母岩浆","definition":"the original melt from which a series of related rocks or melts are derived","definitionCN":"一系列相关岩石或熔体所由衍生的原始熔体","example":"Geochemists traced all the samples back to one parental magma.","exampleCN":"地球化学家把全部样品追溯至同一个母岩浆。","why":"the word works as a family term, with melts descending from a common source as children from a parent.","whyCN":"该词被当作家族术语：各熔体如同子女，源自同一个母体。"},{"no":"08","title":"Suppressed fury like magma","titleCN":"如岩浆般压抑的怒气","definition":"a figurative use for strong feeling or power that is held down and may break out","definitionCN":"比喻被压住、可能冲破而出的强烈情绪或力量","example":"Resentment had been gathering like magma beneath the quiet office.","exampleCN":"怨气像岩浆一样在那间安静的办公室里积攒。","why":"magma is invisible and dangerous precisely because it is still under the crust, which makes it a natural image for held-in anger.","whyCN":"岩浆之所以危险，正因为它仍在壳下、看不见，这使它成为压抑怒气的天然意象。"}],"etymology":{"intro":{"en":"Magma comes from Greek magma, a kneaded mass, from massein, to knead. Latin used magma only as a Greek loanword, so there is no native Latin family behind it. Geology adopted the term in the nineteenth century for molten rock still underground, specifically to contrast with lava at the surface.","cn":"magma 一般认为源自希腊 magma「揉成的团块」，出自动词 massein「揉、捏」，但更早的前希腊词根并不确定。拉丁语中的 magma 只是希腊借词，背后没有本土拉丁词族。地质学在十九世纪采用该词指仍在地下的熔融岩石，特意与已到地表的 lava 相对。"},"items":[{"era":"GREEK MASSEIN","en":"Massein meant to knead, press or work a soft substance with the hands.","cn":"massein 意为「揉、压」，用手把柔软之物反复捏合。"},{"era":"GREEK MAGMA","en":"Magma was the result: a kneaded mass, and in medical Greek a thick ointment or paste.","cn":"magma 是结果：揉成的一团；在希腊医学中还指浓稠的药膏或糊剂。"},{"era":"LATIN BORROWING ONLY","en":"Latin texts used magma as an unassimilated Greek word. It has no Latin verb or noun relatives, which is why this entry leaves the Latin list empty.","cn":"拉丁文献把 magma 当作未同化的希腊词使用。它没有拉丁动词或名词同族，因此本词条的拉丁词表留空。"},{"era":"GEOLOGICAL ENGLISH","en":"Nineteenth-century geology needed a word for melt that had not yet reached the surface; magma filled that gap.","cn":"十九世纪的地质学需要一个词指尚未到达地表的熔体，magma 正好补上这个空位。"},{"era":"MODERN EXTENSIONS","en":"The word now covers magma chambers, magma oceans, magma mixing and parental magma, and is also used figuratively.","cn":"这个词如今覆盖岩浆房、岩浆洋、岩浆混合与母岩浆，也被用于比喻。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root in doubt): the Greek origin is generally accepted, from magma, a kneaded mass, and massein, to knead; but the deeper pre-Greek root of massein is unsettled, any older form offered for it is a reconstruction, and the exact date of the geological sense is approximate.","cn":"来源不确定（词根存疑）：一般认为是希腊 magma「揉成的团块」，出自 massein「揉、捏」，这一路径获较广泛接受；但 massein 更早的前希腊词根并无定论，凡给出的更深形式均属重构形式，地质义的确切首见年代亦为约数。"}]},"similar":{"note":{"en":"Group one holds forms built on the same word; group two holds the terms most often confused with magma.","cn":"第一组是由同一个词构成的形式；第二组是最容易与岩浆混淆的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"magmatic","ipa":"/mæɡˈmætɪk/","tag":"adjective of magma","definition":"Relating to magma or to the processes that involve it, as in magmatic water or magmatic differentiation.","definitionCN":"与岩浆或岩浆参与的过程有关，如岩浆水、岩浆分异。"},{"word":"magmatism","ipa":"/ˈmæɡmətɪzəm/","tag":"noun, activity","definition":"The total activity of magma within a region, including its generation, movement and solidification.","definitionCN":"一个区域内岩浆活动的总和，包括生成、运移与固结。"},{"word":"magmata","ipa":"/mæɡˈmɑːtə/","tag":"rare Latin-style plural","definition":"An uncommon plural modelled on Greek and Latin neuter plurals; magmas is the usual form.","definitionCN":"模仿希腊语与拉丁语中性复数构成的少见复数；常用复数仍是 magmas。"},{"word":"magma chamber","ipa":"/ˈmæɡmə ˈtʃeɪmbə/","tag":"compound term","definition":"The underground reservoir that holds magma; the phrase names the container, not the melt.","definitionCN":"储存岩浆的地下储库；这个短语指容器，而非熔体本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"lava","ipa":"/ˈlɑːvə/","tag":"melt at the surface","definition":"The same molten rock once it has reached the surface; magma is the underground stage, lava the exposed stage.","definitionCN":"同一种熔融岩石到达地表之后的名称；magma 是地下阶段，lava 是露出地表的阶段。"},{"word":"molten rock","ipa":"/ˈməʊltən rɒk/","tag":"descriptive phrase","definition":"A plain description of rock heated until liquid; magma is the technical term for it underground.","definitionCN":"对加热至液态的岩石的平实描述；magma 是它在地下时的术语。"},{"word":"melt","ipa":"/melt/","tag":"geological noun","definition":"In petrology, a synonym for liquid rock or the liquid portion of a partly molten system.","definitionCN":"在岩石学中指液态岩石，或部分熔融体系中的液相部分。"},{"word":"igneous","ipa":"/ˈɪɡniəs/","tag":"rock class, not the melt","definition":"Describing rock formed from cooled magma or lava; it names the product, not the molten stage.","definitionCN":"描述由冷却的岩浆或熔岩形成的岩石；指产物，而非熔融阶段。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek morphology, real collocations and the real magma-lava boundary.","cn":"正常联想：真实的希腊构词、真实搭配，以及真实存在的岩浆与熔岩分界。"},"normal":[{"en":"Greek massein means to knead: magma is rock softened and worked into a glowing paste.","cn":"希腊 massein 意为「揉」：岩浆就是被揉软、揉成一团的灼热糊状岩石。"},{"en":"Magma stays below, lava comes out: one word for the hidden stage, one for the exposed stage.","cn":"岩浆留在地下，熔岩流到地表：一个词指隐藏阶段，一个词指露出阶段。"},{"en":"Compound terms come in a series: magma chamber, magma ocean, magma mixing, parental magma.","cn":"复合术语成串出现：岩浆房、岩浆洋、岩浆混合、母岩浆。"},{"en":"Composition splits it into basaltic magma and granitic magma, the first hotter and runnier.","cn":"按成分可分为玄武质岩浆与花岗质岩浆，前者更热、更稀。"},{"en":"The figurative use keeps the position: anger sits under the surface like magma under crust.","cn":"比喻用法保留了位置：怒气伏在表面之下，如同壳下的岩浆。"}],"abstract":[{"en":"Picture dough being folded and pressed in a bowl until it becomes one soft mass.","cn":"想象面团在盆里被反复折叠按压，最后成了一团柔软的整体。"},{"en":"Picture a thick soup held down by a lid, steam bubbling only at the rim.","cn":"想象一锅浓汤被盖子压住，热气只在边缘冒出细泡。"},{"en":"Picture a hidden underground river that makes the ground above slightly warm.","cn":"想象地下有一条看不见的暗河，让上方的地面微微发烫。"}]},"examples":[{"en":"The magma cooled slowly at depth, forming coarse crystals.","cn":"岩浆在深处缓慢冷却，形成粗大的晶体。"},{"en":"A magma chamber beneath the caldera was detected by seismic waves.","cn":"地震波探测到破火山口下方有一个岩浆房。"},{"en":"Her anger sat like magma, unseen until the day it broke through.","cn":"她的怒气像岩浆一样伏着，直到爆发那天才被看见。"}],"dict_mnemonic":{"note":"联想记忆 · 非词源","text":"希腊语「揉成的团」——地热把岩石揉软，还压在地壳里 → 岩浆","word":"magma"},"root":"希腊 magma「揉成的团块」，出自 massein「揉、捏」；拉丁语仅作希腊借词使用，无本土同族；地质学借指地下熔融岩石，与地表的 lava（熔岩）分工。","sensesIntro":{"en":"Eight senses follow one hidden body: a kneaded melt that sits under rock. The material sense comes first, then its container, its composition, the wider class of melts, planetary and process uses, a source term, and finally the figurative pressure it suggests.","cn":"八个义项围绕同一个隐藏的物体：一团伏在岩石之下的熔体。先讲物质本身，再讲容器、成分、更宽的熔体类别、行星与过程用法、源熔体，最后落在它暗示的压抑之势。"},"semanticMap":{"core":{"en":"CORE IMAGE: a kneaded, glowing paste trapped under a lid of rock.","cn":"核心意象：一团被岩石盖子压住的灼热糊状物。"},"chain":["KNEADED MASS","TRAPPED UNDER ROCK","STORED IN A CHAMBER","TYPED BY COMPOSITION","PLANETARY MELT","PRESSURE HELD DOWN"],"branches":[{"senses":"S1 · S2","en":"MATERIAL AND CONTAINER: the melt itself, and the cavity that holds it.","cn":"物质与容器：熔体本身，以及容纳它的腔体。"},{"senses":"S3 · S7","en":"COMPOSITION AND SOURCE: chemistry sorts the melt into types, and one type can be the parent of a rock series.","cn":"成分与来源：化学把熔体分成类型，而某一类型可以成为一套岩石系列的母体。"},{"senses":"S4 · S5","en":"BEYOND ROCK: the same paste image covers industrial melts and a planet-wide molten layer.","cn":"越出岩石：同一个糊状意象覆盖工业熔体与全球性的熔融层。"},{"senses":"S6","en":"PROCESS BETWEEN BODIES: two melts can meet and blend before an eruption.","cn":"两团之间的过程：两股熔体可以在喷发前相遇并混合。"},{"senses":"S8","en":"FIGURATIVE PRESSURE: what is held under the crust becomes the image of held-in fury.","cn":"比喻压力：压在壳下之物，成为被压抑怒气的意象。"}]},"affixes":{"intro":{"en":"Magma is not built from Latin prefixes and suffixes; it is a whole Greek noun borrowed intact, so these items are stems and compounds rather than derivational endings.","cn":"magma 不是由拉丁前缀与后缀构成的，而是整体借入的希腊名词；因此下列条目是词干与复合形式，而非派生词尾。"},"latinIntro":{"en":"Latin contributes no native relatives: magma appears only as a Greek loanword, and the geological vocabulary is built by compounding with English and Latin elements.","cn":"拉丁语没有提供本土同族词：magma 只作为希腊借词出现，地质词汇靠英语与拉丁成分复合构成。"},"items":[{"word":"magma-","structure":"Greek magma (stem magmat-), 'kneaded mass'","meaning":"kneaded mass; melt","meaningCN":"揉成的团块；熔体","example":"The stem magma- appears unchanged in English.","exampleCN":"词干 magma- 在英语中保持原形。"},{"word":"-ic","structure":"-ikos (Greek adjective suffix, through Latin -icus)","meaning":"relating to","meaningCN":"与……有关的","example":"Magmatic describes anything that belongs to magma.","exampleCN":"magmatic 描述一切属于岩浆的事物。"},{"word":"-ism","structure":"-ismos (Greek noun suffix of activity or system)","meaning":"activity or system","meaningCN":"活动或体系","example":"Magmatism names the activity of magma in a region.","exampleCN":"magmatism 指一个区域内的岩浆活动。"},{"word":"-logy","structure":"-logia (Greek noun suffix, 'study of')","meaning":"the study of","meaningCN":"……学；对……的研究","example":"Magmatology is the study of magmas and their evolution.","exampleCN":"岩浆学是研究岩浆及其演化的学问。"},{"word":"magma chamber","structure":"magma + chamber (English compound)","meaning":"underground reservoir of melt","meaningCN":"地下储库","example":"The chamber fed the eruption for several weeks.","exampleCN":"这个岩浆房为喷发供给了数周。"},{"word":"magma ocean","structure":"magma + ocean","meaning":"a global molten layer","meaningCN":"全球性熔体层","example":"The magma ocean solidified from the top down.","exampleCN":"岩浆洋自上而下固结。"},{"word":"magma mixing","structure":"magma + mixing","meaning":"blending of two melts","meaningCN":"两种熔体的混合","example":"Magma mixing can trigger an eruption.","exampleCN":"岩浆混合可能触发喷发。"},{"word":"parental magma","structure":"parental + magma","meaning":"source melt of a rock series","meaningCN":"一套岩石系列的源熔体","example":"The parental magma was rich in magnesium.","exampleCN":"母岩浆富含镁。"},{"word":"magmatic differentiation","structure":"magmatic + differentiation","meaning":"change of melt composition by crystal separation","meaningCN":"熔体成分因晶体分离而改变","example":"Magmatic differentiation produces different rock types.","exampleCN":"岩浆分异产生不同的岩石类型。"},{"word":"basaltic magma","structure":"basaltic + magma","meaning":"magnesium-rich, runny melt","meaningCN":"富镁、流动性强的熔体","example":"Basaltic magma feeds quiet lava flows.","exampleCN":"玄武质岩浆供给平静的熔岩流。"}],"latinEntries":[]}},{"word":"lava","ipa_uk":"/ˈlɑːvə/","ipa_us":"/ˈlɑːvə/","definition_zh":"熔岩；熔岩流；熔岩冷却形成的岩石；熔岩穹丘；熔岩管；枕状熔岩；比喻大量涌出之物；熔岩灯","definition_en":"molten rock that has reached a planet's surface and flows from a volcano, or the solid rock it forms when it cools","core_image":"火山口边缘，暗红的黏稠流体沿斜坡推进，表面结出黑色硬壳，壳缝里透出橙色光","scene":"夜里的山坡上，暗红色流体一边移动一边结壳，缓慢逼近远处的房屋。 A river of lava cut across the road and reached the sea by dawn.","sceneCN":"这里 lava 指流出地表的熔岩（第 1 个义项：到达地表并正在流动的高温熔融岩石）；句意为一条熔岩流横穿公路，天亮时抵达海边。","pos":[{"tag":"n.","zh":"熔岩（到达地表的熔融岩石）"},{"tag":"n.","zh":"熔岩流；熔岩冷却形成的岩石"},{"tag":"n.","zh":"熔岩灯；（比喻）大量涌出之物"}],"collocations":[{"phrase":"lava flow","zh":"熔岩流"},{"phrase":"lava dome","zh":"熔岩穹丘"},{"phrase":"lava tube","zh":"熔岩管"},{"phrase":"pillow lava","zh":"枕状熔岩"},{"phrase":"molten lava","zh":"熔融的熔岩"},{"phrase":"basaltic lava","zh":"玄武质熔岩"},{"phrase":"lava lamp","zh":"熔岩灯"}],"forms":[{"label":"名词复数","form":"lavas"},{"label":"形容词（熔岩的，少见）","form":"lavic"},{"label":"复合名词（熔岩流）","form":"lava flow"},{"label":"复合名词（熔岩穹丘）","form":"lava dome"},{"label":"复合名词（熔岩灯）","form":"lava lamp"}],"derivatives":[{"word":"lavic","pos":"adj.","zh":"熔岩的；似熔岩的（较少见，地质学用）"},{"word":"lava-like","pos":"adj.","zh":"熔岩般的；像熔岩那样炽热流动的"},{"word":"lava flow","pos":"n.","zh":"熔岩流（复合术语，指流动的熔岩体及其堆积）"},{"word":"lava dome","pos":"n.","zh":"熔岩穹丘（复合术语，黏稠熔岩堆成的圆丘）"},{"word":"lava tube","pos":"n.","zh":"熔岩管（复合术语，熔岩流内部排空后留下的隧道）"}],"senses":[{"no":"01","title":"Molten rock at the surface","titleCN":"地表的熔融岩石","definition":"molten rock that has reached the surface through a vent","definitionCN":"通过火山口到达地表的熔融岩石","example":"Lava poured from a fissure on the flank of the cone.","exampleCN":"熔岩从锥体侧面的裂缝中涌出。","why":"lava names the melt only after it is exposed; while it is underground the same material is still magma.","whyCN":"lava 只在这团熔体露出地表之后才这么叫；它在地下时仍是 magma。"},{"no":"02","title":"A stream of lava","titleCN":"熔岩流","definition":"a flowing body of lava moving down a slope, or the deposit it leaves","definitionCN":"沿坡面流动的熔岩体，或它留下的堆积物","example":"The lava flow stopped two hundred metres from the village.","exampleCN":"熔岩流在离村庄两百米处停住。","why":"the moving stream became a countable thing, so the word can name one flow as well as the substance.","whyCN":"流动的熔岩被当作可数的个体，于是该词既能指物质，也能指一条熔岩流。"},{"no":"03","title":"The rock that lava becomes","titleCN":"熔岩冷却成的岩石","definition":"the solid igneous rock formed when a lava flow cools, commonly basalt","definitionCN":"熔岩流冷却后形成的坚硬火成岩，常见为玄武岩","example":"The cliff is made of lava that hardened under water.","exampleCN":"这道崖壁由在水下硬结的熔岩构成。","why":"once cooled, the material keeps the name of its molten stage, so the product inherits the word.","whyCN":"冷却之后，这种材料仍沿用熔融阶段的名称，于是产物继承了该词。"},{"no":"04","title":"A dome of thick lava","titleCN":"熔岩穹丘","definition":"a rounded mound built by viscous lava piling up around a vent","definitionCN":"黏稠熔岩在火山口周围堆叠而成的圆丘","example":"The lava dome grew by several metres each week.","exampleCN":"熔岩穹丘每周增高数米。","why":"stiff lava cannot run far, so it stacks into a dome, and the compound records that behaviour.","whyCN":"黏稠的熔岩流不远，只能堆成穹丘，这个复合词记录了这种行为。"},{"no":"05","title":"A tube left by a lava flow","titleCN":"熔岩管","definition":"a hollow tunnel formed when the surface of a lava flow crusts over while the molten interior drains away","definitionCN":"熔岩流表面结壳、内部熔体排空后留下的空心隧道","example":"The lava tube ran for six kilometres beneath the field.","exampleCN":"这条熔岩管从田野下方延伸六公里。","why":"the crust freezes first, the interior keeps moving, and the empty channel survives as a tube.","whyCN":"表层先凝固，内部继续流动，排空后的通道便作为管道留存。"},{"no":"06","title":"Pillow lava","titleCN":"枕状熔岩","definition":"bulbous, pillow-shaped masses of lava formed where lava is erupted under water","definitionCN":"熔岩在水下喷出时形成的球状、枕状团块","example":"Pillow lava on the sea floor showed the eruption had been submarine.","exampleCN":"海底的枕状熔岩表明这次喷发发生在水下。","why":"water chills the outside instantly, so each pulse of lava freezes as a rounded pillow.","whyCN":"水使外层瞬间冷却，于是每一股熔岩都冻成圆枕状。"},{"no":"07","title":"A flood of something","titleCN":"比喻大量涌出之物","definition":"a figurative use for something that pours out in great quantity, often hot or unstoppable","definitionCN":"比喻大量涌出之物，常带灼热或不可阻挡的意味","example":"Lava of complaints poured into the office after the launch.","exampleCN":"产品上线后，投诉如熔岩般涌进办公室。","why":"the image keeps heat and unstoppable flow, so the word suggests something that cannot be held back.","whyCN":"这个意象保留了高温与不可阻挡的流动，因此暗示无法被拦住的东西。"},{"no":"08","title":"The lava lamp","titleCN":"熔岩灯","definition":"a decorative lamp in which blobs of coloured wax rise and fall in heated liquid, named for their look","definitionCN":"一种装饰灯，加热液体中彩色蜡块升降起伏，因其外观而得名","example":"A lava lamp glowed on the shelf beside the old record player.","exampleCN":"旧唱机旁的架子上亮着一盏熔岩灯。","why":"the wax blobs mimic rising and sinking lava, so a cultural object borrowed the geological word.","whyCN":"蜡块升降的样子模仿熔岩，于是一件文化物件借用了这个地质词。"}],"etymology":{"intro":{"en":"Lava entered English from Italian, specifically the Neapolitan dialect, where lava meant a torrent or stream. Its deeper origin is disputed: one common hypothesis links it to Latin labes, a fall or slide, from labi, to slip; others suggest Latin lavare, to wash, or a local pre-Roman word. It is not a direct Latin inheritance, and no single origin is settled.","cn":"lava 经意大利语、具体是那不勒斯方言进入英语，方言中 lava 指急流或水流。其更深来源有争议：一种常见假说把它联系到拉丁 labes「坠落、滑落」，出自 labi「滑落」；也有人提出拉丁 lavare「洗」，或当地前罗马时期的词。它不是拉丁语的直接继承词，也没有定论。"},"items":[{"era":"NEAPOLITAN LAVA","en":"In the Naples dialect lava meant a torrent, especially a stream of rain water rushing down a slope.","cn":"在那不勒斯方言中，lava 指急流，尤指雨水沿坡冲下的水流。"},{"era":"LATIN LABES HYPOTHESIS","en":"One hypothesis derives the dialect word from Latin labes, a fall or sliding, from labi, to slip; the image of sliding material fits a lava flow, but the chain is unproven.","cn":"一种假说把方言词追溯到拉丁 labes「坠落、滑落」，出自 labi「滑落」；「滑落之物」的意象与熔岩流相合，但这条例证链未被证实。"},{"era":"ALTERNATIVE HYPOTHESES","en":"Other suggestions connect lava to Latin lavare, to wash, or to a pre-Roman local word; scholars have not agreed, so no single origin is asserted here.","cn":"其他说法把 lava 联系到拉丁 lavare「洗」，或联系到前罗马时期的当地词；学界未达成一致，因此此处不指定单一来源。"},{"era":"ENGLISH BORROWING","en":"English travellers and naturalists brought the word home in the eighteenth century, describing Vesuvius and Etna.","cn":"英语世界的旅行者与博物学家在十八世纪把这个词带回，用于描述维苏威火山与埃特纳火山。"},{"era":"GEOLOGICAL VOCABULARY","en":"Geology built a family of compounds: lava flow, lava dome, lava tube, pillow lava, each naming a shape the melt takes.","cn":"地质学构造了一族复合词：熔岩流、熔岩穹丘、熔岩管、枕状熔岩，各自指熔体的一种形态。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root in doubt): the Italian route is well documented, but the deeper origin is unsettled; it is generally thought to be related to Latin labes, a fall, while lavare, to wash, and a pre-Roman local word are competing hypotheses, so no single source is chosen; the first English date is approximate.","cn":"来源不确定（词根存疑）：意大利语这条路径有充分记录；但更深的来源未定，一般认为是与拉丁 labes「坠落」有关的假说，另有 lavare「洗」及前罗马时期当地词等说法并列，不选定论；英语首见的确切年代为约数。"}]},"similar":{"note":{"en":"Group one holds look-alike forms; group two holds the terms that overlap with lava in geology.","cn":"第一组是形近形式；第二组是在地质学中与熔岩重叠的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"larva","ipa":"/ˈlɑːvə/","tag":"one letter apart","definition":"The immature form of an insect or other animal; the spelling differs by a single letter and the meaning is unrelated.","definitionCN":"昆虫或其他动物的幼体；拼写只差一个字母，意义毫无关联。"},{"word":"lavic","ipa":"/ˈlɑːvɪk/","tag":"adjective of lava","definition":"A rare adjective meaning of or like lava, used mainly in geological writing.","definitionCN":"少见形容词，意为熔岩的或似熔岩的，主要用于地质写作。"},{"word":"lavas","ipa":"/ˈlɑːvəz/","tag":"regular plural","definition":"The regular plural, used when counting separate flows or types of melt.","definitionCN":"规则复数，用于计数不同的熔岩流或熔岩类型。"},{"word":"lava lamp","ipa":"/ˈlɑːvə læmp/","tag":"cultural compound","definition":"The decorative lamp whose wax blobs suggested the name, now the best-known non-geological use.","definitionCN":"那种蜡块让人联想到熔岩的装饰灯，如今是该词最知名的非地质用法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"magma","ipa":"/ˈmæɡmə/","tag":"melt underground","definition":"The same molten rock before it reaches the surface; the two words mark stages, not different substances.","definitionCN":"同一种熔融岩石在到达地表之前的名称；两词标记的是阶段，而非不同物质。"},{"word":"molten rock","ipa":"/ˈməʊltən rɒk/","tag":"descriptive phrase","definition":"A neutral description of rock heated to liquid, avoiding the technical stage terms.","definitionCN":"对加热成液态的岩石的中性描述，避开阶段术语。"},{"word":"basalt","ipa":"/ˈbæsɔːlt/","tag":"cooled lava rock","definition":"The dark, fine-grained rock most lava flows become; it names the product after cooling.","definitionCN":"多数熔岩流冷却后形成的深色细粒岩石；指冷却后的产物。"},{"word":"flow","ipa":"/fləʊ/","tag":"general movement word","definition":"Any moving mass of material; lava flow narrows it to molten rock and its deposit.","definitionCN":"任何流动的物质团；熔岩流把它收窄到熔融岩石及其堆积物。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Italian dialect source, the real magma boundary and the real compound series.","cn":"正常联想：真实存在的意大利方言来源、真实的岩浆分界，以及真实的复合词系列。"},"normal":[{"en":"The dialect word first meant a torrent running down a slope, then settled on the molten stream from a volcano.","cn":"这个方言词本指沿坡冲下的急流，后来固定指火山流出的熔融流体。"},{"en":"Underground it is magma, at the surface it is lava: one substance, two stages.","cn":"地下叫岩浆，地表叫熔岩：同一种物质，两个阶段。"},{"en":"The compounds line up by shape: lava flow, lava dome, lava tube, pillow lava.","cn":"复合词按形态排开：熔岩流、熔岩穹丘、熔岩管、枕状熔岩。"},{"en":"After cooling the material is still called lava, though it has become dark basalt.","cn":"冷却之后，这种材料仍叫熔岩，只是已成了深色玄武岩。"},{"en":"The lava lamp is the one everyday use: wax blobs rise and fall as if lava flowed inside the glass.","cn":"熔岩灯是唯一日常可见的用法：蜡块升降，仿佛玻璃里有熔岩在流。"}],"abstract":[{"en":"Picture honey falling from a spoon, thickening as it goes, a skin forming first.","cn":"想象蜂蜜从勺上缓慢垂落，越流越厚，表面先结一层皮。"},{"en":"Picture thick porridge tipped onto a table, still bubbling at the centre while the edge hardens.","cn":"想象一锅浓粥倒在桌上，中心还在冒泡，边缘已经硬了。"},{"en":"Picture a dark moving line at night whose colour can only be guessed.","cn":"想象夜里一条移动的暗线，颜色只能靠猜。"}]},"examples":[{"en":"Lava from the fissure flowed into the valley for three days.","cn":"裂缝中的熔岩流入山谷，持续了三天。"},{"en":"The lava had cooled into a dark, glassy crust.","cn":"熔岩冷却成一层深色、带玻璃光泽的硬壳。"},{"en":"Tourists queued to watch the wax blobs rise in the lava lamp.","cn":"游客排队观看熔岩灯里蜡块升起。"}],"dict_mnemonic":{"note":"联想记忆 · 非词源","text":"意大利方言「急流」——从火山口冲出的流动物 → 熔岩","word":"lava"},"root":"意大利语（那不勒斯方言）lava「急流」进入英语作 lava；更深来源未定，或与拉丁 labes「坠落、滑落」有关（仅属假说），亦有人提出拉丁 lavare「洗」；并非拉丁语直接继承词。","sensesIntro":{"en":"Eight senses follow the melt after it escapes: first the substance at the surface, then the stream it forms, the rock it becomes, three shapes cooling gives it, a figurative flood, and finally a cultural object named after the look.","cn":"八个义项跟踪熔体逃出地表之后的经历：先是在地表的物质，然后是它形成的流体、它变成的岩石、冷却赋予它的三种形态、比喻性的涌流，最后是以其外观命名的文化物件。"},"semanticMap":{"core":{"en":"CORE IMAGE: a glowing paste that has escaped its rock lid and now crawls over the ground.","cn":"核心意象：一团逃出岩石盖子的灼热糊状物，正在地面上爬行。"},"chain":["MELT REACHES SURFACE","STREAM CRAWLS DOWN","CRUST FORMS","SHAPES FREEZE","ROCK REMAINS","IMAGE LEAVES GEOLOGY"],"branches":[{"senses":"S1 · S2","en":"MATERIAL AND FLOW: the exposed melt and the moving body it makes.","cn":"物质与流动：露出地表的熔体，以及它形成的流动体。"},{"senses":"S3","en":"COOLED PRODUCT: the melt keeps its name after it hardens into dark rock.","cn":"冷却产物：熔体硬结成深色岩石后仍沿用原名。"},{"senses":"S4 · S5 · S6","en":"SHAPES OF FLOW: a dome, a tube and a pillow are three ways the same melt freezes in place.","cn":"流动的形态：穹丘、管道与枕状体，是同一熔体在原地冻住的三种方式。"},{"senses":"S7","en":"FIGURATIVE FLOOD: heat and unstoppable motion carry over to anything pouring out.","cn":"比喻涌流：高温与不可阻挡的运动被移用到一切大量涌出之物。"},{"senses":"S8","en":"CULTURAL OBJECT: a lamp borrows the look of rising and sinking melt.","cn":"文化物件：一盏灯借用了熔体升降的外观。"}]},"affixes":{"intro":{"en":"Lava has no Latin prefixes or suffixes of its own; it arrived as a whole dialect word, so the items below are compounds and borrowed combining forms rather than true affixes.","cn":"lava 没有自己的拉丁前缀或后缀；它作为一个完整的方言词传入，因此下列条目是复合形式与借入的组合成分，而非真正的词缀。"},"latinIntro":{"en":"No Latin entries are listed: lava is not inherited from Latin, and its possible Latin links are hypotheses rather than a derivational family.","cn":"此处不列拉丁词条：lava 并非由拉丁语继承而来，其可能的拉丁联系只是假说，而非一个派生词族。"},"items":[{"word":"lava","structure":"Neapolitan lava, 'torrent, stream'","meaning":"torrent; molten rock at the surface","meaningCN":"急流；地表的熔融岩石","example":"The word arrived whole, without a Latin prefix.","exampleCN":"这个词整体传入，没有拉丁前缀。"},{"word":"-a","structure":"Italian feminine noun ending","meaning":"noun ending, not a suffix of meaning","meaningCN":"名词词尾，不承载意义","example":"The final -a is an Italian noun ending, not an English suffix.","exampleCN":"词尾 -a 是意大利语的名词结尾，不是英语后缀。"},{"word":"lava flow","structure":"lava + flow (English compound)","meaning":"moving stream of lava","meaningCN":"流动的熔岩流","example":"The flow reached the road by noon.","exampleCN":"熔岩流在正午前抵达公路。"},{"word":"lava dome","structure":"lava + dome","meaning":"mound of viscous lava","meaningCN":"黏稠熔岩堆成的穹丘","example":"The dome cracked as it grew.","exampleCN":"穹丘在增长时开裂。"},{"word":"lava tube","structure":"lava + tube","meaning":"drained channel under a crust","meaningCN":"壳下排空的通道","example":"The tube held a cold river of air.","exampleCN":"管道里流着一股冷空气。"},{"word":"pillow lava","structure":"pillow + lava","meaning":"underwater bulbous lava","meaningCN":"水下形成的枕状熔岩","example":"Pillow lava records a submarine eruption.","exampleCN":"枕状熔岩记录了水下喷发。"},{"word":"lava lamp","structure":"lava + lamp","meaning":"decorative wax lamp","meaningCN":"装饰性蜡灯","example":"The lamp was a gift from a friend.","exampleCN":"这盏灯是朋友的礼物。"},{"word":"lavic","structure":"lava + -ic","meaning":"of or like lava","meaningCN":"熔岩的；似熔岩的","example":"Lavic deposits line the valley.","exampleCN":"谷底两侧分布着熔岩沉积。"},{"word":"molten","structure":"Old English molten, past participle of melt","meaning":"melted by heat","meaningCN":"熔化的","example":"Molten rock glows dull red.","exampleCN":"熔化的岩石发出暗红的光。"},{"word":"basalt","structure":"Latin basaltes, from Greek basanites","meaning":"dark fine-grained lava rock","meaningCN":"深色细粒的熔岩岩石","example":"Basalt forms most of the ocean floor.","exampleCN":"玄武岩构成大部分海底。"}],"latinEntries":[]}}]);
